-- Step 73, part 2 of 3: breeding guides (run part 1 first; it creates the table).

insert into public.breeding_guides
  (slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
select v.slug, a.id, v.species_slug, v.glossary_slug, v.seo_title, v.summary, v.intro, v.facts, v.sections, v.faq, v.society_tip
from (values
  ($g$acei-cichlid$g$, $g$c4d58855-5768-42fa-8cf1-a621160859df$g$::uuid, $g$acei-cichlid$g$, null, $g$How to Breed Acei Cichlids: Harems, Holding and Fry Care$g$, $g$Breeding acei is a beginner friendly mouthbrooder project: set up a harem, watch for a holding female, then raise 10 to 30 fry on spirulina foods.$g$, $g$Acei are one of the easiest Lake Malawi mouthbrooders to breed, and one of the calmer ones, so a harem in a 50 gallon tank often spawns with little help from you. The real work is sexing them, since males and females look alike, and keeping a holding female stress free for about three weeks. Seeing a female spit out a cloud of perfect miniature acei never gets old.$g$, $g${"method": "Maternal mouthbrooder (female holds eggs and fry)", "sexing": "Hard by color; males grow larger with longer fins and more egg spots. Venting is most reliable", "group": "1 male to 3 or 4 females", "breeding_tank": "50 gallons or more, rockwork caves, open swimming space, hard alkaline water", "conditioning": "2 to 3 weeks of spirulina flake and pellets, small amounts of protein", "trigger": "Stable water at 78 to 80°F, enough females to spread out the male's attention", "spawn": "Commonly 10 to 30 eggs, larger females can hold more", "eggs": "Held about 21 to 28 days at 78 to 80°F", "fry": "Released fully formed, about 3/8 inch, free swimming and feeding at once", "first_foods": "Baby brine shrimp, crushed spirulina flake, fine fry pellets", "grow_out": "About 1 inch in 2 to 3 months; colored and sellable around 1.5 to 2 inches", "parents": "No care after release; adults eat fry, so move the holding female or provide dense rock"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 50 gallon or larger tank suits a harem of acei. They grow to about 6 inches and like to swim in the open, so give them length and stack rockwork along the back with plenty of caves and gaps. Sand or fine gravel is fine.\n\nKeep the water like the rest of your Malawi tanks: 76 to 82°F, pH 7.8 to 8.6 and hard water with a GH of 10 to 25. For breeding, aim for the middle, around 78 to 80°F and pH 8.0 to 8.4. Strong filtration and weekly 30 to 50 percent water changes matter more than anything else here."}, {"heading": "Choosing and conditioning a harem", "text": "Males and females look almost identical, which is the main hurdle. Males usually grow larger, have longer pelvic and dorsal fins and show more and brighter egg spots on the anal fin, but none of that is foolproof. Venting a calm, netted fish is the most reliable method, or buy a group of 6 to 10 juveniles and let nature sort it out.\n\nThe best ratio is 1 male to 3 or 4 females. Feed a spirulina based flake or pellet two or three times a day in small amounts for 2 to 3 weeks. Acei are herbivores, so keep high protein foods as an occasional treat to avoid bloat."}, {"heading": "Spawning: what you will see", "text": "A ready male darkens and shakes in front of a female, leading her to a flat rock or cave. The pair circle, she lays a few eggs, picks them up in her mouth and nips at his egg spots, which helps fertilize them.\n\nThe giveaway afterward is a female with a swollen, boxy throat who refuses food and hides. Note the date so you can plan the release."}, {"heading": "Holding time", "text": "Females commonly hold for about 21 to 28 days at 78 to 80°F. You have two choices:\n\n- Leave her in the main tank if there is plenty of rockwork and the male is not harassing her. Some fry survive in the rocks, but many get eaten.\n- Move her gently to a 10 to 20 gallon tank with the same water about a week into holding. Moving her too early is the most common cause of spitting.\n\nSome breeders strip the fry by hand once they are well developed. If you do, use clean, matched water and be gentle. Most beginners do better letting her release naturally."}, {"heading": "Raising the fry", "text": "Fry come out about 3/8 inch long and eat right away. Week 1: baby brine shrimp and finely crushed spirulina flake twice a day. Weeks 2 to 4: add fry pellets and keep up the brine shrimp. Hold the fry tank at 78 to 80°F and change 25 to 50 percent of the water two or three times a week with matched water. A sponge filter is ideal.\n\nReturn the female to the harem after a few days of rest and good food so she can regain condition."}, {"heading": "Growing out", "text": "Expect fry to reach about 1 inch in 2 to 3 months and 1.5 to 2 inches in 4 to 5 months with good feeding and frequent water changes. Move them to a larger grow out tank as they grow, since crowding slows growth and raises aggression. Shift the diet toward spirulina pellets as they get bigger.\n\nYoung males start to show longer fins and stronger egg spots at around 2 inches, which is a good time to start sorting them if you plan to sell or trade groups."}, {"heading": "Common mistakes", "text": "- Buying adults without venting and ending up with all males or all females.\n- Moving a holding female in the first few days, which causes her to spit the eggs.\n- Feeding rich protein foods every day and causing bloat.\n- Overcrowding fry and skipping water changes, which stunts growth."}]$g$::jsonb, $g$[{"q": "How long do acei hold their eggs?", "a": "Most female acei hold for about 3 to 4 weeks at 78 to 80°F. Cooler water stretches the time a little."}, {"q": "How can you tell male and female acei apart?", "a": "It is hard by looks alone. Males tend to be larger with longer fins and more egg spots, but venting is the most reliable way to be sure."}, {"q": "How many fry does an acei have?", "a": "A typical brood is around 10 to 30 fry. Young females hold fewer, and big, mature females can hold more."}, {"q": "Will acei eat their own fry?", "a": "Yes, adults in the main tank will eat fry they can catch. Moving the holding female or growing the fry out in a separate tank gives you the most survivors."}]$g$::jsonb, $g$Open your log before the harem spawns and get a clear stage 1 photo of the male and females with your challenge code card. For stage 2, a side photo of the female's full, swollen throat is good evidence of a spawn.$g$),
  ($g$african-butterfly-cichlid$g$, $g$892aefb3-56e3-4c37-83b4-942488713c58$g$::uuid, $g$african-butterfly-cichlid$g$, null, $g$How to Breed African Butterfly Cichlids: Pairs and Fry$g$, $g$African butterfly cichlids are gentle substrate spawners that lay hundreds of eggs on stones; a bonded pair in soft water is the key to success.$g$, $g$The African butterfly cichlid is a peaceful little West African cichlid that pairs up, cleans a flat stone and raises a cloud of fry together. Getting a true pair is the main challenge because the sexes look so similar, but once they bond they spawn regularly. Watching both parents herd and guard hundreds of tiny fry is a real treat for anyone stepping up from livebearers.$g$, $g${"method": "Substrate spawner (open spawner on flat stones or leaves)", "sexing": "Difficult; females are often smaller and rounder. Best to raise a group and let pairs form", "group": "One bonded pair", "breeding_tank": "20 gallons, flat stones, plants, soft slightly acidic water", "conditioning": "2 weeks of frozen bloodworms, brine shrimp and quality flake", "trigger": "Soft water near 6.5, temperature raised to about 79 to 81°F, water changes", "spawn": "Commonly 100 to 500 eggs", "eggs": "Hatch in about 2 to 3 days at 79 to 81°F", "fry": "Free swimming about 4 to 6 days after hatching; very small", "first_foods": "Infusoria or liquid fry food, then baby brine shrimp and microworms", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Both parents guard well; first spawns are often eaten, which usually stops with experience"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank is enough for one pair. Add a few flat stones or slate pieces, some broad leaved plants, a sponge filter and a soft sand or fine gravel bottom where the parents can dig pits for the wrigglers. Dim lighting and a few floating plants help them feel secure.\n\nThe site's care range for this fish is 73 to 81°F, pH 6 to 7.5 and GH 3 to 12. For spawning, aim for the softer, warmer end: around 79 to 81°F, pH 6.5 to 7 and a GH under about 8."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing is genuinely difficult. Females are often a little smaller and plumper, and males may grow slightly longer fin extensions, but neither is reliable. The surest route is to buy 6 juveniles, grow them up together and watch for two fish that stake out a stone and chase others away. Move that pair to the breeding tank.\n\nFeed small meals of frozen bloodworms, brine shrimp, daphnia and a good flake two or three times a day for about 2 weeks. Do a 25 percent water change a few times that week; fresh, slightly softer water at the warm end of the range often sets them off."}, {"heading": "Spawning: what you will see", "text": "The pair will clean a flat stone or leaf for a day or two, nipping it spotless. The female then makes passes over it laying rows of small eggs, with the male following to fertilize them. A spawn of 100 to 500 eggs is commonly reported.\n\nBoth parents take turns fanning the eggs and chasing off anything that comes close."}, {"heading": "Eggs and fungus prevention", "text": "Eggs hatch in about 2 to 3 days at 79 to 81°F. The parents remove any white, fungused eggs themselves. Once the eggs hatch, the parents move the wriggling larvae into pits dug in the sand and may shift them between pits several times.\n\nIf the pair keeps eating eggs, you can move the stone to a separate tank with an air stone and a drop of methylene blue, but most breeders find that new pairs settle down after one or two tries."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 4 to 6 days after hatching, and they are tiny. Week 1: infusoria, green water or a liquid fry food several times a day, plus very fine powdered food. Week 2: add microworms and newly hatched brine shrimp. From week 3, crushed flake joins the menu.\n\nKeep the tank at 78 to 80°F and change 20 to 30 percent of the water every 2 to 3 days with matched soft water. The parents will herd the fry for several weeks; remove the fry if the parents start spawning again."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Spread them out in a larger tank, keep feeding brine shrimp and quality flake, and keep the water clean and soft. They start showing adult colors at around 1.5 inches.\n\nButterfly cichlids are peaceful enough that young ones can share a grow out tank with other small, gentle fish, but they grow faster and color up better without competition at feeding time. Keep a few of the best ones back to raise your next pair."}, {"heading": "Common mistakes", "text": "- Water that is too hard, which can lower hatch rates.\n- Giving up after a pair eats its first one or two spawns.\n- Feeding the free swimming fry baby brine shrimp only; many are too small for it the first few days.\n- Not separating the fry when the pair is ready to spawn again."}]$g$::jsonb, $g$[{"q": "Are African butterfly cichlids easy to breed?", "a": "Yes, they are among the easier West African cichlids once you have a real pair. Soft, clean water and good conditioning are the main needs."}, {"q": "How do you sex African butterfly cichlids?", "a": "It is hard. Females are often smaller and rounder, but the best way is to grow a group of juveniles and let them pair off."}, {"q": "How many eggs do African butterfly cichlids lay?", "a": "Clutches of about 100 to 500 eggs are commonly reported, laid on a flat stone or leaf."}, {"q": "Do African butterfly cichlids eat their eggs?", "a": "Young pairs sometimes eat their first spawns. Most settle down with practice and become devoted parents."}]$g$::jsonb, $g$Photograph the bonded pair beside their cleaned stone with your challenge code card for stage 1, then a close shot of the eggs on the stone for stage 2. The fry hatch quickly, so keep the camera ready for the free swimming stage.$g$),
  ($g$auratus-cichlid$g$, $g$60e430a3-597e-4a6f-a3ec-0f0c3e8a3710$g$::uuid, $g$auratus-cichlid$g$, null, $g$How to Breed Auratus Cichlids: Harem Setup and Fry Care$g$, $g$Auratus breed readily as mouthbrooders, but their aggression is the challenge; use a large harem tank and expect 15 to 30 fry per brood.$g$, $g$Auratus are one of the easiest mbuna to breed, and one of the most aggressive. The good news is that sexing adults is easy, because dominant males turn dark brown to black with gold stripes while females stay yellow. The challenge is giving the male enough tank and enough females that nobody gets hurt while a female holds her eggs for about three weeks.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Easy in adults: males go dark brown to black with gold stripes, females stay yellow", "group": "1 male to 4 or more females", "breeding_tank": "50 gallons or more, lots of rock caves, hard alkaline water", "conditioning": "2 to 3 weeks of quality flake and pellets with spirulina and some protein", "trigger": "Stable water at 78 to 80°F, plenty of females and rock cover", "spawn": "Commonly 15 to 30 eggs", "eggs": "Held about 3 weeks (around 21 days) at 78 to 80°F", "fry": "Released free swimming, about 3/8 inch, striped yellow like the females", "first_foods": "Baby brine shrimp, crushed flake and fine fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so isolate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Auratus are small, about 4.5 inches, but very aggressive. A 50 gallon tank is the minimum the site lists, and bigger is better. Stack rocks into many caves so females can break line of sight. Sand or fine gravel and strong filtration finish it.\n\nKeep the water at 76 to 82°F, pH 7.8 to 8.6 and GH 10 to 25, aiming for about 78 to 80°F for breeding. Change 30 to 50 percent of the water weekly.\n\nIf you can, use a dedicated species tank. A busy mixed mbuna tank adds stress, raises the odds of holding females being harassed and makes it easier for the male to cross with a similar looking female of another species."}, {"heading": "Choosing and conditioning a harem", "text": "Adult sexing is simple. Dominant males change from yellow to dark brown or black with yellow to gold stripes. Females and young fish stay yellow with black and white stripes. Note that a subordinate male may stay in female coloring, so do not assume every yellow fish is female.\n\nKeep only one male, with at least 4 females. Feed an omnivore flake or pellet with spirulina, plus occasional small portions of brine shrimp or mysis, twice daily for 2 to 3 weeks. Females that are well fed and not constantly chased fill out with eggs faster and hold more reliably.\n\nFemales can be ready to spawn at around 2 to 2.5 inches, so a group of young fish often starts breeding sooner than you expect."}, {"heading": "Spawning: what you will see", "text": "The male darkens even more, shakes and leads a female to a flat spot in his territory. She lays a few eggs at a time and picks them up in her mouth, then nips at his anal fin to fertilize them. Spawning can last an hour or more.\n\nAfterward the female will have a full throat, stop eating and hide in the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 weeks at 78 to 80°F. Auratus males often harass holding females, so most breeders move her after about a week to a 10 to 20 gallon tank with matched water and a cave. Net her gently and avoid chasing her around the tank, or she may spit the eggs.\n\nSome breeders strip well developed fry by hand. For beginners, letting her release naturally in her own tank is safer."}, {"heading": "Raising the fry", "text": "Fry are released free swimming at about 3/8 inch. Remove the female once she releases them and give her a week or so to recover before returning her to the harem.\n\nWeek 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Even young auratus squabble, so give them space and rockwork as they grow. Young males start turning dark at around 2 to 3 inches, which is also when they start fighting in earnest.\n\nFeed the fry three or four small meals a day if you can, and keep up the frequent water changes. Sort out obvious males as they color, since a single growing male will start bullying his tankmates. Groups of young fish are easiest to rehome or sell at about 1.5 to 2 inches, before males fully color and turn on each other."}, {"heading": "Common mistakes", "text": "- Keeping two males, or one male with only one or two females.\n- Leaving a holding female with a harassing male.\n- Mixing auratus with similar mbuna, which can lead to hybrids. Breed them in a species tank.\n- Assuming a yellow fish is a female; young males stay yellow for a while."}]$g$::jsonb, $g$[{"q": "How can you tell male and female auratus apart?", "a": "Adult males turn dark brown to black with gold stripes, while females stay yellow with black stripes. Young males look like females until they mature."}, {"q": "How long do auratus hold their eggs?", "a": "Female auratus usually hold for around 3 weeks at 78 to 80°F before releasing free swimming fry."}, {"q": "How many babies do auratus have?", "a": "A brood is commonly 15 to 30 fry, depending on the size of the female."}, {"q": "Why is my auratus male killing females?", "a": "Usually there are too few females or not enough rock cover. Add more females and caves, or move him out for a while."}]$g$::jsonb, $g$Get the dark male and his yellow females in your stage 1 photo with the challenge code card. For stage 2, a clear photo of a female with a full, puffed out throat is good evidence.$g$),
  ($g$brichardi$g$, $g$354d85e5-2131-49a0-8dc1-ddc293c3d692$g$::uuid, $g$brichardi$g$, null, $g$How to Breed Brichardi: Fairy Cichlid Pairs, Caves and Fry$g$, $g$Brichardi are Tanganyikan cave spawners that raise fry as a family; finding a true pair is the hard part, then the colony grows on its own.$g$, $g$Breeding brichardi is like starting a small village. Once a pair forms, they spawn in a cave every few weeks and older fry help guard their younger siblings, so the tank slowly fills with generations of these graceful lyre tailed fish. The tricky part is getting a pair, since males and females look nearly identical, but after that they are some of the most rewarding Tanganyikan cichlids to keep.$g$, $g${"method": "Cave spawner; family groups where older young help guard", "sexing": "Very hard by looks; males are often slightly larger with longer fin streamers. Venting helps", "group": "One pair, ideally picked from a group of 6 juveniles", "breeding_tank": "30 gallons or more, rock caves, sand, hard alkaline water", "conditioning": "2 weeks of frozen brine shrimp, mysis, daphnia and quality flake", "trigger": "A settled pair with a secure cave and stable water around 78 to 80°F", "spawn": "Commonly dozens of eggs, up to about 200 in large females", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming roughly 7 to 10 days after spawning, staying close to the cave", "first_foods": "Baby brine shrimp, microworms and finely crushed flake", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Both parents guard; fry can stay, and older siblings help defend the brood"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank works for one pair, and a 40 gallon breeder or larger gives the colony room to grow. Build stable rock piles with many small caves and crevices on a sand bottom. Add a few extra caves away from the main one, because older fry and young adults need places to retreat.\n\nKeep the water at 75 to 81°F, pH 8 to 9 and GH 10 to 25, as listed in the site's care data. For breeding, about 78 to 80°F and pH 8.5 works well. Tanganyikans like very clean, stable water, so change 20 to 30 percent weekly rather than doing large, sudden changes."}, {"heading": "Getting a pair", "text": "Brichardi are among the hardest cichlids to sex by eye. Males are often a little larger and may grow longer streamers on the tail and fins, but females can look the same. Venting is possible but takes practice on small fish.\n\nThe easy route is to raise a group of 6 juveniles together. When a pair forms, they claim a cave and chase the others. Remove the extra fish quickly, because a bonded pair can kill tankmates in a confined space.\n\nFeed small meals of frozen brine shrimp, mysis, daphnia and a good flake or small pellet twice a day."}, {"heading": "Spawning: what you will see", "text": "Spawning happens out of sight, usually on the ceiling or wall of a cave. You may notice the female spending all her time inside and the male patrolling the entrance more fiercely than usual. A clutch is commonly dozens of eggs, up to about 200 from a large female.\n\nDo not move rocks to look. The pair will usually handle everything."}, {"heading": "Eggs and the first days", "text": "The eggs hatch in about 2 to 3 days at 78 to 80°F. The wrigglers stay in the cave while they absorb their yolk, and you will first see tiny fry at the cave mouth roughly 7 to 10 days after spawning.\n\nFungus is rarely a problem with brichardi, since the female cleans the eggs. If eggs keep disappearing, it is usually a young pair or a stressed one, and they often get it right after a few tries."}, {"heading": "Raising the fry", "text": "Brichardi fry are best raised with their parents. Week 1: baby brine shrimp and microworms once or twice a day, squirted near the cave with a pipette. Week 2 onward: add finely crushed flake and powdered fry food. Keep the temperature steady and do small, regular water changes of around 20 percent twice a week, siphoning uneaten food.\n\nThe pair will spawn again every few weeks. Older juveniles usually stay and help defend the newest fry, which is the classic brichardi family behavior."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. The colony can stay together until the tank gets crowded or young males begin to fight with the parents, usually once the oldest young reach adult size. At that point, move some of the older juveniles to a grow out tank. If the parents start chasing a particular group of young, take them out quickly.\n\nJuveniles do well on baby brine shrimp, crushed flake and small frozen foods such as cyclops and daphnia. By 2 inches they look like small adults, with the white edged fins and lyre shaped tail. Keep a few pairs worth of young fish back if you want to start a second colony later."}, {"heading": "Common mistakes", "text": "- Adding a pair to a small community tank, where they bully or kill tankmates.\n- Leaving extra adults in once a pair has formed.\n- Moving the rockwork to check for eggs.\n- Big swings in pH or temperature from large, unmatched water changes.\n- Expecting to see the spawn. Brichardi are secretive, so patience and close watching of the cave mouth are key."}]$g$::jsonb, $g$[{"q": "Do brichardi eat their fry?", "a": "Generally no. Brichardi parents guard their fry, and older siblings help. Problems usually only come when the tank gets overcrowded."}, {"q": "How do you tell male and female brichardi apart?", "a": "It is very difficult. Males may be larger with longer fin streamers, but the reliable approach is to raise a group and let a pair form, or vent them."}, {"q": "How often do brichardi breed?", "a": "A settled pair often spawns every few weeks, so a tank can hold several sizes of young at once."}, {"q": "How many eggs do brichardi lay?", "a": "Clutches of dozens of eggs are typical, and large females can lay up to about 200."}]$g$::jsonb, $g$Brichardi spawn out of sight, so for stage 2 a photo of the female guarding the cave entrance is less convincing than one of eggs or wrigglers. Many breeders wait and use the first fry at the cave mouth, so open your stage 1 log early with the pair and challenge code card in frame.$g$),
  ($g$egyptian-mouthbrooder$g$, $g$ec0efb09-dbea-47e2-b2e1-e32b72068a29$g$::uuid, null, null, $g$How to Breed Egyptian Mouthbrooders: A Simple Fry Guide$g$, $g$Egyptian mouthbrooders are small, hardy maternal mouthbrooders; a colorful male and a few females in a 20 gallon tank usually breed with ease.$g$, $g$The Egyptian mouthbrooder is a small, hardy African cichlid that is a perfect first mouthbrooder. Males are easy to spot, the fish are not fussy about water, and females hold their eggs for less time than most Malawi cichlids. The best part is watching the mother call her fry back into her mouth when danger threatens, something you rarely get to see so clearly.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Easy: males are colorful with an orange to red tip on the anal fin; females are plain tan", "group": "1 male to 2 or 3 females", "breeding_tank": "20 gallons, sand to dig, rocks and plants for cover", "conditioning": "1 to 2 weeks of frozen bloodworms, brine shrimp and quality flake", "trigger": "A male digging a pit and displaying, with well fed females nearby", "spawn": "Commonly 30 to 100 eggs", "eggs": "Held about 10 to 14 days at 77 to 80°F", "fry": "Released free swimming, often taken back into the mother's mouth for a few more days", "first_foods": "Baby brine shrimp from the first day, plus crushed flake", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Mother guards fry for several days after release; males and other fish will eat them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank suits one male and two or three females. These are small fish, around 3 inches, but males are territorial. Use a sand bottom, since the male digs a spawning pit, plus some rocks and sturdy plants to give females places to hide.\n\nEgyptian mouthbrooders are adaptable. Breeders commonly keep them at around 72 to 80°F with a pH near neutral to slightly alkaline, roughly 7 to 8, and moderate hardness. For breeding, aim for about 77 to 80°F. A sponge or gentle filter and weekly 25 to 30 percent water changes keep things clean."}, {"heading": "Choosing and conditioning a group", "text": "Sexing is easy in adults. Males are colorful, with shimmering green, blue and yellow scales and a bright orange to red spot on the tip of the anal fin. Females are mostly plain tan to brown.\n\nKeep one male with two or three females to spread out his attention. Condition for 1 to 2 weeks on frozen bloodworms, brine shrimp, daphnia and a good flake, fed in small amounts twice a day. Females fill out noticeably when they are ready."}, {"heading": "Spawning: what you will see", "text": "The male digs a shallow pit in the sand and displays at passing females, flaring his fins and shaking. When a female joins him, she lays eggs in the pit, picks them up in her mouth and then mouths at the male's anal fin spot, which is when fertilization takes place.\n\nClutches of about 30 to 100 eggs are commonly reported. After spawning, she hides with a full throat and stops eating."}, {"heading": "Holding time", "text": "Females usually hold for about 10 to 14 days at 77 to 80°F, which is quicker than most Lake Malawi mouthbrooders. You can move her to her own 10 gallon tank after a few days of holding, netting her gently to avoid spitting. A tank with a few plants and a sponge filter is ideal.\n\nAfter she releases the fry, she will guard them for several more days and take them back into her mouth if she senses danger."}, {"heading": "Raising the fry", "text": "The fry are big enough to eat baby brine shrimp from the first day. Week 1: baby brine shrimp twice a day and a little finely crushed flake. Week 2: add microworms or crushed fry pellets. Week 3 onward: crushed flake and small frozen foods.\n\nRemove the mother once the fry stop returning to her mouth, usually within about a week of release, and give her a week of good food before returning her to the male. Keep the fry at about 78°F and change 25 to 30 percent of the water every few days."}, {"heading": "Growing out", "text": "Fry grow quickly, reaching about 1 inch in 2 to 3 months. Young males begin to show color at about 1.5 inches. They are peaceful enough to grow out together until the males start sparring, at which point it is time to split them up or move them on.\n\nFeed growing fry three or four small meals a day of baby brine shrimp, crushed flake and small frozen foods such as daphnia. Keep up the water changes, and spread them across more space as they grow. Females are ready to breed at a surprisingly small size, often well under 2 inches."}, {"heading": "Common mistakes", "text": "- Keeping two males in a small tank, which leads to constant fighting.\n- Moving a holding female in the first day or two, causing her to spit.\n- Removing the mother right after release, before she has finished guarding.\n- Overfeeding the fry tank and letting water quality slip.\n- Keeping them with large or aggressive fish, which stresses holding females into spitting."}]$g$::jsonb, $g$[{"q": "How long do Egyptian mouthbrooders hold their eggs?", "a": "Females usually hold for about 10 to 14 days at 77 to 80°F, then keep guarding the fry for several days after release."}, {"q": "How do you sex Egyptian mouthbrooders?", "a": "Males are colorful with an orange to red tip on the anal fin. Females are plain tan to brown."}, {"q": "How many babies do Egyptian mouthbrooders have?", "a": "A brood of about 30 to 100 fry is commonly reported, depending on the female's size."}, {"q": "Are Egyptian mouthbrooders good for beginners?", "a": "Yes. They are hardy, adaptable and breed readily in a small species tank."}]$g$::jsonb, $g$Because these females hold for only about 2 weeks, open your log and take the stage 1 photo with the challenge code card before you see a holding female. A photo of the mother with fry swimming back into her mouth makes a great stage 3 shot.$g$),
  ($g$maingano-cichlid$g$, $g$96e7b338-435f-4c39-96c4-9c0f3d6bd4ff$g$::uuid, $g$maingano-cichlid$g$, null, $g$How to Breed Electric Blue Johanni (Maingano Cichlids)$g$, $g$Electric blue johanni are easy mouthbrooders with small broods; sexing is tricky, so start with a group and expect 10 to 20 fry per spawn.$g$, $g$The electric blue johanni, often sold as maingano, is a small, striking mbuna that breeds readily in a well set up group. Males and females look much alike, so the main challenge is building a group with one male and several females. Broods are small, but females spawn often, and the dark blue and black striped fry are miniature copies of their parents from the day they are released.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Hard: both sexes are blue with black stripes; males are often larger. Venting is most reliable", "group": "1 male to 3 or 4 females", "breeding_tank": "55 gallons or more, many rock caves, hard alkaline water", "conditioning": "2 weeks of quality flake and pellets with spirulina and some protein", "trigger": "Stable water at 78 to 80°F and enough females to spread out aggression", "spawn": "Small broods, commonly 10 to 20 eggs", "eggs": "Held about 3 to 4 weeks at 78 to 80°F", "fry": "Released free swimming, already blue and striped", "first_foods": "Baby brine shrimp, crushed flake and fine fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so separate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 55 gallon minimum for this species, and that suits a group of one male and three or four females, with or without other mbuna of different shapes and colors. Stack rocks into caves, give them a sand bottom, and leave some open water.\n\nKeep the water at 76 to 82°F, pH 7.6 to 8.6 and GH 10 to 20. For breeding, about 78 to 80°F and pH 8 to 8.4 works well. Change 30 to 50 percent of the water each week."}, {"heading": "Building a breeding group", "text": "Sexing electric blue johanni is not easy. Both sexes are the same blue with black horizontal stripes. Males often grow larger and may show slightly brighter color or more egg spots on the anal fin, but these signs are not reliable. Venting is the best way to be sure, or buy 6 to 8 juveniles and remove extra males as they become obvious by their behavior.\n\nDo not keep them with other blue and black striped mbuna such as johanni types or auratus, since mixed similar species may hybridize. Condition the group on a spirulina based flake or pellet with occasional small portions of mysis or brine shrimp for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The male intensifies his color, shakes and leads a female into his territory. As with other mbuna, she lays a few eggs at a time, takes them into her mouth and mouths at his anal fin to fertilize them. Broods are small, commonly 10 to 20 eggs.\n\nA holding female has a bulging throat, stops eating and keeps to the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Move her after about a week, gently, to a 10 to 20 gallon tank with the same water and a cave or two. Netting her in the first few days often causes her to spit.\n\nWhen she releases the fry, remove her and give her a week or two of good feeding before returning her to the group, so she can rebuild her condition."}, {"heading": "Raising the fry", "text": "The fry are released already free swimming and colored like the adults. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F, use a sponge filter and change 25 to 50 percent of the water two or three times a week."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months and around 2 inches by 5 to 6 months. They remain small as adults, around 3.5 inches. Grow them out in a tank with some rockwork so the weaker ones can escape. Young males start to show territorial behavior at about 2 inches, which is a good time to pick out the best ones to keep or sell.\n\nFeed young fish three or four small meals a day if you can, with spirulina flake as the base and baby brine shrimp or daphnia as extras. Frequent water changes do more for growth than any food. Sort the fry by size if a few start to outgrow the others, as large siblings can bully smaller ones away from food."}, {"heading": "Common mistakes", "text": "- Building a group without venting and ending up with too many males.\n- Keeping them with similar blue and black striped mbuna.\n- Moving the holding female too early.\n- Returning a female to the group before she has recovered her weight."}]$g$::jsonb, $g$[{"q": "How do you tell male and female electric blue johanni apart?", "a": "They look very similar. Males may be larger with more egg spots, but venting is the only reliable method."}, {"q": "How many fry do electric blue johanni have?", "a": "Broods are small, commonly about 10 to 20 fry."}, {"q": "How long do electric blue johanni hold their eggs?", "a": "Females hold for about 3 to 4 weeks at 78 to 80°F."}, {"q": "Is maingano the same fish as electric blue johanni?", "a": "Yes. Melanochromis cyaneorhabdos is sold under both names, and it is a different fish from Melanochromis johannii."}]$g$::jsonb, $g$Since the sexes look alike, include the whole group in your stage 1 photo with the challenge code card and note which fish you vented as males. Broods are small, so count and photograph the fry clearly at each grow out stage.$g$),
  ($g$jewel-cichlid$g$, $g$1782e3c6-6f76-4802-8cc5-ebe0b3a6bfcc$g$::uuid, $g$jewel-cichlid$g$, null, $g$How to Breed Jewel Cichlids: Safe Pairing and Raising Fry$g$, $g$Jewel cichlids are devoted substrate spawners that lay hundreds of eggs; the challenge is pairing safely, then the parents do most of the work.$g$, $g$Jewel cichlids are some of the best parents in the hobby. A bonded pair turns brilliant red, cleans a flat rock, lays hundreds of eggs and guards the fry with real ferocity. The hard part is forming a pair safely, because jewels can be brutal to a partner that is not ready. Get that right and they will spawn again and again.$g$, $g${"method": "Substrate spawner on cleaned flat rocks", "sexing": "Hard; males are often larger. Pairs color up strongly when breeding. Let pairs form naturally", "group": "One bonded pair", "breeding_tank": "30 gallons, flat stones, caves, divider ready in case of fighting", "conditioning": "2 weeks of frozen bloodworms, brine shrimp, mysis and pellets", "trigger": "A bonded pair, warmer water around 80°F and regular water changes", "spawn": "Commonly 200 to 500 eggs", "eggs": "Hatch in about 2 to 3 days at 80°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Baby brine shrimp and microworms, then crushed flake", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Both parents guard intensely; they may attack anything in the tank, including you"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank is a good size for one pair. Provide several flat stones or slate pieces for spawning, a cave or two and a fine sand or gravel bottom. Plants may get dug up, so use hardy ones attached to wood or rocks.\n\nThe site lists jewels at 70 to 82°F, pH 6.5 to 7.5 and GH 5 to 18. For breeding, keep the temperature around 78 to 80°F and the pH near neutral. A sponge filter is safest for fry, and weekly 30 percent water changes keep the pair in spawning shape."}, {"heading": "Choosing and pairing", "text": "Sexing jewels is unreliable by looks. Males are often slightly larger, and both sexes turn deep red with blue spangles when breeding. The safest way to get a pair is to raise 6 juveniles together and remove the others once two fish start guarding a spot together.\n\nJewels can kill a partner that is not ready to spawn. If you put an adult pair together, keep a tank divider handy and watch closely for the first few days. Torn fins or a hiding fish mean you should separate them.\n\nCondition the pair on frozen bloodworms, brine shrimp, mysis and a quality pellet twice a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "A ready pair colors up dramatically, with the red deepening and blue spots glowing. They clean a flat stone for a day or two, then the female lays rows of eggs while the male follows to fertilize. Clutches of 200 to 500 eggs are commonly reported, and large females can lay more.\n\nFrom this point, both parents attack anything that comes near."}, {"heading": "Eggs and fungus prevention", "text": "The eggs hatch in about 2 to 3 days at around 80°F. The parents fan the eggs and pick out any that turn white with fungus. Once hatched, they move the wrigglers to pits dug in the sand.\n\nIf a young pair eats the eggs, give them a few more chances. You can also move the stone to a separate tank with an air stone and a small dose of methylene blue, but you lose the parental care that makes jewels so fun to watch."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 5 days after hatching, and the parents herd them around the tank in a tight cloud. Week 1: baby brine shrimp and microworms two or three times a day. Week 2: add finely crushed flake. Week 3 onward: crushed pellets and small frozen foods.\n\nKeep the tank at 78 to 80°F and change 20 to 30 percent of the water every few days, siphoning carefully around the parents. When the pair starts cleaning a stone again, usually after 3 to 6 weeks, move the fry out."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months with good feeding. They grow fast but become territorial early, so spread them across a larger grow out tank with rocks and hiding spots. Sell or rehome them in groups before they pair off and start fighting.\n\nFeed growing jewels three small meals a day of crushed pellets, flake and frozen foods such as brine shrimp and bloodworms. They color up from about 1.5 inches, though the deepest reds come with maturity. Change 30 to 50 percent of the grow out water weekly; jewels are messy eaters and grow fastest in clean water."}, {"heading": "Common mistakes", "text": "- Forcing a random male and female together without a divider.\n- Keeping other fish in the breeding tank, which the parents may kill.\n- Leaving older fry in when the parents spawn again.\n- Assuming the brightest fish is the male; females color up strongly too."}]$g$::jsonb, $g$[{"q": "Do jewel cichlids eat their babies?", "a": "Usually not. Jewels are protective parents, though a new pair may eat the first few spawns before they settle down."}, {"q": "How do you sex jewel cichlids?", "a": "It is difficult by looks. Males are often a little larger, but the best method is to let a pair form from a group of juveniles."}, {"q": "How many eggs do jewel cichlids lay?", "a": "A clutch of 200 to 500 eggs is commonly reported, laid on a cleaned flat stone."}, {"q": "Why did my jewel cichlid kill its mate?", "a": "Jewels can be very aggressive to a partner that is not ready to spawn. Use a divider until both fish show breeding behavior."}]$g$::jsonb, $g$Get the pair in your stage 1 photo with the challenge code card before they spawn, since they become very defensive after. A shot of the parents fanning eggs on the stone is clear stage 2 evidence.$g$),
  ($g$kenyi-cichlid$g$, $g$9d1dd3f6-dc26-446e-b758-0a479b91fbef$g$::uuid, $g$kenyi-cichlid$g$, null, $g$How to Breed Kenyi Cichlids: Harem Setup and Mouthbrooding$g$, $g$Kenyi cichlids breed easily as mouthbrooders and sex by color, males yellow and females blue; aggression is the real challenge in a harem.$g$, $g$Kenyi are one of the easiest mbuna to breed, and one of the easiest to sex, because adult males turn yellow to orange while females stay blue with dark bars. The catch is aggression. A male kenyi can be relentless, so success depends on a big enough tank, plenty of rock caves and several females. Do that and you will have holding females every few weeks.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Easy in adults: males turn yellow to orange; females and juveniles are blue with dark bars", "group": "1 male to 3 or 4 females", "breeding_tank": "55 gallons or more, many rock caves, hard alkaline water", "conditioning": "2 weeks of spirulina flake and pellets with small amounts of protein", "trigger": "Stable water at 78 to 80°F with enough females and cover", "spawn": "Commonly 10 to 30 eggs", "eggs": "Held about 3 weeks (often 21 to 28 days) at 78 to 80°F", "fry": "Released free swimming, about 3/8 inch, blue like the females", "first_foods": "Baby brine shrimp, crushed spirulina flake and fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so isolate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 55 gallon minimum for kenyi, and that is the place to start. They grow to about 5 inches and males are very aggressive. Stack rocks into many caves and crevices along the full length of the tank so females can escape.\n\nKeep the water at 76 to 82°F, pH 7.6 to 8.6 and GH 10 to 20. Aim for 78 to 80°F for breeding, and change 30 to 50 percent of the water weekly. Strong filtration helps, as mbuna tanks get heavily stocked."}, {"heading": "Choosing and conditioning a harem", "text": "Kenyi sex by color, which is unusual among mbuna. Mature males turn yellow to orange, often with a few faint bars. Females and juveniles stay pale blue with dark vertical bars. Young males are blue at first and change color as they mature, usually at about 2 to 3 inches.\n\nKeep one male with three or four females. Kenyi are herbivores, so feed a spirulina based flake or pellet twice a day, with protein foods only as a small treat. Avoid keeping them with other blue barred Maylandia, as they can hybridize."}, {"heading": "Spawning: what you will see", "text": "The male brightens, shakes and leads a female to a spot near his cave. She lays a few eggs at a time, picks them up and mouths at the egg spots on his anal fin to fertilize them. A typical clutch is about 10 to 30 eggs.\n\nAfterward she hides with a bulging throat and refuses food."}, {"heading": "Holding time", "text": "Females hold for about 3 weeks, often 21 to 28 days at 78 to 80°F. Holding females eat very little, so a well conditioned female going in makes a big difference to how well she holds.\n\nKenyi males harass holding females, so most breeders move her after about a week to a 10 to 20 gallon tank with matched water and a cave. Move her gently and avoid chasing her.\n\nSome breeders strip the fry once they are well developed, but letting her release naturally is the safer choice for beginners."}, {"heading": "Raising the fry", "text": "Fry are released about 3/8 inch long and can eat right away. Week 1: baby brine shrimp and finely crushed spirulina flake twice a day. Weeks 2 to 4: add fry pellets. Keep the tank at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRemove the female after release and feed her well for a week or two before returning her to the male."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Give them space and rockwork as they grow, because even young kenyi squabble. At about 2 to 3 inches, young males start turning yellow, and you will need to split them up or move them on before they fight.\n\nFeed growing fry three or four small meals a day, with spirulina flake and pellets as the base. Kenyi are herbivores, so avoid rich protein foods beyond baby brine shrimp in the first weeks. Frequent water changes do more for growth than extra food. Sort out the largest fish if they start bullying their smaller siblings."}, {"heading": "Common mistakes", "text": "- Keeping kenyi in a tank that is too small, which leads to injured or dead females.\n- Keeping two males together.\n- Mixing them with similar blue barred mbuna and getting hybrids.\n- Leaving a holding female with the male.\n- Feeding high protein foods every day, which can cause bloat in these herbivores."}]$g$::jsonb, $g$[{"q": "How can you tell male and female kenyi apart?", "a": "Adult males are yellow to orange, while females and young fish are blue with dark vertical bars."}, {"q": "How long are kenyi cichlids pregnant?", "a": "Kenyi are mouthbrooders rather than pregnant. Females hold the eggs and fry for about 3 weeks, often 21 to 28 days."}, {"q": "How many fry do kenyi cichlids have?", "a": "Broods are commonly about 10 to 30 fry."}, {"q": "Why is my kenyi so aggressive?", "a": "Male kenyi are naturally aggressive. A larger tank, more females and plenty of rock caves help spread the aggression."}]$g$::jsonb, $g$Include the yellow male and his blue females in your stage 1 photo with the challenge code card. Kenyi fry look like the females, so note the date of release in your log and keep the fry in their own tank to make the grow out counts easy.$g$),
  ($g$multifasciatus-shell-dweller$g$, $g$44983248-e527-4e25-b26c-76b48b6a3e64$g$::uuid, $g$multifasciatus-shell-dweller$g$, null, $g$How to Breed Multies: Shell Dweller Colonies Made Simple$g$, $g$Multies are tiny Tanganyikan shell dwellers that breed as a colony in empty snail shells; give them sand, lots of shells and time, and fry follow.$g$, $g$Neolamprologus multifasciatus, usually called multies, are among the smallest cichlids in the world, and a colony of them is one of the most entertaining tanks you can keep. They spawn inside empty snail shells, guard their young as a group, and slowly turn a few fish into a busy little town. Breeding them is mostly about setting the tank up right and then leaving them alone.$g$, $g${"method": "Shell dwelling cave spawner; colonial, eggs laid inside empty snail shells", "sexing": "Males are clearly larger than females; otherwise the sexes look alike", "group": "A colony of 6 or more, or one male with 2 or 3 females to start", "breeding_tank": "20 gallons long, 2 inches or more of sand, 2 to 3 shells per fish", "conditioning": "1 to 2 weeks of baby or adult brine shrimp, daphnia, cyclops and fine flake", "trigger": "Enough shells, stable hard alkaline water and a settled colony", "spawn": "Small clutches, commonly a few to about 20 or 30 eggs", "eggs": "Hatch in roughly 2 to 3 days at 78 to 80°F; fry stay in the shell for about a week", "fry": "Tiny fry appear at the shell mouth about 7 to 10 days after spawning", "first_foods": "Baby brine shrimp, microworms and finely powdered flake", "grow_out": "About 1/2 inch in 2 months; full size, around 1 to 2 inches, takes many months", "parents": "Parents and colony guard fry; fry can usually stay with the adults"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long tank is a good start, because multies use the bottom more than the height. Add at least 2 inches of fine sand, since they dig constantly and bury shells to make their homes. Then add 2 to 3 empty snail shells per fish, roughly 1.5 to 2 inches across. Shells sold for shell dwellers or cleaned escargot shells work well.\n\nThe site lists multies at 76 to 82°F, pH 7.8 to 9 and GH 10 to 20. Aim for about 78 to 80°F and pH 8.2 to 8.8. A sponge filter is ideal, and a weekly 20 to 25 percent water change keeps things stable."}, {"heading": "Starting a colony", "text": "Males are noticeably larger than females, often close to 2 inches against about 1.25 inches for a female. That is the main way to tell them apart, which only works once fish are grown. The usual approach is to buy a group of 6 to 10 juveniles and let them sort out territories, or start with one male and two or three females.\n\nMulties are carnivores. Feed small amounts of baby or adult brine shrimp, daphnia, cyclops and a quality fine flake or micro pellet once or twice a day. Their mouths are small, so food size matters."}, {"heading": "Spawning: what you will see", "text": "You will rarely see the actual spawning. The female lays her eggs inside a shell and the male fertilizes them, all out of sight. The signs are a female who spends most of her time in or right at the mouth of one shell and fiercely chases other fish away from it.\n\nClutches are small, commonly a few eggs up to about 20 or 30. Each female will use her own shell, and a male often controls a territory containing several females."}, {"heading": "Eggs and the first week", "text": "The eggs hatch in roughly 2 to 3 days at 78 to 80°F, and the fry stay inside the shell while they absorb their yolk. About 7 to 10 days after spawning, you will see tiny fry hovering at the shell entrance and darting back inside when anything comes near.\n\nThere is nothing for you to do except keep the water clean and avoid disturbing the shells. Do not lift shells to check; you may spill or stress the fry."}, {"heading": "Raising the fry", "text": "Multie fry are best raised in the colony. Week 1: squirt baby brine shrimp or microworms near the shells with a pipette once or twice a day. Week 2 onward: add very finely powdered flake. Keep the temperature steady and do small water changes of 15 to 20 percent twice a week, siphoning gently above the sand.\n\nThe fry will start digging and claiming their own little spots as they grow. Adults generally tolerate their own young, which is why colonies grow so well."}, {"heading": "Growing out", "text": "Multies grow slowly. Expect fry to reach about 1/2 inch in 2 months, with full adult size taking many months. A colony can stay together for a long time, but once the tank gets crowded or fights over shells become constant, move some of the young to their own tank with plenty of shells.\n\nKeep adding shells as the colony grows. A good rule is to always have more shells than fish."}, {"heading": "Common mistakes", "text": "- Too few shells, which leads to fighting and lost fry.\n- Shallow sand, which stops them burying shells the way they like.\n- Feeding food that is too large for their small mouths.\n- Moving or rinsing shells while fry are inside.\n- Adding fish that compete for the bottom, such as other shell dwellers or bottom grazing cichlids."}]$g$::jsonb, $g$[{"q": "How many shells do multies need?", "a": "Provide at least 2 to 3 shells per fish and add more as the colony grows. Having extra shells cuts down on fighting."}, {"q": "How do you sex multies?", "a": "Males are clearly larger than females once grown, but otherwise they look alike."}, {"q": "Do multies eat their fry?", "a": "Usually not. Multies guard their fry, and the colony generally tolerates its young."}, {"q": "How fast do multies breed?", "a": "A settled colony can spawn often, and breeders report steady fry production once the fish are comfortable."}]$g$::jsonb, $g$Multies spawn in shells out of sight, so for stage 2 a photo of tiny fry at a shell mouth is often the clearest evidence. Note the date you first see them and photograph the colony with your challenge code card for stage 1 well before then.$g$),
  ($g$ocellatus-shell-dweller$g$, $g$e6527b0b-af84-4b87-b809-7498070932be$g$::uuid, $g$ocellatus-shell-dweller$g$, null, $g$How to Breed Lamprologus Ocellatus: Shells, Pairs and Fry$g$, $g$Ocellatus are bold little shell dwellers; the female spawns inside a snail shell and guards her fry, making them a fun, small tank breeding project.$g$, $g$Lamprologus ocellatus are tiny, feisty shell dwellers with huge personalities. The female picks an empty snail shell, spawns inside it and guards her fry with real courage, even against your hand. They breed readily in a small species tank once they settle in, and watching a female peek out of her shell surrounded by her fry is a highlight of keeping Tanganyikan cichlids.$g$, $g${"method": "Shell dwelling cave spawner; eggs laid inside an empty snail shell", "sexing": "Males are clearly larger than females; both have the dark spot on the gill cover", "group": "One pair, or one male with 2 females", "breeding_tank": "20 gallons long, 2 inches or more of sand, 2 shells per fish", "conditioning": "1 to 2 weeks of brine shrimp, daphnia, cyclops and fine flake or pellets", "trigger": "A female settled in a shell, stable hard alkaline water around 78°F", "spawn": "Commonly about 20 to 50 eggs", "eggs": "Hatch in roughly 2 to 3 days at about 78°F; fry stay in the shell for about a week", "fry": "Fry appear at the shell mouth about 7 to 10 days after spawning", "first_foods": "Baby brine shrimp, microworms and finely powdered food", "grow_out": "About 1/2 inch in 2 months; slow growing after that", "parents": "Female guards the shell and fry; remove fry after a few weeks to avoid conflict"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long tank is enough for a pair or a male with two females. Use at least 2 inches of fine sand, since ocellatus dig constantly and bury their shells until only the opening shows. Add at least 2 empty snail shells per fish, about 1.5 to 2 inches across.\n\nThe site lists ocellatus at 75 to 80°F, pH 7.8 to 9 and GH 10 to 20. Breeding goes well at about 78°F and pH 8.2 to 8.8. A sponge filter and weekly 20 to 25 percent water changes keep the tank stable. Keep tankmates out, as these little fish will fight much larger ones over a shell."}, {"heading": "Choosing and conditioning a pair", "text": "Adult males are clearly larger than females, roughly 2 inches against about 1.5 inches. Both sexes have the dark spot on the gill cover that gives the fish its name. Some strains, such as gold ocellatus, have bright color in both sexes, so size is the best guide.\n\nA pair works well, and a male with two females also works if each female can claim her own shells. Feed small portions of brine shrimp, daphnia, cyclops and fine flake or micro pellets once or twice a day."}, {"heading": "Spawning: what you will see", "text": "The female picks a shell, buries it and starts guarding it. The male visits and courts her, and spawning happens inside the shell where you cannot see it. The female then spends most of her time in the shell or right at the opening and becomes very defensive.\n\nClutches are commonly around 20 to 50 eggs. The male is not much help with care, and he may move on to court other females."}, {"heading": "Eggs and the first week", "text": "The eggs hatch in roughly 2 to 3 days at about 78°F, and the fry stay inside the shell while they absorb their yolk. About 7 to 10 days after spawning, you will see tiny fry hovering around the shell entrance with mom keeping watch.\n\nLeave the shell alone. Lifting it to check will scatter the fry or stress the female."}, {"heading": "Raising the fry", "text": "Week 1 of free swimming: squirt baby brine shrimp or microworms near the shell once or twice a day. Week 2 onward: add very fine powdered flake. Keep the temperature steady and change 15 to 20 percent of the water twice a week, siphoning gently.\n\nAfter a few weeks, the female will usually want to spawn again and may start chasing the older fry away. That is the time to move them to their own grow out tank, along with a few shells."}, {"heading": "Growing out", "text": "Ocellatus grow slowly. Fry reach about 1/2 inch in 2 months, and full size can take most of a year. Grow them out in a tank with sand and plenty of small shells so each juvenile can find a spot. Feed small amounts several times a day and keep up water changes.\n\nAs they mature, young males start fighting over shells. Split them up or move them on before injuries happen.\n\nYoung ocellatus are easiest to sell or trade at around 1 inch, once they are big enough to eat small pellets and handle a move. Keep one or two of your best young females and an unrelated male if you want to start a fresh pair down the line. Label gold and regular forms separately so buyers know what they are getting."}, {"heading": "Common mistakes", "text": "- Too few shells, which leads to constant fighting.\n- Keeping them with other fish, which they will attack.\n- Lifting shells to look for eggs or fry.\n- Leaving older fry in with a female ready to spawn again.\n- Using coarse gravel, which stops them burying their shells."}]$g$::jsonb, $g$[{"q": "How many fry do ocellatus have?", "a": "Clutches are commonly around 20 to 50 eggs, laid inside an empty snail shell."}, {"q": "How do you tell male and female ocellatus apart?", "a": "Males are clearly larger than females once grown. Coloring is otherwise similar."}, {"q": "Do ocellatus eat their fry?", "a": "Females guard their fry closely. After a few weeks, they may chase older fry away when they want to spawn again, so move the fry then."}, {"q": "How many shells do I need for ocellatus?", "a": "Give at least 2 shells per fish, and more if you have several females."}]$g$::jsonb, $g$Photograph your pair in their sandy tank with the shells and challenge code card for stage 1. For stage 2, the clearest evidence is usually the first tiny fry at the shell mouth with the female guarding them.$g$),
  ($g$red-zebra-cichlid$g$, $g$9e7d6bbc-6882-484f-95e0-b0af20c1eae5$g$::uuid, $g$red-zebra-cichlid$g$, null, $g$How to Breed Red Zebra Cichlids: Harems and Fry Guide$g$, $g$Red zebras are classic beginner mouthbrooders; females hold 10 to 40 eggs for about 3 weeks, but sexing and aggression need careful planning.$g$, $g$Red zebras are one of the most popular mbuna, and they breed readily in a well set up harem tank. Females hold their eggs for about three weeks, and the orange fry are a lovely sight. The tricky parts are sexing, since both sexes can be orange in aquarium strains, and managing aggression so holding females are not harassed. Get those right and they are a great first mouthbrooder.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Tricky in aquarium strains; males have more egg spots and longer fins. Venting is most reliable", "group": "1 male to 3 or 4 females", "breeding_tank": "50 gallons or more, rock caves, hard alkaline water", "conditioning": "2 weeks of spirulina flake and pellets with small amounts of protein", "trigger": "Stable water at 78 to 80°F with enough females and rock cover", "spawn": "Commonly 10 to 40 eggs, depending on female size", "eggs": "Held about 3 to 4 weeks (often 21 to 28 days) at 78 to 80°F", "fry": "Released free swimming, about 3/8 inch", "first_foods": "Baby brine shrimp, crushed spirulina flake and fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so isolate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 50 gallon tank is the site's minimum for red zebras, and it suits one male and three or four females. Stack rocks into lots of caves and crevices so females can break line of sight with the male. Sand or fine gravel is best, and strong filtration helps in a heavily stocked tank.\n\nKeep the water at 76 to 82°F, pH 7.8 to 8.6 and GH 10 to 25. For breeding, aim for about 78 to 80°F and pH 8.0 to 8.4. Change 30 to 50 percent of the water each week."}, {"heading": "Choosing and conditioning a harem", "text": "Sexing red zebras is tricky because aquarium strains vary. Females are usually orange, and males can be orange or pale blue to whitish depending on the strain. Males usually grow larger with longer pointed fins and more, brighter egg spots on the anal fin. Color alone is not reliable, so venting is the best check.\n\nKeep one male with three or four females. Feed a spirulina based flake or pellet twice a day for about 2 weeks, with protein foods as an occasional treat. Breed them in a species tank, since red zebras hybridize easily with other Maylandia."}, {"heading": "Spawning: what you will see", "text": "The male intensifies his color, shakes and leads a female to a flat spot or cave. She lays a few eggs at a time, picks them up and mouths at his egg spots to fertilize them. This can go on for an hour or more.\n\nAfterward she hides with a full throat and stops eating. Clutches are commonly around 10 to 40 eggs, with larger females holding more."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks, often 21 to 28 days at 78 to 80°F. If the male harasses her, move her after about a week to a 10 to 20 gallon tank with matched water and a cave. Net her gently and avoid chasing, or she may spit the eggs.\n\nSome breeders strip the fry when they are well developed, but most beginners do best letting her release naturally. A well conditioned female holds better, so do not skip the conditioning."}, {"heading": "Raising the fry", "text": "The fry are released free swimming, about 3/8 inch long. Week 1: baby brine shrimp and finely crushed spirulina flake twice a day. Weeks 2 to 4: add fry pellets. Keep the tank at 78 to 80°F, use a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRemove the female after release and give her a week or two of good feeding before returning her to the harem."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months and around 2 inches in 5 to 6 months. Give them rockwork and space, and keep up the water changes. Young males start to show more egg spots and longer fins at about 2 inches, which is a good time to sort them.\n\nFeed spirulina based foods as the main diet, since rich foods every day can cause bloat in mbuna.\n\nThree or four small meals a day grow fry faster than one big one, and frequent water changes matter even more than food. Sort the fry by size if a few start to outgrow the rest, because bigger siblings will push smaller ones off the food. Groups sell and rehome best at around 1.5 to 2 inches, before the males turn on each other."}, {"heading": "Common mistakes", "text": "- Assuming color tells you the sex and ending up with the wrong ratio.\n- Mixing red zebras with other Maylandia and getting hybrids.\n- Moving the holding female too early, causing her to spit.\n- Overfeeding protein, which can lead to bloat."}]$g$::jsonb, $g$[{"q": "How do you tell male and female red zebras apart?", "a": "It depends on the strain, since both sexes can be orange. Males are usually larger with more egg spots and longer fins, but venting is the most reliable way."}, {"q": "How long do red zebras hold their eggs?", "a": "About 3 to 4 weeks, often 21 to 28 days at 78 to 80°F."}, {"q": "How many babies do red zebras have?", "a": "Broods of about 10 to 40 fry are typical, depending on the size of the female."}, {"q": "Can red zebras breed with other cichlids?", "a": "Yes, they hybridize easily with other Maylandia. Breed them in a species tank so the fry stay pure."}]$g$::jsonb, $g$Include the male and his females in your stage 1 photo with the challenge code card. A side view of the holding female's swollen throat is good stage 2 evidence, and photographing the fry tank at each grow out stage makes counting easy.$g$),
  ($g$rusty-cichlid$g$, $g$35ae3c5d-b5e0-4256-bb38-2d4a92d5fa31$g$::uuid, $g$rusty-cichlid$g$, null, $g$How to Breed Rusty Cichlids: A Calm Mbuna Breeding Guide$g$, $g$Rusty cichlids are among the calmer mbuna and breed readily; sexing is hard, broods are small, and females hold for about 3 to 4 weeks.$g$, $g$Rusty cichlids are one of the gentler mbuna, which makes them a good choice if you want to breed a Malawi mouthbrooder without constant fighting. They breed readily once you have a group, though sexing is hard because males and females look so alike. Broods are modest, but watching the fry grow into rusty orange adults with a lavender sheen is a pleasure.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Hard: sexes look alike; males may show more egg spots. Venting is most reliable", "group": "1 male to 3 or 4 females", "breeding_tank": "40 gallons or more, rock caves, hard alkaline water", "conditioning": "2 weeks of spirulina flake and pellets with some protein", "trigger": "Stable water at 78 to 80°F in a calm, well decorated tank", "spawn": "Small broods, commonly about 10 to 30 eggs", "eggs": "Held about 3 to 4 weeks at 78 to 80°F", "fry": "Released free swimming, about 3/8 inch", "first_foods": "Baby brine shrimp, crushed flake and fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so separate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 40 gallon minimum for rusty cichlids, and that suits a breeding group of one male and three or four females. Stack rocks into caves and gaps, with a sand or fine gravel bottom and open swimming room in front.\n\nKeep the water at 76 to 82°F, pH 7.8 to 8.6 and GH 10 to 25, aiming for about 78 to 80°F and pH 8.0 to 8.4 for breeding. Change 30 to 50 percent of the water each week. Rusties are calmer than most mbuna, so avoid pairing them with very aggressive species that may stress the females."}, {"heading": "Building a breeding group", "text": "Rusties are hard to sex by eye. Males can be slightly larger and may show more egg spots on the anal fin, but females can show egg spots too. Venting is the most reliable method. Many breeders start with 6 to 8 juveniles and watch for the dominant male, then remove extra males.\n\nRusties are omnivores that graze on algae. Feed a spirulina based flake or pellet twice daily, with small portions of brine shrimp or mysis a couple of times a week for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The male darkens, shakes and leads a female to his chosen spot. She lays a few eggs, picks them up in her mouth and nips at his anal fin to fertilize them. Broods are small, commonly about 10 to 30 eggs.\n\nA holding female has a full throat, stops eating and hides near the rocks."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Since rusties are fairly peaceful, some breeders leave holding females in the main tank, but moving her after about a week to a 10 to 20 gallon tank with matched water gives the fry the best odds.\n\nNet her gently and avoid chasing her around the tank, which can make her spit. After release, give her a week or two of good feeding before putting her back."}, {"heading": "Raising the fry", "text": "The fry are released free swimming and ready to eat. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRusty fry are fairly peaceful with each other, which makes grow out easy. Do not overfeed: uneaten food in a small fry tank fouls the water quickly, so feed only what the fry clear in a minute or two and siphon the rest."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months, and around 2 inches by 5 to 6 months. They take on the rusty orange body and lavender sheen as they grow. Feed spirulina based foods as the base and keep the water changes going.\n\nBecause they are calm, young rusties can usually be raised in groups for longer than more aggressive mbuna. Move out obvious males when they start to dominate.\n\nThree or four small meals a day give the best growth, and frequent water changes help even more. Keep a few of your best young females and an unrelated male aside if you plan to start a new breeding group later, since breeding siblings over many generations can weaken a line."}, {"heading": "Common mistakes", "text": "- Keeping them with very aggressive mbuna, which stresses holding females.\n- Buying unvented adults and ending up with too many males.\n- Moving the holding female too early.\n- Feeding protein heavy foods every day."}]$g$::jsonb, $g$[{"q": "How do you tell male and female rusty cichlids apart?", "a": "They look very similar. Males may be slightly larger with more egg spots, but venting is the only reliable method."}, {"q": "How many fry do rusty cichlids have?", "a": "Broods are small, commonly about 10 to 30 fry."}, {"q": "How long do rusty cichlids hold their eggs?", "a": "Females hold for about 3 to 4 weeks at 78 to 80°F."}, {"q": "Are rusty cichlids aggressive?", "a": "They are one of the calmer mbuna, though males still defend territories during breeding."}]$g$::jsonb, $g$Show the whole group in your stage 1 photo with the challenge code card and note which fish you vented as the male. Broods are small, so a clear photo of the fry tank at each stage makes the counts easy to check.$g$),
  ($g$striped-kribensis$g$, $g$1910638f-34db-4910-8d1f-65c0c7aeac94$g$::uuid, $g$striped-kribensis$g$, null, $g$How to Breed Striped Kribensis: Soft Water, Caves and Fry$g$, $g$Striped kribs are cave spawning West African cichlids that raise fry as a pair; soft, acidic water and a good cave are the keys to success.$g$, $g$Striped kribensis are a beautiful cousin of the common krib, with many color forms from different West African streams. They pair up, spawn in a cave and raise their fry together, and breeding them is a great step up for anyone who has bred common kribs. The main difference is water: they do best in soft, slightly acidic conditions that mimic their forest streams.$g$, $g${"method": "Cave spawner; both parents guard, female tends the cave", "sexing": "Females are rounder with a bright belly; males are larger with longer pointed fins", "group": "One pair", "breeding_tank": "20 gallons, caves, sand, plants, soft slightly acidic water", "conditioning": "2 weeks of frozen brine shrimp, bloodworms, daphnia and quality flake", "trigger": "A settled pair, soft acidic water and warm, stable temperatures", "spawn": "Commonly about 50 to 150 eggs", "eggs": "Hatch in about 2 to 4 days at 77 to 79°F", "fry": "Free swimming roughly 7 to 10 days after spawning", "first_foods": "Baby brine shrimp and microworms, then crushed flake", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Both parents guard; may eat early spawns but usually settle down"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well for one pair. Use a sand bottom, plenty of plants, and a couple of caves such as coconut halves or small clay pots with an opening the female can use. Dim light and floating plants make them feel safe.\n\nThe site lists striped kribs at 72 to 79°F, pH 5.5 to 7 and GH 2 to 10. For breeding, aim for about 77 to 79°F, pH 6 to 6.5 and a GH under about 6. Soft water is the key difference from common kribs. A sponge filter and weekly 25 percent water changes with matched soft water keep them in shape."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing is easier than in many cichlids. Females are smaller and rounder, and when ready to spawn they show a bright, often purple or pink, belly. Males grow larger and have longer, pointed dorsal and anal fins. In many color forms, males also have spots or patterns on the tail.\n\nEach color form comes from a different location, such as Moliwe or Lokoundje. Keep forms separate and label them, so fry stay true to type. Condition the pair on frozen brine shrimp, bloodworms, daphnia and a good flake, fed twice a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "The female shows her bright belly, bends her body and invites the male to a cave. She spends a lot of time inside cleaning it, and spawning happens on the cave ceiling or wall. Clutches of about 50 to 150 eggs are commonly reported.\n\nThe female then tends the eggs inside, while the male guards the area outside."}, {"heading": "Eggs and the first days", "text": "The eggs hatch in about 2 to 4 days at 77 to 79°F. The female moves the wrigglers around inside the cave while they absorb their yolk. Roughly 7 to 10 days after spawning, the fry swim out in a tight group with both parents guarding.\n\nFungus is not usually a problem, since the female fans and cleans the eggs. If a new pair eats the eggs, give them a few more chances."}, {"heading": "Raising the fry", "text": "Week 1 of free swimming: baby brine shrimp and microworms two or three times a day. Week 2: add finely crushed flake. Week 3 onward: crushed pellets and small frozen foods.\n\nKeep the temperature at 77 to 79°F and change 20 to 25 percent of the water every few days with matched soft water. The parents will guard the fry for several weeks. When they start getting ready to spawn again, move the fry to a grow out tank."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months. Young fish begin to show their color form at around 1.5 inches. Grow them out in a tank with caves and plants and keep up the water changes.\n\nBreeders report that water pH and temperature can affect the sex ratio of Pelvicachromis fry, so if you get very lopsided broods, try adjusting toward the middle of the range on the next spawn.\n\nFeed growing fry three or four small meals a day of baby brine shrimp, crushed flake and small frozen foods. Young striped kribs are generally peaceful with each other until they start pairing off at around 2 inches, which is a good time to sell or trade them in groups. Keep the color form name with every fish that leaves your tank."}, {"heading": "Common mistakes", "text": "- Using hard, alkaline water, which often leads to poor hatch rates.\n- Mixing color forms and losing the pure line.\n- Keeping them with boisterous tankmates that stress the pair.\n- Leaving older fry in when the parents spawn again."}]$g$::jsonb, $g$[{"q": "How do you tell male and female striped kribs apart?", "a": "Females are smaller and rounder with a bright belly when ready to spawn. Males are larger with longer, pointed fins."}, {"q": "What water do striped kribs need for breeding?", "a": "Soft, slightly acidic water works best, around pH 6 to 6.5 with low hardness and 77 to 79°F."}, {"q": "How many eggs do striped kribs lay?", "a": "Clutches of about 50 to 150 eggs are commonly reported, laid inside a cave."}, {"q": "Do striped kribs eat their fry?", "a": "Usually not. A new pair may eat a first spawn, but most become good parents."}]$g$::jsonb, $g$Note the color form in your log and photograph the pair beside their cave with your challenge code card for stage 1. A photo of the parents leading the fry out of the cave makes a great stage 3 shot.$g$),
  ($g$electric-yellow-lab$g$, $g$7cc903fd-a007-45f5-8e05-b26c0fd4b3a2$g$::uuid, $g$electric-yellow-lab$g$, null, $g$How to Breed Yellow Labs: Mouthbrooding Made Easy$g$, $g$Yellow labs are one of the easiest and calmest mbuna to breed; females hold 10 to 25 eggs for about 3 to 4 weeks in a well set up harem tank.$g$, $g$Yellow labs are often the first mouthbrooder people breed, and for good reason. They are calmer than most mbuna, they spawn readily in a harem, and the bright yellow fry are easy to raise. The trickiest part is sexing, since the black in the fins that people use as a guide shows up in both males and females. Get a good group together and the labs will do the rest.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Unreliable by looks; males usually have darker black fins and grow larger. Venting is best", "group": "1 male to 3 or 4 females", "breeding_tank": "40 gallons or more, rock caves, sand, hard alkaline water", "conditioning": "2 weeks of spirulina flake and pellets plus small amounts of protein", "trigger": "Stable water at 78 to 80°F with enough females and rock cover", "spawn": "Commonly 10 to 25 eggs", "eggs": "Held about 3 to 4 weeks at 78 to 80°F", "fry": "Released free swimming, about 3/8 inch, already yellow", "first_foods": "Baby brine shrimp, crushed flake and fry pellets", "grow_out": "About 1 inch in 2 to 3 months", "parents": "No care after release; adults eat fry, so separate the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 40 gallon minimum for yellow labs, and a group of one male and three or four females fits well in a 40 breeder or larger. Stack rocks into caves along the back, add sand or fine gravel and leave open water in front. Labs are calmer than most mbuna, but males still claim a territory.\n\nKeep the water at 75 to 82°F, pH 7.6 to 8.8 and GH 10 to 25. For breeding, aim for about 78 to 80°F and pH 8.0 to 8.4. Change 30 to 50 percent of the water every week."}, {"heading": "Choosing and conditioning a harem", "text": "Sexing yellow labs by looks is unreliable. Males usually grow larger and have more intense black on the dorsal, anal and pelvic fins, sometimes with a dusky throat. But many females also have black in their fins, so do not rely on it. Venting is the most reliable method. The other route is to grow out 6 to 8 juveniles and remove extra males once you see who is dominant.\n\nFeed a spirulina based flake or pellet twice a day with small portions of brine shrimp, mysis or daphnia a few times a week for about 2 weeks. Labs eat more protein than most mbuna, but rich foods every day can still cause bloat."}, {"heading": "Spawning: what you will see", "text": "The male brightens, shakes his body and leads a female toward a flat rock or cave. She lays a few eggs at a time, picks them up in her mouth and mouths at his anal fin to fertilize them. Spawning can last an hour or more.\n\nAfterward she hides with a puffy throat and stops eating. Broods are commonly about 10 to 25 eggs, with young females holding fewer."}, {"heading": "Holding time", "text": "Females hold for about 3 to 4 weeks at 78 to 80°F. Labs are mild enough that some breeders leave holding females in the main tank, but moving her after about a week to a 10 to 20 gallon tank with matched water gives the best fry survival.\n\nNet her gently without a long chase. Moving her in the first few days often makes her spit. Some breeders strip well developed fry, but natural release is easier on beginners and the female."}, {"heading": "Raising the fry", "text": "The fry come out free swimming, about 3/8 inch long and already yellow. Week 1: baby brine shrimp and finely crushed flake twice a day. Weeks 2 to 4: add fry pellets and continue the brine shrimp. Keep them at 78 to 80°F with a sponge filter and change 25 to 50 percent of the water two or three times a week.\n\nRemove the female after release and give her a week or two of good feeding before returning her to the group."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 2 to 3 months and roughly 2 inches in 5 to 6 months. They are peaceful with each other, so grow out is straightforward. Feed three or four small meals a day if you can and keep up frequent water changes, which do more for growth than extra food.\n\nLook for good color: bright, even yellow and clean black fin edges. Keep your best fish for future breeding, and avoid breeding fish with faded or patchy color."}, {"heading": "Common mistakes", "text": "- Assuming black fins always mean male.\n- Keeping labs with similar yellow mbuna, which can lead to hybrids.\n- Moving the holding female too early.\n- Feeding heavy protein every day.\n- Overcrowding the grow out tank, which slows growth."}]$g$::jsonb, $g$[{"q": "How do you tell male and female yellow labs apart?", "a": "Males are usually larger with darker black in the fins, but females can show black too. Venting is the most reliable method."}, {"q": "How long do yellow labs hold their eggs?", "a": "Females usually hold for about 3 to 4 weeks at 78 to 80°F."}, {"q": "How many babies do yellow labs have?", "a": "A brood is commonly about 10 to 25 fry, depending on the female's size."}, {"q": "Can yellow labs breed in a community tank?", "a": "Yes, they often spawn in mixed mbuna tanks, but few fry survive. Moving the holding female gives far better results."}]$g$::jsonb, $g$Show the male and females in your stage 1 photo with the challenge code card, and note which fish you vented. A side view of the holding female's swollen throat makes good stage 2 evidence.$g$),
  ($g$boesemani-rainbowfish$g$, $g$12585f1f-e67b-4af8-9fcc-85a455b192fa$g$::uuid, $g$boesemani-rainbowfish$g$, null, $g$How to Breed Boeseman's Rainbowfish: Mops, Eggs and Fry$g$, $g$Boeseman's rainbowfish lay a few eggs daily on spawning mops; the eggs are easy, but the tiny fry need very fine first foods and patience.$g$, $g$Boeseman's rainbowfish are easy to spawn: a well fed group will lay eggs on a spawning mop almost every morning. The challenge is the fry, which are tiny and need microscopic foods for their first week or two. They also grow slowly and take many months to show the famous blue and orange colors. If you are patient, it is a rewarding project.$g$, $g${"method": "Egg scatterer that attaches eggs to plants or spawning mops", "sexing": "Males are deeper bodied and more colorful; females are slimmer and duller", "group": "1 male to 2 or 3 females, or a larger group", "breeding_tank": "30 gallons or more, spawning mops or fine leaved plants, gentle filter", "conditioning": "2 weeks of live or frozen foods, quality flake and spirulina", "trigger": "Morning light, fresh water changes and a warm, stable tank", "spawn": "A few to a few dozen eggs a day over several weeks", "eggs": "Hatch in about 7 to 12 days at 79 to 82°F", "fry": "Fry swim at the surface right after hatching; very small", "first_foods": "Infusoria, green water or liquid fry food, then vinegar eels and baby brine shrimp", "grow_out": "About 1 inch in 3 to 4 months; full color can take a year or more", "parents": "No care; adults eat eggs and fry, so move mops to a separate tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 30 gallon minimum for Boeseman's rainbowfish, and a 30 gallon long or larger is a good breeding tank for a male and two or three females. Add two or three spawning mops made of dark acrylic yarn, or dense fine leaved plants such as java moss. A sponge filter is ideal, because fry and eggs get pulled into stronger filters.\n\nThe site's care range is 75 to 86°F, pH 7 to 8 and GH 8 to 20. For breeding, aim for about 79 to 82°F and pH 7.2 to 7.8."}, {"heading": "Choosing and conditioning", "text": "Males are deeper bodied, with brighter blue fronts and orange to red rear halves, and longer dorsal and anal fins. Females are slimmer, with duller coloring. Males also show a bright color stripe on the forehead when displaying.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and spirulina, two or three times a day for about 2 weeks. A well fed group spawns more often and lays more eggs."}, {"heading": "Spawning: what you will see", "text": "Rainbowfish usually spawn in the morning, especially when the tank gets morning light. The male displays with his fins spread and a bright forehead stripe, then swims beside a female into the mop. She releases a few eggs at a time, each with a sticky thread that catches on the yarn or leaves.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick the eggs off, into a hatching tank or container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 12 days at 79 to 82°F. Because they are laid over several days, you will get a steady trickle of fry rather than one big hatch. Remove any eggs that turn white, since fungus can spread. A small dose of methylene blue in the hatching container helps, but remove it before the fry hatch."}, {"heading": "Raising the fry", "text": "Rainbowfish fry are tiny and stay near the surface. Week 1: infusoria, green water or liquid fry food, several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: add crushed flake.\n\nKeep the fry at 78 to 80°F with a gentle sponge filter, and change 10 to 20 percent of the water every few days with matched water. Keep the water clean but avoid big changes, which stress the fry. Many losses in the first two weeks come from starvation, so feed small amounts often."}, {"heading": "Growing out", "text": "Boeseman's rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. Young fish are silvery and plain, and the classic blue and orange colors can take a year or more to fully develop.\n\nFeed three or four times a day as they grow and keep up regular water changes. Separate fry by size if bigger siblings start bullying smaller ones.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch. More space and clean water are the two things that speed up rainbowfish growth the most. Keep your best colored fish back for future breeding."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults, who will eat them and the fry.\n- Feeding baby brine shrimp too early, before fry can eat it.\n- Mixing different Melanotaenia species in the breeding tank, which can cause hybrids.\n- Expecting full color in fry; it takes many months."}]$g$::jsonb, $g$[{"q": "How often do Boeseman's rainbowfish lay eggs?", "a": "A healthy group can spawn most days for weeks, laying a few to a few dozen eggs each time."}, {"q": "How long do rainbowfish eggs take to hatch?", "a": "Boeseman's rainbowfish eggs hatch in about 7 to 12 days at 79 to 82°F."}, {"q": "How do you tell male and female Boeseman's rainbowfish apart?", "a": "Males are deeper bodied and more colorful with longer fins. Females are slimmer and duller."}, {"q": "Do rainbowfish eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so move the spawning mops or eggs to a separate tank."}]$g$::jsonb, $g$Rainbowfish spawn a few eggs every day, so open your log before you add the first mop and photograph the group with your challenge code card. For stage 2, a close photo of eggs on the mop strands works well.$g$),
  ($g$neon-dwarf-rainbowfish$g$, $g$14d404ac-b126-4814-8127-30ce561b8f02$g$::uuid, $g$neon-dwarf-rainbowfish$g$, null, $g$How to Breed Dwarf Neon Rainbowfish: Mops, Eggs and Fry$g$, $g$Dwarf neon rainbowfish spawn daily on mops; the eggs hatch in about 7 to 10 days, and tiny fry need fine first foods and patient care.$g$, $g$Dwarf neon rainbowfish are small, peaceful and easy to spawn. A well fed group will lay a few eggs every day on a spawning mop, so collecting them is straightforward. The challenge is raising the fry, which are tiny and need very fine foods for the first week or two. With patience, you will grow out a school of shimmering blue fish with red fins.$g$, $g${"method": "Egg scatterer that attaches eggs to plants or spawning mops", "sexing": "Males have red fins and deeper bodies; females have yellow to orange fins", "group": "1 male to 2 females, or a small group", "breeding_tank": "20 gallons, spawning mops or fine leaved plants, gentle filter", "conditioning": "2 weeks of live or frozen foods, quality flake and spirulina", "trigger": "Morning light, fresh water changes and a warm, stable tank", "spawn": "A few to a few dozen eggs a day over several weeks", "eggs": "Hatch in about 7 to 10 days at 77 to 80°F", "fry": "Fry swim at the surface right after hatching; very small", "first_foods": "Infusoria, green water or liquid fry food, then vinegar eels and baby brine shrimp", "grow_out": "About 1 inch in 3 to 4 months", "parents": "No care; adults eat eggs and fry, so move mops to a separate tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works for a breeding group of a male and two females, or a small group. Add one or two spawning mops of dark acrylic yarn or dense fine leaved plants like java moss. Use a sponge filter so eggs and fry are not sucked in.\n\nThe site lists dwarf neon rainbowfish at 73 to 82°F, pH 6.5 to 7.8 and GH 5 to 15. For breeding, aim for about 77 to 80°F and pH 7 to 7.5."}, {"heading": "Choosing and conditioning", "text": "Sexing is fairly easy. Males have bright red fins and a deeper body, and they show a brighter blue shimmer when displaying. Females have yellow to orange fins and are slimmer. Young fish are harder to sex until they mature at about 1.5 inches.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and some spirulina, two or three times a day for about 2 weeks before you add the mops."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male flashes his colors, spreads his fins and swims beside a female into the mop. She releases a few eggs at a time, each attached to the yarn or plants by sticky threads.\n\nThey spawn every day for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 10 days at 77 to 80°F. Because they are laid over several days, fry appear a few at a time. Remove any eggs that turn white with fungus. A small amount of methylene blue in the hatching container can help, but remove it before hatching.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry are tiny and stay at the surface. Week 1: infusoria, green water or liquid fry food several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: crushed flake.\n\nKeep the fry at 77 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water. Feed small amounts often, since starvation is the biggest cause of losses."}, {"heading": "Growing out", "text": "Dwarf neon rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. They show their blue color and red or yellow fins as they mature, usually by about 5 to 6 months.\n\nKeep feeding three or four times a day and keep up water changes. Sort them by size if bigger fish start pushing smaller ones off the food.\n\nMove the growing fry to a larger tank at around 1/2 inch, since space and clean water speed growth more than anything else. Dwarf neons are peaceful and do well in groups, so raise them together. Keep your best colored males and a few healthy females back to start the next generation."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Feeding baby brine shrimp too early.\n- Using strong filters in the fry tank.\n- Mixing different Melanotaenia species, which can hybridize."}]$g$::jsonb, $g$[{"q": "How do you tell male and female dwarf neon rainbowfish apart?", "a": "Males have red fins and deeper bodies. Females have yellow to orange fins and are slimmer."}, {"q": "How long do dwarf neon rainbowfish eggs take to hatch?", "a": "Eggs hatch in about 7 to 10 days at 77 to 80°F."}, {"q": "Do dwarf neon rainbowfish eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so move the spawning mops or eggs to a separate tank."}, {"q": "How many eggs do dwarf neon rainbowfish lay?", "a": "They lay a few to a few dozen eggs each day, often spawning daily for weeks."}]$g$::jsonb, $g$Rainbowfish spawn a few eggs every day, so open your log before you add the first mop and photograph the group with your challenge code card. For stage 2, a close photo of eggs on the mop strands works well.$g$),
  ($g$forktail-blue-eye$g$, $g$93149daf-2706-4cfc-86fa-1b01169aa06a$g$::uuid, $g$forktail-blue-eye$g$, null, $g$How to Breed Forktail Blue-eyes: Mops, Eggs and Fry Care$g$, $g$Forktail blue-eyes spawn a few eggs daily on mops; eggs take about 2 weeks to hatch and the fry need fine first foods, making this a fun project.$g$, $g$Forktail blue-eyes are small, lively fish with bright yellow fins and big blue eyes, and they spawn readily in a planted tank. Like other blue-eyes, they lay a few eggs every day over a long period, so you collect eggs rather than wait for one big spawn. They are short lived, often only about 2 to 3 years, so breeding them is the best way to keep them going.$g$, $g${"method": "Egg scatterer that attaches eggs to plants or spawning mops", "sexing": "Males have larger, more elaborate yellow and black fins; females are plainer", "group": "1 male to 2 or 3 females, or a small group", "breeding_tank": "15 gallons or more, mops or fine leaved plants, gentle filter", "conditioning": "2 weeks of live or frozen foods plus fine flake", "trigger": "Morning light, fresh water changes and a warm, stable tank", "spawn": "A few eggs a day, spread over many weeks", "eggs": "Often around 2 weeks; reports range roughly 10 to 20 days at 75 to 80°F", "fry": "Fry swim at the surface right after hatching; small but active", "first_foods": "Infusoria, vinegar eels or fine powder, then baby brine shrimp", "grow_out": "About 1 inch in 3 to 4 months", "parents": "No care; adults eat eggs and fry, so move mops to a separate tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 15 gallon minimum for forktail blue-eyes, and a 15 to 20 gallon tank is a good breeding setup. Add one or two spawning mops of dark acrylic yarn or plenty of fine leaved plants such as java moss. Use a sponge filter, since fry and eggs get pulled into stronger filters.\n\nKeep the water at 72 to 80°F, pH 6.5 to 7.8 and GH 5 to 15, as the site lists. For breeding, aim for about 75 to 80°F and pH around 7."}, {"heading": "Choosing and conditioning", "text": "Males have larger, longer fins with bright yellow color and black edges, and they spar with each other constantly. Females are a little smaller and plainer with smaller fins. Sexing is easy in adults.\n\nFeed live or frozen foods such as baby brine shrimp, daphnia and cyclops, plus a fine flake, two or three times a day for about 2 weeks. These are small fish with small mouths, so choose small foods. Forktails spawn better when well fed and kept in a group with several females."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. Males display to females with fins spread, then swim beside a female into the mop or plants. She releases a few eggs at a time, each attached by a thread.\n\nForktails lay only a few eggs each day, but they spawn for many weeks, so egg numbers add up."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and pick off the eggs or move the mop to a hatching container with the same water. Breeders commonly report hatching after about 2 weeks, with a range of roughly 10 to 20 days depending on temperature.\n\nRemove any eggs that turn white with fungus. A small amount of methylene blue can help in the hatching container, but remove it before the fry hatch. Because eggs are collected over several days, fry hatch a few at a time.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry swim at the surface right after hatching. Week 1: infusoria, vinegar eels or very fine powdered food several times a day. Week 2: baby brine shrimp as soon as they can take it. Week 3 onward: crushed flake.\n\nKeep the fry at 75 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first week causes most losses."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 3 to 4 months. Males start to show their yellow fins at around 1 inch. Keep feeding three or four times a day and keep up water changes.\n\nForktail blue-eyes are short lived, often only about 2 to 3 years, so keep a few young fish back to breed next. Rotating new groups keeps the line healthy.\n\nMove the growing fry to a larger tank at around 1/2 inch if they are crowded. Forktails are peaceful and do well in groups, so raise them together, and keep a few of the best colored males and healthy females back for the next round of breeding."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Giving up on eggs too early; they can take 2 weeks or more to hatch.\n- Feeding food that is too large for the fry.\n- Using strong filters in the fry tank."}]$g$::jsonb, $g$[{"q": "How long do forktail blue-eye eggs take to hatch?", "a": "Eggs commonly hatch in about 2 weeks, with reports ranging from roughly 10 to 20 days depending on temperature."}, {"q": "How do you sex forktail blue-eyes?", "a": "Males have larger, longer yellow and black fins. Females are smaller and plainer."}, {"q": "Do forktail blue-eyes eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so move the mops or eggs to a separate tank."}, {"q": "How long do forktail blue-eyes live?", "a": "They are short lived, often about 2 to 3 years, so breeding is the best way to keep them in your tanks."}]$g$::jsonb, $g$Forktails lay only a few eggs a day, so open your log and get your stage 1 photo with the challenge code card before you start collecting eggs. A close photo of eggs on the mop strands works well for stage 2.$g$),
  ($g$turquoise-rainbowfish$g$, $g$2e6271e0-e606-4bf0-811b-89f24cbd23e0$g$::uuid, $g$turquoise-rainbowfish$g$, null, $g$How to Breed Lake Kutubu Rainbowfish: Mops, Eggs and Fry$g$, $g$Lake Kutubu rainbowfish lay eggs daily on spawning mops; the eggs hatch in about 7 to 12 days and the fry need tiny foods and patient grow out.$g$, $g$Lake Kutubu rainbowfish, also called turquoise rainbowfish, are easy to spawn. A well fed group will lay a few eggs on a mop almost every morning, and the eggs are easy to collect. The challenge is the fry, which are tiny and need microscopic foods at first, and the long wait for their turquoise and blue colors. With patience, they are a rewarding fish to breed.$g$, $g${"method": "Egg scatterer that attaches eggs to plants or spawning mops", "sexing": "Males are deeper bodied and more intensely colored with longer fins", "group": "1 male to 2 or 3 females, or a larger group", "breeding_tank": "40 gallons or more, spawning mops or fine leaved plants, gentle filter", "conditioning": "2 weeks of live or frozen foods, quality flake and spirulina", "trigger": "Morning light, fresh water changes and a warm, stable tank", "spawn": "A few to a few dozen eggs a day over several weeks", "eggs": "Hatch in about 7 to 12 days at 78 to 80°F", "fry": "Fry swim at the surface right after hatching; very small", "first_foods": "Infusoria, green water or liquid fry food, then vinegar eels and baby brine shrimp", "grow_out": "About 1 inch in 3 to 4 months; full color can take a year", "parents": "No care; adults eat eggs and fry, so move mops to a separate tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 40 gallon minimum for Lake Kutubu rainbowfish, so a 40 breeder or larger is a good breeding tank. Add two or three spawning mops of dark acrylic yarn or plenty of fine leaved plants like java moss. Use a sponge filter so eggs and fry are not sucked in.\n\nKeep the water at 72 to 82°F, pH 7 to 8 and GH 8 to 20, as the site lists. For breeding, aim for about 78 to 80°F and pH 7.2 to 7.8."}, {"heading": "Choosing and conditioning", "text": "Males are deeper bodied, with brighter turquoise and blue color and longer dorsal and anal fins. Females are slimmer and paler. Males show a bright color stripe on the forehead when displaying.\n\nFeed live or frozen foods such as brine shrimp, bloodworms and daphnia, plus a good flake and spirulina, two or three times a day for about 2 weeks before adding mops. Well fed fish spawn more often."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male displays with his fins spread and a glowing forehead stripe, then swims beside a female into the mop. She releases a few eggs at a time, each attached by a sticky thread.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and about 1 mm across.\n\nEggs hatch in about 7 to 12 days at 78 to 80°F. Fry hatch a few at a time because eggs are laid over several days. Remove any eggs that turn white with fungus. A small amount of methylene blue can help, but remove it before hatching.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry are tiny and stay at the surface. Week 1: infusoria, green water or liquid fry food several times a day. Week 2: add vinegar eels and very fine powdered food. From about week 2 to 3, they can take baby brine shrimp. Week 4 onward: crushed flake.\n\nKeep the fry at 78 to 80°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first weeks causes most losses."}, {"heading": "Growing out", "text": "Lake Kutubu rainbowfish grow slowly. Expect about 1 inch in 3 to 4 months. Young fish are silvery, and the full turquoise color can take a year or more to develop.\n\nFeed three or four times a day and keep up water changes. Separate fry by size if bigger siblings start bullying smaller ones.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch, since more space and clean water speed growth more than anything else. Keep your best colored fish back for future breeding, and avoid breeding fish with faded color or bent spines."}, {"heading": "Common mistakes", "text": "- Leaving eggs in with the adults.\n- Feeding baby brine shrimp too early.\n- Mixing different Melanotaenia species, which can hybridize.\n- Expecting full color in fry; it takes many months.\n- Doing big water changes in the fry tank, which can shock the tiny fry."}]$g$::jsonb, $g$[{"q": "How do you sex Lake Kutubu rainbowfish?", "a": "Males are deeper bodied, more brightly colored and have longer fins. Females are slimmer and paler."}, {"q": "How long do Lake Kutubu rainbowfish eggs take to hatch?", "a": "Eggs hatch in about 7 to 12 days at 78 to 80°F."}, {"q": "Do Lake Kutubu rainbowfish eat their eggs?", "a": "Yes. Adults eat eggs and fry, so move the spawning mops or eggs to a separate tank."}, {"q": "How often do Lake Kutubu rainbowfish spawn?", "a": "A healthy group can spawn daily for weeks, laying a few to a few dozen eggs each time."}]$g$::jsonb, $g$Rainbowfish spawn a few eggs every day, so open your log before you add the first mop and photograph the group with your challenge code card. For stage 2, a close photo of eggs on the mop strands works well.$g$),
  ($g$madagascar-rainbowfish$g$, $g$81b0203e-3cd2-4e51-bafb-0915354ee9f6$g$::uuid, $g$madagascar-rainbowfish$g$, null, $g$How to Breed Madagascar Rainbowfish: Mops, Eggs and Fry$g$, $g$Madagascar rainbowfish lay eggs daily on mops in cooler water than most rainbows; collecting eggs is easy and fry need fine first foods.$g$, $g$Madagascar rainbowfish are a peaceful, cooler water rainbowfish that spawns readily on mops or fine leaved plants. Like their Australian and New Guinea cousins, they lay a few eggs every day for weeks, so you collect eggs rather than wait for one big spawn. They are threatened in the wild, which makes keeping healthy captive bred lines going a worthwhile goal for any breeder.$g$, $g${"method": "Egg scatterer that attaches eggs to plants or spawning mops", "sexing": "Males have brighter fins with red and black edging; females are paler", "group": "1 male to 2 or 3 females, or a larger group", "breeding_tank": "30 gallons or more, spawning mops or fine leaved plants, gentle filter", "conditioning": "2 weeks of live or frozen foods plus quality flake", "trigger": "Morning light, fresh water changes and a stable 74 to 77°F", "spawn": "A few to a few dozen eggs a day over several weeks", "eggs": "Commonly reported around 1 week, longer in cooler water", "fry": "Fry swim at the surface after hatching", "first_foods": "Infusoria or fine powder, then vinegar eels and baby brine shrimp", "grow_out": "About 1 inch in 3 to 4 months", "parents": "No care; adults eat eggs and fry, so move mops to a separate tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "The site lists a 30 gallon minimum for Madagascar rainbowfish, so a 30 gallon long or larger works for a breeding group. Add two or three spawning mops of dark acrylic yarn or plenty of fine leaved plants. A sponge filter keeps eggs and fry safe.\n\nThe site's care range is 68 to 79°F, pH 6.5 to 8 and GH 6 to 15. These fish like cooler water than most rainbowfish, so aim for about 74 to 77°F for breeding with a pH near 7 to 7.5."}, {"heading": "Choosing and conditioning", "text": "Males have brighter fins, with red and black edging on the tail and dorsal fins, and are often slightly deeper bodied. Females are paler with less color in the fins. Sexing is easier in mature fish.\n\nFish sold as Madagascar rainbowfish are sometimes a closely related Bedotia species, since the names are often mixed up in the trade. Keep your group from one source and do not mix Bedotia types. Feed live or frozen foods such as brine shrimp, daphnia and bloodworms, plus a good flake, two or three times a day for about 2 weeks."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens in the morning. The male displays with his fins spread and swims beside a female into the mop or plants. She releases a few eggs at a time, which stick to the yarn or leaves by fine threads.\n\nThey spawn daily for weeks, laying a few to a few dozen eggs each day."}, {"heading": "Eggs and hatching", "text": "Check the mop every day or two and move it, or pick off the eggs, into a hatching container with the same water. The eggs are clear and easy to spot.\n\nBreeders commonly report hatching in around a week, with cooler water taking longer. Fry hatch a few at a time because eggs are laid over several days. Remove any eggs that turn white with fungus. A small amount of methylene blue can help, but remove it before the fry hatch.\n\nA hatching container can be as simple as a plastic tub or small tank with an air stone set to a gentle bubble and a heater. Keep it out of bright direct light and label it with the date the eggs were collected so you know when to expect fry."}, {"heading": "Raising the fry", "text": "The fry swim at the surface after hatching. Week 1: infusoria, very fine powdered food or liquid fry food several times a day. Week 2: add vinegar eels and baby brine shrimp as soon as they can take it. Week 3 onward: crushed flake.\n\nKeep the fry at about 74 to 77°F with gentle filtration. Change 10 to 20 percent of the water every few days with matched water, and feed small amounts often. Starvation in the first weeks causes most losses."}, {"heading": "Growing out", "text": "Fry reach about 1 inch in 3 to 4 months. They show their fin colors as they mature. Keep feeding three or four times a day and keep up water changes.\n\nBecause Madagascar rainbowfish are threatened in the wild, try to keep unrelated breeders and rotate new fish in over time to keep the line healthy.\n\nMove the growing fry into a larger tank once they reach about 1/2 inch, since more space and clean water speed growth more than anything else. Keep your best colored, healthiest fish back for future breeding."}, {"heading": "Common mistakes", "text": "- Keeping them too warm, which shortens their lifespan and reduces spawning.\n- Leaving eggs in with the adults.\n- Feeding food that is too large for the fry.\n- Mixing different Bedotia species or populations."}]$g$::jsonb, $g$[{"q": "How do you sex Madagascar rainbowfish?", "a": "Males have brighter fins with red and black edging. Females are paler with less fin color."}, {"q": "How long do Madagascar rainbowfish eggs take to hatch?", "a": "Breeders commonly report about a week, with cooler water taking longer."}, {"q": "Do Madagascar rainbowfish eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so move the mops or eggs to a separate tank."}, {"q": "What temperature is best for breeding Madagascar rainbowfish?", "a": "They prefer cooler water than most rainbows; about 74 to 77°F works well for breeding."}]$g$::jsonb, $g$Rainbowfish spawn a few eggs every day, so open your log before you add the first mop and photograph the group with your challenge code card. For stage 2, a close photo of eggs on the mop strands works well.$g$),
  ($g$red-rainbowfish$g$, $g$6701de01-5aa5-46eb-8043-a111a13c1324$g$::uuid, $g$red-rainbowfish$g$, null, $g$How to Breed Red Rainbowfish: Spawning Mops and Tiny Fry$g$, $g$Red rainbowfish spawn readily on mops in moderately hard, alkaline water. The real work is the tiny fry, which need infusoria or green water first.$g$, $g$Red rainbowfish are steady, willing spawners: a conditioned male in full red color will chase females into fine plants or a spawning mop every morning for days. Getting eggs is the easy part. The challenge is the fry, which are very small when they hatch and need the right first foods, but with a little preparation this is a very achievable and rewarding species for a dedicated breeding tank.$g$, $g${"method": "Egg scatterer, continuous spawner (sticky eggs hang on plants or mops by fine threads)", "sexing": "Mature males are deep red and high backed; females are olive to silvery gold and slimmer", "group": "1 male to 2 or 3 females, or a small group with more females than males", "breeding_tank": "20 to 30 gallons, sponge filter, spawning mops or java moss, bare or thin substrate", "conditioning": "1 to 2 weeks of live or frozen foods (bloodworms, brine shrimp, daphnia) plus quality flake", "trigger": "Conditioned fish, fresh water and morning light; spawning usually happens in the first hours of light", "spawn": "Dozens of eggs per day over several days rather than one big batch", "eggs": "Commonly about 7 to 12 days at 77 to 80°F, quicker when warmer", "fry": "Swim at the surface right after hatching; very small and easy to underfeed", "first_foods": "Infusoria, green water or liquid fry food, then baby brine shrimp after 1 to 2 weeks", "grow_out": "About 3 to 4 months to around 1.5 inches; full male color can take 6 months or more", "parents": "No care; adults eat eggs and fry, so move mops to a separate hatching tank every few days"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "As a temporary spawning tank, 20 to 30 gallons gives a red rainbowfish trio enough room to display; keep the group in 40 gallons or more the rest of the time. Keep the water in the same range the fish already live in: 77 to 80°F for spawning, pH 7 to 8 and moderately hard water. Red rainbows do well in moderately hard, alkaline water, so there is no need to soften it.\n\nUse a gentle sponge filter, a bare bottom or a thin layer of sand, and two or three spawning mops made of dark acrylic yarn, or a few clumps of java moss. Place one mop near the surface and one near the bottom. A lid matters, because rainbowfish jump when chased.\n\nSet up a second small tank, 5 to 10 gallons with a sponge filter, as the hatching and fry tank. You will move eggs into it as they are laid."}, {"heading": "Conditioning and Choosing Your Fish", "text": "Pick a male with strong red color and a tall back, and two or three plump, active females. Young males are often orange or silvery and color up as they mature, so buy adults if you want to start soon.\n\nCondition the group for 1 to 2 weeks with several small meals a day: frozen or live bloodworms, brine shrimp, daphnia and a good flake. Some breeders separate the sexes during conditioning and then put them together in the breeding tank, which often brings on spawning within a day or two."}, {"heading": "What Spawning Looks Like", "text": "Spawning usually starts as the lights come on. The male darkens, flashes his fins and drives a female into the mop, where the pair quiver side by side and release a few eggs at a time. This repeats through the morning.\n\nEggs are clear, about 1 mm across, and hang from the mop or plants on fine threads. Expect dozens a day over several days rather than one large batch. Check the mops each evening or every two to three days."}, {"heading": "Hatching the Eggs", "text": "Lift the mop into the hatching tank, or pick the eggs off and place them in a container of tank water with an airstone on a gentle setting. Commonly reported hatch time is about 7 to 12 days at 77 to 80°F, so eggs from different days will hatch on different days.\n\nRemove any eggs that turn white, since these are infertile and grow fungus that can spread. A few drops of methylene blue in a separate hatching container, or a couple of alder cones, help some breeders. Do not dose the main tank."}, {"heading": "Raising the Fry", "text": "Newly hatched fry swim straight to the surface and are tiny. Feed them small amounts several times a day:\n\n- Week 1: infusoria, green water or a liquid fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp and microworms\n- Week 4 on: crushed flake, then larger live and frozen foods\n\nKeep the fry tank at 77 to 80°F with gentle filtration. Change 10 to 20 percent of the water every day or two with water matched in temperature. Snails or a bit of plant help clean up leftovers. Fry from later hatches will be smaller, so sort by size if the big ones start to bully."}, {"heading": "Growing Out", "text": "Move the fry to a larger tank, 20 gallons or more, at about 4 to 6 weeks. Rainbowfish grow slowly compared with many fish. Expect around 1.5 inches at 3 to 4 months, with males showing the first red at a few months and full adult color at 6 months or longer. Keep feeding several times a day and keep up with water changes, because steady growth is what brings out color."}, {"heading": "Common Mistakes", "text": "- Leaving eggs in with the adults, who will eat them\n- Starting the fry on baby brine shrimp before they are big enough to eat it\n- Overfeeding liquid food and fouling the small fry tank\n- No lid on the breeding tank\n- Expecting all eggs to hatch together, when daily spawns hatch over a week or more"}]$g$::jsonb, $g$[{"q": "How long do red rainbowfish eggs take to hatch?", "a": "Breeders commonly report about 7 to 12 days at 77 to 80°F. Warmer water speeds it up a little."}, {"q": "Do red rainbowfish eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so move mops or plants with eggs into a separate tank every few days."}, {"q": "How can you tell a male red rainbowfish from a female?", "a": "Adult males are deep red with a tall, arched back. Females are olive to silvery gold, slimmer and less colorful."}, {"q": "What do baby rainbowfish eat?", "a": "Start with infusoria, green water or a liquid fry food for about the first week. Move on to baby brine shrimp once they can take it."}]$g$::jsonb, $g$Open your log and photograph the male and females in the breeding tank with your challenge code card before you add the mops. Because eggs hatch over many days, date your stage 3 photo from the first fry seen swimming.$g$),
  ($g$amazon-sword$g$, $g$54925256-42f9-4a6c-ba77-68d2533517f3$g$::uuid, null, $g$amazon-sword$g$, $g$How to Propagate Amazon Sword: Plantlets on Flower Stalks$g$, $g$Amazon swords make new plants on long underwater stalks. With rich substrate and patience you can root and separate plantlets in a few weeks.$g$, $g$A healthy Amazon sword will send out long stalks that grow a line of baby plants along their length, each one a ready made new sword. Propagating it is mostly about feeding the mother plant well and being patient. It takes a mature plant to start the process, which is why it sits in Society class B, but once it gets going one sword can fill several tanks.$g$, $g${"method": "Adventitious plantlets on flower stalks; occasional division of large rhizomes", "light": "Moderate light, about 8 hours a day; strong light is not required", "co2": "Optional; grows well without, faster with CO2", "substrate": "Deep, nutrient rich substrate or plain gravel with root tabs near the roots", "timeline": "Plantlets root and are ready to separate about 3 to 6 weeks after they form", "first_steps": "Let the stalk grow, then pin plantlets to the substrate or wait for 3 to 5 leaves and roots"}$g$::jsonb, $g$[{"heading": "How Amazon Swords Propagate", "text": "A mature Amazon sword sends up a long, thin stalk from its center. Underwater, this stalk usually does not flower properly. Instead, small plantlets form at nodes along it, each with its own leaves and, in time, its own roots. This is the main way to propagate the plant in an aquarium.\n\nLarge, old plants sometimes have a thick rhizome that can be split, but this is slower and riskier than growing plantlets. A young plant fresh from the store often grows emersed type leaves first and may take a few months to settle before it sends up a stalk."}, {"heading": "What You Need", "text": "- A healthy, established sword with several large leaves\n- At least 2 to 3 inches of substrate, ideally a nutrient rich soil or gravel with root tabs\n- Moderate light for about 8 hours a day\n- Sharp scissors and a few plant weights or rock pieces to hold stalks down\n\nAmazon swords are heavy root feeders. Push a root tab into the substrate near the base every 1 to 3 months. Pale new leaves or yellowing between the veins are a sign the plant needs more iron and nutrients."}, {"heading": "Step by Step", "text": "Let the stalk grow until plantlets appear along it. You have two choices.\n\nThe easy route is to leave the plantlets on the stalk until each has 3 to 5 leaves and a few roots, which usually takes 3 to 6 weeks. Then cut the stalk on either side of the plantlet and plant it gently in the substrate, roots down and the crown just above the surface.\n\nThe faster route is to bend the stalk down and pin the plantlets to the substrate with a weight or a small rock while still attached. They root into the substrate while the mother plant keeps feeding them. Once they show new growth, snip the stalk.\n\nIf the stalk keeps growing toward the surface, you can let plantlets grow partly out of the water. Many hobbyists find these root quickly once planted."}, {"heading": "Caring for New Plants", "text": "Give young swords a root tab of their own after a couple of weeks. Expect a few older leaves to melt or yellow as the plant adjusts; remove these at the base. New leaves from the center are the sign it has taken. Keep fast growing neighbors trimmed so the young plant gets light.\n\nGive each new sword room. A full grown Amazon sword can spread well over a foot wide, so plant young ones at least 8 to 10 inches apart, or move extras to another tank. Young plants grow slowly at first while they build roots, then speed up. Expect a young sword to take several months before it is large enough to send up stalks of its own."}, {"heading": "Dividing a Large Plant", "text": "If a mother plant has grown a thick rhizome with more than one crown, you can lift it and cut the rhizome with a clean knife so each piece keeps a crown and some roots. Replant both pieces at the same depth. Only try this on large, healthy plants, and expect them to sulk for a few weeks."}, {"heading": "Common Mistakes", "text": "- Cutting plantlets off before they have roots, so they float and struggle\n- Burying the crown, which leads to rot\n- No root tabs in plain gravel, giving pale, weak plants that never send stalks\n- Moving the mother plant around, which sets it back for weeks\n- Expecting a newly bought plant to propagate in its first month"}]$g$::jsonb, $g$[{"q": "How do Amazon swords reproduce?", "a": "In the aquarium they grow plantlets on long stalks from the center of the plant. Each plantlet can be rooted and planted as a new sword."}, {"q": "When should I cut Amazon sword plantlets?", "a": "Wait until the plantlet has about 3 to 5 leaves and some roots, which usually takes 3 to 6 weeks. You can also pin it to the substrate first so it roots while still attached."}, {"q": "Do Amazon swords need root tabs?", "a": "In plain gravel or sand, yes. They feed mainly through their roots, and root tabs keep them healthy enough to propagate."}, {"q": "Why is my Amazon sword not making runners?", "a": "Amazon swords make plantlets on flower stalks rather than true runners. If none appear, the plant is usually too young, still adjusting from emersed growth, or short on nutrients. Give it time, root tabs and steady moderate light."}]$g$::jsonb, $g$For the plant program, photograph the mother plant and its stalk with plantlets on day one, then take dated photos when you separate each plantlet and again once it shows new leaves of its own.$g$),
  ($g$cryptocoryne$g$, $g$63156273-710d-4bb7-966e-2ed6e180b89a$g$::uuid, null, $g$cryptocoryne$g$, $g$How to Propagate Cryptocoryne Wendtii: Runners and Division$g$, $g$Cryptocoryne wendtii spreads by underground runners. Learn how to separate plantlets, avoid crypt melt, and grow a thick patch in low light.$g$, $g$Cryptocoryne wendtii is one of the easiest plants to multiply once it has settled in. It sends runners under the substrate and new plantlets pop up a few inches away from the mother. The tricky part is patience: crypts dislike being moved and may melt before they bounce back. Treat them gently and a single pot can turn into a full foreground in a few months.$g$, $g${"method": "Runners under the substrate, plus division of established clumps", "light": "Low to moderate light; does well under basic lighting", "co2": "Not needed; growth is a little faster with CO2", "substrate": "Fine gravel, sand or soil with root tabs placed near the clump", "timeline": "Runners usually appear a few weeks to a few months after the plant settles in", "first_steps": "Wait for plantlets with 3 to 4 leaves, then cut the runner and replant them"}$g$::jsonb, $g$[{"heading": "How Crypts Propagate", "text": "Cryptocoryne wendtii spreads with runners that travel under the substrate. A new plantlet pushes up from the runner a short distance from the mother plant, and in time it makes runners of its own. Left alone, a few plants grow into a dense clump.\n\nYou can also propagate by dividing a clump. Pull it up gently, tease apart the plants, and replant them separately. Crypts in an aquarium very rarely flower, so seeds are not a practical route."}, {"heading": "What You Need", "text": "- An established crypt that has been growing for at least a few weeks\n- Fine gravel, sand or an aquarium soil at least 2 inches deep\n- Root tabs if the substrate is plain gravel or sand\n- Stable water and temperature, since sudden changes trigger melting\n\nCrypts are root feeders and do well in low to moderate light. Stability matters more than any single number. A tank that stays steady week to week will see far more runners than a tank with big swings."}, {"heading": "Step by Step", "text": "Wait until a plantlet has 3 to 4 leaves and visible roots. Reach into the substrate beside it and find the runner connecting it to the mother plant. Snip the runner with scissors, leaving the roots on the plantlet.\n\nPlant the baby a few inches away with its roots buried and the crown at the surface. Crypts do not like being buried too deep.\n\nTo divide a thick clump, lift the whole clump with the substrate around the roots. Rinse gently in tank water and pull it into smaller groups of 2 or 3 plants. Replant right away."}, {"heading": "Dealing with Crypt Melt", "text": "Crypts often lose some or all of their leaves after being moved or after big water changes. This is called crypt melt. It looks alarming but the roots and crown usually survive.\n\nDo not pull a melted plant out. Remove the rotting leaves and leave the roots in place. New leaves commonly appear within 2 to 4 weeks. Moving plants in small numbers at a time and keeping water conditions steady reduces melting."}, {"heading": "Caring for New Plants", "text": "Give young plants a root tab nearby after a couple of weeks. Keep taller plants from shading them entirely. Once they start pushing new leaves, leave them alone. The less you disturb a crypt patch, the faster it fills in.\n\nGrowth is slow compared with stem plants. A new plantlet may only add a leaf or two a month at first. Once its roots are established it starts sending runners of its own, and the patch begins to grow much faster. Leaf color varies with light: brighter light tends to give browner or more reddish leaves, while lower light gives greener ones. Both are normal for Cryptocoryne wendtii, which comes in several color forms."}, {"heading": "Planning a Crypt Patch", "text": "Because runners travel a few inches before coming up, plant your starter plants a few inches apart in the area you want to fill. Keep that area free of gravel vacuuming, which disturbs roots and runners. Trim back plants on the edge if the patch starts moving into space you want for something else. A patch planted with five or six small plants can close in over a few months in a steady tank."}, {"heading": "Common Mistakes", "text": "- Uprooting plants that have melted, assuming they are dead\n- Cutting plantlets before they have roots\n- Burying the crown too deep\n- Moving crypts around the tank repeatedly\n- Large, sudden changes in water hardness or temperature"}]$g$::jsonb, $g$[{"q": "How do Cryptocoryne wendtii spread?", "a": "They send runners under the substrate that grow new plantlets a few inches from the mother plant. Over time this forms a dense clump."}, {"q": "Why is my crypt melting?", "a": "Melting is usually a reaction to being moved or to a sudden change in water conditions. Leave the roots in place and new leaves usually return in a few weeks."}, {"q": "Do crypts need CO2?", "a": "No. Cryptocoryne wendtii grows well without CO2 in low to moderate light, though it can grow a little faster with it."}, {"q": "When can I separate crypt babies?", "a": "Once a plantlet has 3 to 4 leaves and its own roots. Snip the runner and replant it nearby."}]$g$::jsonb, $g$Take a dated photo of the mother plant when you start, then photograph the first plantlet coming up from a runner and again after you replant it and it shows new leaves.$g$),
  ($g$bacopa$g$, $g$e39b69e1-aafd-472c-a806-886816057600$g$::uuid, null, null, $g$How to Propagate Bacopa Caroliniana: Stem Cuttings Made Easy$g$, $g$Bacopa caroliniana grows from simple stem cuttings. Learn where to cut, how to replant the tops, and how to get bushy side shoots.$g$, $g$Bacopa caroliniana is a sturdy, thick stemmed plant that propagates the classic way: cut the top off and plant it. Cuttings root quickly, and the trimmed stem left behind will branch into more stems. It grows at a moderate pace and does not need high tech gear, which makes it a good first stem plant to propagate on purpose.$g$, $g${"method": "Stem cuttings; trimmed stems also branch with side shoots", "light": "Moderate light; stronger light gives bronze tops and more compact growth", "co2": "Optional; growth is steady without, faster with CO2", "substrate": "Any fine gravel, sand or soil; root tabs or liquid fertilizer help", "timeline": "Roots in about 1 to 2 weeks; side shoots from trimmed stems in a few weeks", "first_steps": "Cut the top 3 to 4 inches of a healthy stem and strip the lowest pair or two of leaves"}$g$::jsonb, $g$[{"heading": "How Bacopa Propagates", "text": "Like most stem plants, Bacopa caroliniana grows upward with pairs of leaves along a stem. Any healthy section of stem with a few leaf pairs can root and grow into a new plant. When you cut the top off, the stem left in the substrate usually sprouts one or more side shoots below the cut, so every trim gives you more plants.\n\nRoots often start appearing along the stem near the leaf joints even before you cut it. This is normal and shows the plant is ready to propagate."}, {"heading": "What You Need", "text": "- A healthy, established bunch with green or bronze tops\n- Sharp scissors\n- Moderate light\n- A substrate that holds stems upright, plus root tabs or a liquid fertilizer\n\nBacopa caroliniana is forgiving. It grows without CO2, though growth will be slower and leaves spaced further apart. Crushed leaves smell faintly of lemon, which is a handy way to tell it apart from other Bacopa species."}, {"heading": "Step by Step", "text": "Choose a stem that is reaching toward the surface. Cut the top 3 to 4 inches just above a leaf pair. Remove the lowest one or two pairs of leaves from the cutting so you have bare stem to plant.\n\nPush the bare stem about 1 to 2 inches into the substrate with tweezers. Space cuttings a little apart rather than in one tight bundle, so light reaches the lower leaves.\n\nLeave the bottom part of the original stem in place. Within a few weeks it should push out new side shoots just below the cut. You can also float cuttings for a week or two until roots form, then plant them."}, {"heading": "Caring for New Plants", "text": "Cuttings usually root within about 1 to 2 weeks. Until then, avoid pulling them up to check. Feed with a root tab or a balanced liquid fertilizer. Once the new stems reach the surface, repeat the process. Regular trimming keeps the bunch bushy instead of tall and bare at the bottom.\n\nNew growth may look slightly different from the plants you bought. Nursery Bacopa is often grown out of water, and its underwater leaves can be a little thinner and lighter. This is normal adjustment, not a problem. Bacopa caroliniana is a moderate grower, so expect a few inches of new stem a month in a basic setup rather than the rapid growth of thinner stem plants. Keep it out of deep shade, because lower leaves drop when they do not get enough light."}, {"heading": "Getting a Fuller Bunch", "text": "Bacopa grows tall and straight with few branches if left alone. To build a dense group, trim stems at different heights so the side shoots fill the space in layers. Replant the healthiest tops and discard leggy, weak pieces. In lower light, plant fewer stems with more space between them.\n\nIf you want many plants quickly, you can also cut a long stem into two or three sections, each with several leaf pairs, and plant them all. Middle sections root just like tops, though they take a little longer to start growing upward. This is a good way to fill a new tank from a single bunch."}, {"heading": "Common Mistakes", "text": "- Planting cuttings in a tight bundle, which shades and rots the lower stems\n- Leaving leaves on the buried part of the stem\n- Cutting in a way that crushes the stem instead of a clean snip\n- Letting the plant grow too tall before the first trim\n- Expecting fast growth in low light without fertilizer"}]$g$::jsonb, $g$[{"q": "How do you propagate Bacopa caroliniana?", "a": "Cut the top 3 to 4 inches of a stem, strip the lowest leaves, and plant it in the substrate. The trimmed stem left behind will grow side shoots too."}, {"q": "Does Bacopa need CO2?", "a": "No. It grows without CO2 in moderate light, just more slowly. CO2 and fertilizer give faster, more compact growth."}, {"q": "How long does Bacopa take to root?", "a": "Cuttings commonly root in about 1 to 2 weeks."}, {"q": "Can Bacopa grow floating?", "a": "Cuttings will survive and grow roots while floating, but they do best planted in the substrate once roots form."}]$g$::jsonb, $g$Photograph the bunch with a date before your first trim, then take dated photos of the planted cuttings and the side shoots on the original stems a few weeks later.$g$),
  ($g$rotala$g$, $g$2bb89458-adfe-40b1-b567-3bfce6f025ad$g$::uuid, null, null, $g$How to Propagate Rotala Rotundifolia: Topping and Side Shoots$g$, $g$Rotala rotundifolia grows fast from top cuttings and side shoots. Learn how to trim, replant and get dense bunches with pink tips.$g$, $g$Rotala rotundifolia is one of the fastest and easiest stem plants to multiply. Every trim gives you new cuttings, and the trimmed stems branch into bushier growth. In stronger light it turns pink to red at the tips. It is a Society class B plant because it rewards regular attention, but almost anyone with moderate light can turn a single bunch into a whole background.$g$, $g${"method": "Stem cuttings (topping) and side shoots from trimmed stems", "light": "Moderate to high; stronger light brings out pink and red tips", "co2": "Optional; CO2 gives denser, more colorful growth", "substrate": "Fine gravel, sand or soil; regular liquid fertilizer helps", "timeline": "Roots within about a week; side shoots in 1 to 3 weeks; fast growth after that", "first_steps": "Top the tallest stems, strip the bottom leaves and replant the tops"}$g$::jsonb, $g$[{"heading": "How Rotala Propagates", "text": "Rotala rotundifolia is a stem plant with small leaves along thin stems. A cut top roots quickly, and the stem left behind sprouts side shoots below the cut. It also sends out side shoots and sometimes creeping stems on its own. Plants grown out of water in nurseries have small round leaves; underwater it grows longer, narrower leaves, so new plants often change shape as they adapt."}, {"heading": "What You Need", "text": "- A healthy established bunch\n- Sharp, fine scissors and planting tweezers\n- Moderate to high light\n- A fertilizer routine, liquid or root tabs\n\nCO2 is not required, but it helps a great deal with density and color. Without CO2 the plant still grows and propagates, just with greener tips and more space between leaves."}, {"heading": "Step by Step", "text": "Wait until the stems reach near the surface. Cut the top 3 to 4 inches off each stem. Strip the leaves from the bottom inch of each cutting.\n\nPlant cuttings one or two at a time, about half an inch to an inch apart, pushed 1 inch into the substrate with tweezers. Planting stems individually gives a fuller result than pushing a fat bundle in at once.\n\nLeave the bottom stems in place. They will branch below the cut, usually within 1 to 3 weeks. Trimming at slightly different heights gives a rounded, bushy look."}, {"heading": "Caring for New Plants", "text": "Cuttings commonly root within about a week. Keep feeding regularly, since a fast grower uses up nutrients quickly. Watch for the lower leaves dropping as the bunch gets dense; this usually means the bottom is shaded, and it is time to trim and replant again.\n\nIn a tank with good light, fertilizer and CO2, Rotala can grow an inch or more a week. That speed is great for propagating but means it needs trimming every week or two once established. Keep an eye on slower plants nearby, since a thick Rotala bush can shade them out. Spare trimmings are easy to share with other hobbyists or move to another tank."}, {"heading": "Getting Color and Density", "text": "Pink and red tips come mostly from stronger light, and some hobbyists find lower nitrate levels help too. Frequent trimming makes the plant branch, which builds a dense bush. If stems look thin and stretched, the light is too weak or the stems are too crowded.\n\nRotala also grows well out of water. Some hobbyists keep a few stems in a humid container or the back of a riparium, where the plant keeps its round emersed leaves and grows steadily. Cuttings from emersed stems can be planted underwater the same way as any other top, and they will switch to narrow leaves over a few weeks. This is a handy way to keep a backup supply if your main tank has trouble.\n\nPale or yellowing new growth often points to a nutrient shortage, especially iron, so check your fertilizer routine before blaming the light."}, {"heading": "Rebuilding a Leggy Bunch", "text": "If the bottom of the group has gone bare, do not keep trimming the tops only. Pull the stems, cut the healthy tops, throw away the bare bottoms and replant the tops. This resets the bunch in an afternoon. Remove old stems fully so nothing is left to rot in the substrate, and do a water change afterward to clear any loose debris."}, {"heading": "Common Mistakes", "text": "- Waiting too long between trims, leaving bare lower stems\n- Planting thick bundles so the inside stems rot\n- Not fertilizing a fast growing plant\n- Mistaking the change from round emersed leaves to narrow submerged leaves for a problem\n- Letting floating trimmings drift into the filter"}]$g$::jsonb, $g$[{"q": "How do you propagate Rotala rotundifolia?", "a": "Cut the tops off the stems and replant them. The stems left behind will grow side shoots, so each trim makes more plants."}, {"q": "Does Rotala need CO2?", "a": "No, but CO2 makes growth denser and more colorful. It grows well enough without in moderate light."}, {"q": "How do I make Rotala turn red?", "a": "Stronger light is the main factor. Some keepers also find that lower nitrate brings out more pink."}, {"q": "Why are the leaves on my new Rotala changing shape?", "a": "Nursery plants are often grown out of water with round leaves. Underwater, new growth has narrower leaves, which is normal."}]$g$::jsonb, $g$Take a dated photo of the bunch before your first trim, then photograph the replanted tops and the new side shoots a few weeks later to show the plants multiplying.$g$),
  ($g$betta$g$, $g$4bebcdae-95c9-4293-a224-e63f98aaae52$g$::uuid, $g$betta$g$, null, $g$How to Breed Betta Fish: Bubble Nests, Spawning and Fry Care$g$, $g$Breeding bettas means a bubble nest, a careful introduction and hundreds of tiny fry. Learn the setup, spawning and how to raise and jar the young.$g$, $g$Breeding bettas is a classic project: the male builds a bubble nest, wraps the female in a spawning embrace and then guards the eggs himself. Spawns can be large, and raising hundreds of fry takes daily feeding, clean water and, later, a lot of jars for young males. It is very doable with planning, and watching a male tend his nest is one of the best shows in the hobby.$g$, $g${"method": "Bubble nester; male builds the nest and guards eggs and fry", "sexing": "Males have long fins and bright color; females have shorter fins and a white egg spot near the vent", "group": "One pair", "breeding_tank": "10 gallons, water 4 to 6 inches deep, sponge filter, floating leaf or plants, lid", "conditioning": "1 to 2 weeks of live or frozen foods such as bloodworms, brine shrimp and daphnia", "trigger": "A built bubble nest and a ripe female showing vertical bars and a swollen belly", "spawn": "Commonly from about 50 to several hundred eggs", "eggs": "About 24 to 48 hours to hatch at 80 to 82°F", "fry": "Hang tail down under the nest, then swim free about 2 to 3 days after hatching", "first_foods": "Infusoria, vinegar eels or microworms, then baby brine shrimp from about the first week", "grow_out": "Males usually need separating at about 8 to 10 weeks; sellable size at about 3 to 4 months", "parents": "Remove the female after spawning; male guards until fry swim free, then remove him"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank filled to only 4 to 6 inches works well. Shallow water makes it easier for the male to catch falling eggs and for fry to reach the surface. Keep it at 80 to 82°F with a heater and a sponge filter on very low flow, since strong currents break up the nest.\n\nGive the male something to build under: a floating leaf, a piece of plastic lid or floating plants. Add hiding spots for the female, such as stem plants or a cave, because the male can be rough. A snug lid keeps the air above the water warm and humid, which helps the fry when their labyrinth organ develops."}, {"heading": "Choosing and Conditioning the Pair", "text": "Choose a healthy male under about a year old and a female of similar size. A ripe female has a rounded belly, a visible white egg spot (ovipositor) between the ventral and anal fins, and often shows pale vertical bars when she is ready.\n\nCondition both separately for 1 to 2 weeks with live or frozen foods several times a day. Then put the male in the breeding tank and the female beside him in a clear container, a glass chimney or behind a divider, so they can see each other without contact. The male will usually start building a nest within a day or two."}, {"heading": "Spawning", "text": "Release the female once the nest is built and she is showing vertical bars and approaching the nest calmly. Expect some chasing and fin nipping. If the female is being badly torn and hides constantly, separate them and try again later.\n\nWhen she is ready, the male wraps around her under the nest. Eggs fall, and the male collects them in his mouth and spits them into the nest. This repeats many times over a few hours. Clutches are commonly from about 50 to several hundred eggs. Once she stops releasing eggs, remove the female so the male does not attack her, and treat any fin damage with clean water."}, {"heading": "Eggs and the Male's Care", "text": "Leave the male to tend the nest. He picks up any egg that falls and puts it back. At 80 to 82°F the eggs usually hatch in 24 to 48 hours. Newly hatched fry hang tail down from the nest and live off their yolk.\n\nDo not feed the male heavily during this time, and avoid disturbing the tank. About 2 to 3 days after hatching the fry begin swimming horizontally. This is the time to remove the male, as he may start eating them."}, {"heading": "Raising the Fry", "text": "Betta fry are small and need tiny live foods several times a day.\n\n- Days 1 to 5 of free swimming: infusoria, vinegar eels or microworms\n- From about the first week: newly hatched baby brine shrimp\n- From week 3 or 4: add finely crushed flake or micro pellets\n\nStart small water changes, about 10 percent every day or two, once the fry are swimming, and raise the water level slowly. Keep the lid on. Around 3 to 6 weeks the fry develop their labyrinth organ and start gulping air, and cold drafts at the surface can be deadly."}, {"heading": "Growing Out and Jarring", "text": "Move the fry to a larger tank as they grow, with frequent water changes. Sort out larger fish so small ones are not outcompeted. At about 8 to 10 weeks males usually start to show longer fins and to fight. Move each male into his own jar or small container to protect his fins. Females can often stay together. Most bettas reach a sellable size at about 3 to 4 months."}, {"heading": "Common Mistakes", "text": "- Releasing the female before she is ready, leading to serious injuries\n- Strong filter flow that breaks the nest\n- Leaving the female or male in too long\n- Feeding baby brine shrimp before the fry can eat it\n- No lid, so cold air hits fry when they start breathing air\n- Not planning room and jars for dozens of males"}]$g$::jsonb, $g$[{"q": "How long do betta eggs take to hatch?", "a": "Usually about 24 to 48 hours at 80 to 82°F. The fry swim freely about 2 to 3 days after that."}, {"q": "Do male bettas eat their fry?", "a": "Males care for eggs and fry at first, but often start eating fry once they swim freely. Remove him when the fry are swimming horizontally."}, {"q": "How do I know my female betta is ready to breed?", "a": "A ready female has a rounded belly, a visible white egg spot and often shows pale vertical bars. She will approach the nest rather than flee."}, {"q": "How many babies do bettas have?", "a": "Spawns commonly range from about 50 to several hundred eggs, and not all will survive to adulthood."}]$g$::jsonb, $g$Open your log while the pair are still separated and photograph them in the breeding tank with your challenge code card. For stage 2, a clear photo of the bubble nest with eggs in it works well.$g$),
  ($g$dwarf-gourami$g$, $g$ec86a34c-c25e-4b7a-ad31-c37a907904d4$g$::uuid, $g$dwarf-gourami$g$, null, $g$How to Breed Dwarf Gouramis: Bubble Nests and Tiny Fry$g$, $g$Dwarf gouramis build plant-woven bubble nests and lay hundreds of eggs. The challenge is very tiny fry that need infusoria and warm, humid air.$g$, $g$Dwarf gouramis are bubble nesters that weave bits of plant into their nests, and the male guards the eggs with real dedication. Spawns are large, but the fry are extremely small, which is why this fish sits in Society class C. If you can culture infusoria and keep the tank warm and covered, raising a batch of dwarf gouramis is a great step up from easier species.$g$, $g${"method": "Bubble nester; male builds a nest with plant bits and guards eggs and fry", "sexing": "Males have bright red and blue stripes; females are silvery gray with faint stripes", "group": "One pair, or one male with two females in a larger tank", "breeding_tank": "10 to 20 gallons, water about 6 inches deep, floating plants, gentle sponge filter, lid", "conditioning": "1 to 2 weeks of live or frozen foods such as bloodworms and brine shrimp", "trigger": "Warm, shallow, soft water around 80 to 82°F and a ripe, rounded female", "spawn": "Commonly several hundred eggs", "eggs": "Usually hatch in about 12 to 24 hours at 80 to 82°F", "fry": "Free swimming about 3 days after hatching; extremely small", "first_foods": "Infusoria or paramecium for the first week or so, then baby brine shrimp and microworms", "grow_out": "About 3 to 4 months to a sellable size", "parents": "Remove the female after spawning; remove the male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Use a 10 to 20 gallon tank with the water lowered to about 6 inches. Aim for 80 to 82°F, which sits at the top of the normal care range, and softer, slightly acidic water around pH 6.5 to 7. Use a sponge filter on its lowest setting.\n\nFloating plants such as riccia, salvinia or water sprite give the male material to weave into his nest. Add some stem plants as cover for the female. Keep a tight lid on the tank to hold warm, humid air above the water."}, {"heading": "Choosing and Conditioning the Pair", "text": "Male dwarf gouramis are easy to spot, with bright red and blue stripes. Females are silvery gray and harder to find in stores, so you may have to ask. Look for healthy, active fish from a reliable source, since dwarf gouramis are known to suffer from disease in some imported stock.\n\nCondition the pair separately for 1 to 2 weeks with frozen or live bloodworms, brine shrimp and quality flake. A ready female looks noticeably full in the belly."}, {"heading": "Spawning", "text": "Put the male into the breeding tank first and give him a day or two to build. His nest is a mat of bubbles mixed with plant pieces, often several inches wide. Then add the female.\n\nThe male displays and leads her under the nest. The pair embrace, the male wrapping around her, and eggs float up into the nest. This repeats many times over a few hours. Clutches commonly run to several hundred eggs. Remove the female when she is done, as the male becomes aggressive toward her."}, {"heading": "Eggs and Hatching", "text": "The male guards the nest and returns any eggs that fall. At 80 to 82°F the eggs usually hatch within about a day. The fry stay in the nest on their yolk sacs, then become free swimming roughly 3 days after hatching. Remove the male at this point."}, {"heading": "Raising the Fry", "text": "Dwarf gourami fry are among the smallest common aquarium fry. Start infusoria cultures a week before spawning.\n\n- Week 1 of free swimming: infusoria or paramecium several times a day\n- Week 2: add vinegar eels, microworms and newly hatched baby brine shrimp as they grow\n- Week 4 on: crushed flake and larger live foods\n\nAn airstone and a few snails help keep a small fry tank clean, since leftover infusoria and dead fry foul water quickly. Make very small water changes, around 10 percent every couple of days, using water of the same temperature. Keep the lid on. The labyrinth organ develops at around 3 to 6 weeks, and a chill at the surface can cause heavy losses."}, {"heading": "Growing Out", "text": "Move the fry to a larger tank once they are eating baby brine shrimp well, and raise the water level gradually. Sort by size, since bigger siblings can outcompete smaller ones. Males begin to show color at a couple of months, and most reach a sellable size at about 3 to 4 months.\n\nFeed growing juveniles several small meals a day of baby brine shrimp, crushed flake and small frozen foods. Keep up water changes of 20 to 30 percent a week once they are in the larger tank. Plan where the young fish will go before they get big: a good spawn can leave you with far more gouramis than one tank can hold, and young males may start squabbling as they mature."}, {"heading": "Common Mistakes", "text": "- No infusoria ready when fry swim free\n- Strong flow breaking up the nest\n- Leaving the female in after spawning\n- Lifting the lid and letting cold air in during the labyrinth stage\n- Overfeeding liquid foods and fouling the water"}]$g$::jsonb, $g$[{"q": "How long does it take dwarf gourami eggs to hatch?", "a": "Usually about 12 to 24 hours at 80 to 82°F. The fry swim freely about 3 days later."}, {"q": "How can you tell a male dwarf gourami from a female?", "a": "Males are brightly striped in red and blue. Females are silvery gray with faint stripes and less color."}, {"q": "Do dwarf gouramis eat their babies?", "a": "The male guards the eggs, but adults may eat fry once they swim freely. Remove the female after spawning and the male when the fry swim."}, {"q": "What do dwarf gourami fry eat?", "a": "Their first food needs to be very small, such as infusoria or paramecium. After about a week, add microworms and baby brine shrimp."}]$g$::jsonb, $g$Photograph the pair with your challenge code card when you open the log, before the nest is built. Infusoria is the bottleneck, so get cultures going before stage 2 so you reach stage 3 smoothly.$g$),
  ($g$sparkling-gourami$g$, $g$286ec8e6-5447-41d6-918c-68a22b58cf02$g$::uuid, $g$sparkling-gourami$g$, null, $g$How to Breed Sparkling Gouramis: Croaking, Nests and Fry$g$, $g$Sparkling gouramis build small bubble nests under leaves and lay small clutches. Fry are minute, so infusoria is essential. A good class C project.$g$, $g$Sparkling gouramis are tiny, croaking labyrinth fish that spawn readily in a quiet, planted tank. The male builds a small bubble nest, often under a leaf, and guards it. Getting a spawn is not the hard part. The fry are among the smallest you will ever raise, which is what puts this species in Society class C. With infusoria ready and a calm setup, it is a very satisfying breeding project.$g$, $g${"method": "Bubble nester; small nest often under a leaf or in a cave, guarded by the male", "sexing": "Hard; females show a pale egg mass through the belly when backlit, males have longer, more colorful fins", "group": "One pair, or a small group in a heavily planted tank", "breeding_tank": "5 to 10 gallons, dense plants, floating plants, sponge filter on low, lid", "conditioning": "1 to 2 weeks of small live or frozen foods such as daphnia, brine shrimp and grindal worms", "trigger": "Warm water around 78 to 82°F, soft and slightly acidic, still surface, ripe female", "spawn": "Commonly a few dozen to around 150 small eggs", "eggs": "Breeders report roughly 1 to 3 days to hatch at 78 to 82°F", "fry": "Free swimming a few days after hatching; extremely small", "first_foods": "Infusoria or paramecium for 1 to 2 weeks, then vinegar eels, microworms and baby brine shrimp", "grow_out": "Slow; about 3 to 4 months to near adult size", "parents": "Male guards eggs; remove the female after spawning and the male once fry swim free"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is plenty. Keep it at 78 to 82°F with soft, slightly acidic water around pH 6 to 7. Leaf litter and a few alder cones are popular for a slightly tinted, calm environment.\n\nPlant it heavily with stem plants or moss and add floating plants to calm the surface. Give the male a broad leaf, a small cave or a film canister on its side, since many males build under cover rather than at the open surface. Use a sponge filter barely bubbling and keep a lid on to hold warm, humid air."}, {"heading": "Sexing and Conditioning", "text": "Sexing sparkling gouramis is honestly tricky. The most reliable sign is in the female: shine a light from behind and you can often see a pale, yellowish egg mass in her belly. Males tend to have longer, more pointed fins and brighter color, but this varies. Buying a group of 5 or 6 and letting pairs form is the easiest way to get a true pair.\n\nCondition with small live and frozen foods for 1 to 2 weeks. You may hear the fish croaking during displays, which is normal."}, {"heading": "Spawning", "text": "The male builds a small bubble nest, usually under a leaf or in a cave. He displays to the female, and the pair embrace under the nest in a series of short spawning bouts. Eggs are placed into the nest. Clutches are small, commonly a few dozen and sometimes up to around 150.\n\nRemove the female after spawning, or make sure the tank is planted heavily enough for her to keep away from the male."}, {"heading": "Eggs and Hatching", "text": "The male tends the nest. Breeders report the eggs hatching in roughly 1 to 3 days at these temperatures. The fry stay in or near the nest for a few days on their yolk before they become free swimming. Keep the tank undisturbed and avoid water changes while the nest is active. Do not lift leaves to check on the nest, as a disturbed male may eat the eggs. Many breeders remove the male once the fry are swimming."}, {"heading": "Raising the Fry", "text": "These fry are minute. Start infusoria or paramecium cultures before you set up the pair.\n\n- Weeks 1 to 2: infusoria or paramecium several times a day\n- From about week 2: vinegar eels and microworms\n- From about weeks 3 to 4: newly hatched baby brine shrimp\n\nLet the planted tank help. Biofilm on plants and leaves gives fry extra grazing. Change only small amounts of water, about 10 percent twice a week, matched carefully for temperature. Keep the lid on through the labyrinth stage."}, {"heading": "Growing Out", "text": "Sparkling gouramis grow slowly. Expect about 3 to 4 months to near adult size, and color appears gradually. Keep feeding small foods several times a day and keep the water clean. A batch can stay together, as they are peaceful.\n\nOnce the young fish are taking baby brine shrimp well, move them to a slightly larger planted tank and increase water changes to about 20 percent a week. Young fish begin to croak and display before they are full size. Keep a few of the best fish to become your next breeding group, and pass the rest on to other members once they are big enough to handle a move."}, {"heading": "Common Mistakes", "text": "- Starting baby brine shrimp too early, before the fry can eat it\n- Strong flow or an open surface that disturbs the nest\n- Large water changes with mismatched temperature\n- Assuming two fish are a pair without checking for a female's egg mass\n- Removing the lid during the labyrinth stage"}]$g$::jsonb, $g$[{"q": "How do you tell male and female sparkling gouramis apart?", "a": "It is hard. Backlit females often show a pale egg mass in the belly, while males usually have longer fins and stronger color."}, {"q": "Why do sparkling gouramis make noise?", "a": "They make a croaking sound with their pectoral fins during displays, which is part of courtship and territorial behavior."}, {"q": "How many eggs do sparkling gouramis lay?", "a": "Clutches are small, commonly a few dozen and sometimes up to around 150 eggs."}, {"q": "What do sparkling gourami fry eat?", "a": "They need very tiny foods like infusoria or paramecium for the first week or two, then microworms and baby brine shrimp."}]$g$::jsonb, $g$Because sexing is hard, include a backlit photo of the female showing her egg mass along with your challenge code card in stage 1. A clear shot of eggs in the nest under a leaf makes a strong stage 2 entry.$g$),
  ($g$celestial-pearl-danio$g$, $g$d5971774-19d5-47a1-a916-4ff3ce362e8f$g$::uuid, $g$celestial-pearl-danio$g$, null, $g$How to Breed Celestial Pearl Danios: Moss, Eggs and Fry$g$, $g$Celestial pearl danios scatter small batches of eggs into moss. Remove the eggs or adults, then raise the tiny fry on infusoria and baby brine shrimp.$g$, $g$Celestial pearl danios spawn often but lay only a small number of eggs at a time, scattering them into moss and fine plants near the bottom. The adults eat eggs, so most success comes from collecting eggs or moving the adults. The fry are small and shy and need tiny first foods, which is why this lovely fish sits in Society class C rather than with the easy danios.$g$, $g${"method": "Egg scatterer; small batches laid in moss and fine plants near the bottom", "sexing": "Males have brighter red orange fins and a deeper blue body; females are duller and rounder", "group": "A group of 2 or 3 males to 4 to 6 females, or one male with 2 or 3 females", "breeding_tank": "5 to 10 gallons, java moss or spawning mops, sponge filter, soft light", "conditioning": "1 to 2 weeks of small live and frozen foods: daphnia, baby brine shrimp, cyclops", "trigger": "Conditioned females, fresh water and plenty of moss; spawning is ongoing in mature groups", "spawn": "Commonly around 10 to 30 eggs per spawning", "eggs": "Commonly about 3 days to hatch at 72 to 76°F", "fry": "Cling to surfaces for a couple of days, then swim free; tiny and hide near the bottom", "first_foods": "Infusoria, vinegar eels and powdered fry food, then baby brine shrimp after about 1 week", "grow_out": "About 2 to 3 months to adult size and color", "parents": "No care; adults eat eggs, so remove adults after a few days or move moss with eggs"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank with a sponge filter is ideal. Fill much of the bottom with java moss, other fine-leaved moss or a spawning mop. Keep the water at 72 to 76°F, inside the care range of 68 to 78°F, with soft to moderately hard water around pH 6.5 to 7.5. Dim lighting or floating plants help these shy fish settle. A small hatching container with a gentle airstone is useful if you plan to collect eggs."}, {"heading": "Choosing and Conditioning the Group", "text": "Males have bright red orange fins with bold dark bars and a deeper blue body. Females are a little rounder and paler, with more orange than red in the fins. Males spar constantly but rarely cause harm.\n\nCondition the group with small live and frozen foods, such as daphnia, baby brine shrimp and cyclops, for 1 to 2 weeks. Well-fed females fill out noticeably."}, {"heading": "Spawning", "text": "Spawning happens near the bottom. A male displays to a female, leads her into the moss, and the pair release a few eggs at a time. Each session gives a small number, commonly around 10 to 30 eggs. In a mature group spawning can happen nearly every day.\n\nThere are two common methods. You can move a male and two or three females to the breeding tank for 3 to 5 days, then remove them. Or you can lift the moss every few days from the main tank into a separate container and let the eggs hatch there."}, {"heading": "Eggs and Hatching", "text": "The eggs are tiny and clear, and hard to see in moss. They commonly hatch in about 3 days at 72 to 76°F. Fry then hang on the glass and plants for a couple of days before swimming freely. Remove any eggs that turn white. A little methylene blue in a separate hatching container can help some breeders, but keep it out of a tank with moss and plants."}, {"heading": "Raising the Fry", "text": "CPD fry are very small and spend their first weeks near the bottom, hiding in moss.\n\n- Week 1: infusoria, vinegar eels and powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp and microworms\n- Week 4 on: crushed flake and small frozen foods\n\nFeed small amounts several times a day. Change about 10 to 20 percent of the water every couple of days with matched water. A clean bottom is important, so remove leftover food gently with a pipette. A small amount of moss in the fry tank gives them cover and a surface for biofilm to grow."}, {"heading": "Growing Out", "text": "Growth is slow at first and speeds up once the fry take baby brine shrimp. Juveniles start to show spots and fin color at around 6 to 8 weeks, and reach adult size and full color at about 2 to 3 months. Raising them in a planted tank with plenty of small foods gives the best color.\n\nMove the fry to a larger tank, 10 to 20 gallons, once they are taking baby brine shrimp well. Increase water changes to 20 to 30 percent a week. Sort out the largest fish if smaller ones fall behind. CPDs are peaceful as juveniles, but young males start sparring as their color appears, so give them plants and space. Keep a few of your best fish to start the next generation."}, {"heading": "Common Mistakes", "text": "- Leaving eggs in with the adults\n- Too little moss, so eggs are eaten as soon as they are laid\n- Missing the fry, which hide near the bottom for days\n- Large, sudden water changes\n- Expecting large spawns; this is a small batch fish"}]$g$::jsonb, $g$[{"q": "How long do celestial pearl danio eggs take to hatch?", "a": "They commonly hatch in about 3 days at 72 to 76°F. The fry swim freely a couple of days later."}, {"q": "Do celestial pearl danios eat their eggs?", "a": "Yes. Collect moss with eggs into a separate container, or remove the adults after a few days in the breeding tank."}, {"q": "How do I sex celestial pearl danios?", "a": "Males have brighter red orange fins and a deeper blue body. Females are paler and rounder, with more orange in the fins."}, {"q": "Why can't I see my CPD fry?", "a": "They are tiny and hide near the bottom and in moss for the first couple of weeks. Look closely with a flashlight at the glass and moss."}]$g$::jsonb, $g$Photograph your breeding group in the moss tank with your challenge code card before moving any eggs. Since the eggs are hard to spot, a close up of a few eggs in moss or in the hatching container makes a clear stage 2 photo.$g$),
  ($g$chili-rasbora$g$, $g$84ed958c-cef3-4cb0-9a73-e7c86c45d30f$g$::uuid, $g$chili-rasbora$g$, null, $g$How to Breed Chili Rasboras: Moss Tanks and Tiny Fry$g$, $g$Chili rasboras scatter a few eggs a day in soft water and moss. The real challenge is keeping the tiny fry alive on infusoria and biofilm.$g$, $g$Chili rasboras are tiny, peaceful fish that spawn a few eggs at a time, often every day, in fine plants and moss. Adults will eat eggs and fry, so a mature, mossy tank and a little patience make all the difference. The fry are barely visible at first, and soft, clean water is a must. With the right setup this is a satisfying class C project that rewards careful keepers.$g$, $g${"method": "Egg scatterer; a few eggs at a time into moss and fine plants", "sexing": "Males are slimmer with deeper red color; females are rounder and paler", "group": "A group of 6 to 10 adults, or one male with two females", "breeding_tank": "5 to 10 gallons, java moss, soft acidic water, sponge filter, dim light", "conditioning": "1 to 2 weeks of tiny live and frozen foods: daphnia, cyclops, baby brine shrimp", "trigger": "Soft, acidic water around pH 6, steady warm temps and lots of moss", "spawn": "A few eggs per spawning, often repeated daily", "eggs": "Commonly about 1 to 2 days to hatch at 77 to 80°F", "fry": "Free swimming after a few more days; extremely small", "first_foods": "Infusoria, paramecium and biofilm, then vinegar eels and baby brine shrimp after about 2 weeks", "grow_out": "About 3 months to near adult size", "parents": "No care; adults eat eggs and fry, so remove them after a few days or keep a dense moss tank"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is ideal. Use soft, acidic water: around pH 5.5 to 6.5 and GH 1 to 6, which matches the care range of pH 4 to 7. Keep the temperature at 77 to 80°F.\n\nFill a good part of the bottom with java moss or another fine moss, and add leaf litter and floating plants to dim the light. A sponge filter on a low setting keeps the water clean without sucking up fry. Mature tanks with established biofilm give much better results than new ones. If you can, let the tank run with moss and leaves for a month or more before adding the fish."}, {"heading": "Sexing and Conditioning", "text": "Males are slimmer and show more intense red color, especially when displaying. Females are rounder and paler. In practice, keeping a group of 6 to 10 gives you both sexes.\n\nCondition the group for 1 to 2 weeks with tiny live and frozen foods such as daphnia, cyclops and baby brine shrimp. Small, frequent meals work better than big ones for fish this size."}, {"heading": "Spawning", "text": "Chili rasboras spawn in moss and fine plants. A male shows his color and leads a female into the moss, where they release a few eggs. They tend to spawn often but in very small numbers, so you will not see a big event.\n\nTwo approaches work. One is to move a group into the breeding tank for about a week, then remove the adults. The other is to keep a heavily planted, species-only tank and let fry appear among the moss. This second method gives fewer fry but is less work."}, {"heading": "Eggs and Hatching", "text": "The eggs are tiny and very hard to find. They commonly hatch in about 1 to 2 days at 77 to 80°F, and the fry become free swimming a few days later. Keep the water stable and avoid disturbing the moss while you wait."}, {"heading": "Raising the Fry", "text": "Chili rasbora fry are some of the smallest fry in the hobby.\n\n- Weeks 1 to 2: infusoria, paramecium and the biofilm on moss and leaves\n- Weeks 2 to 3: vinegar eels and microworms\n- From about week 3: newly hatched baby brine shrimp\n\nFeed a little several times a day and keep a strong infusoria culture going so you never run short. Snails and a small amount of moss help clean up leftover food. Change about 10 percent of the water twice a week using soft water of the same temperature. Clean water matters, but large changes can do more harm than good."}, {"heading": "Growing Out", "text": "Growth is slow. Juveniles reach near adult size in about 3 months, and red color develops gradually. Keep them in soft water and feed small live foods to bring out the best color.\n\nOnce they are taking baby brine shrimp, move the young fish to a larger planted tank and increase water changes to about 20 percent a week, still using soft water. They can be sexed once color comes in. Chili rasboras are best kept and sold in groups, so wait until most of the batch is well colored before passing them on. Keep a group of your best fish to start the next generation."}, {"heading": "Common Mistakes", "text": "- Hard or alkaline water, which reduces spawning and egg survival\n- Leaving adults in with eggs and fry\n- A brand new tank without biofilm or infusoria\n- Big water changes with mismatched water\n- Giving up too soon; small spawns add up over weeks"}]$g$::jsonb, $g$[{"q": "How long do chili rasbora eggs take to hatch?", "a": "Breeders commonly report about 1 to 2 days at 77 to 80°F, with fry swimming freely a few days after that."}, {"q": "Do chili rasboras eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so remove them after spawning or keep plenty of dense moss for cover."}, {"q": "How do you tell male and female chili rasboras apart?", "a": "Males are slimmer and more intensely red. Females are rounder and paler."}, {"q": "What do baby chili rasboras eat?", "a": "They need very tiny foods like infusoria, paramecium and biofilm at first. Add microworms and baby brine shrimp as they grow."}]$g$::jsonb, $g$Photograph your group in the moss tank with your challenge code card before any spawning. Because the eggs are so small, many breeders document stage 2 by showing the first wrigglers on the glass or moss, so plan your stage 3 photos at least 3 days later.$g$),
  ($g$scissortail-rasbora$g$, $g$bb1c6ce7-a48a-4d18-bf9c-641075bf1267$g$::uuid, $g$scissortail-rasbora$g$, null, $g$How to Breed Scissortail Rasboras: Group Spawning and Fry$g$, $g$Scissortail rasboras scatter eggs in a group spawning tank. Protect the eggs from the adults with mesh or plants, then raise fry on infusoria.$g$, $g$Scissortail rasboras are active schooling fish that scatter eggs over fine plants and the bottom of the tank, and they will eat every egg they find. Breeding them is about giving them room, conditioning a group well and protecting the eggs. The fry are small but manageable once they reach baby brine shrimp, which makes this a solid Society class C project for anyone with a spare long tank.$g$, $g${"method": "Egg scatterer; group spawner over fine plants and the bottom", "sexing": "Females are larger and deeper bodied, especially when full of eggs; males are slimmer", "group": "A small group, about 2 males to 3 or 4 females", "breeding_tank": "20 gallon long or larger, mesh or marbles on the bottom, fine plants or mops, sponge filter", "conditioning": "1 to 2 weeks of live and frozen foods: bloodworms, brine shrimp, daphnia", "trigger": "Conditioned females, a water change with soft, slightly acidic water and morning light", "spawn": "Spawns can be large, often a hundred or more small eggs", "eggs": "Commonly about 1 to 2 days to hatch at 77 to 80°F", "fry": "Free swimming a few days after hatching; small and best kept with gentle flow", "first_foods": "Infusoria or liquid fry food for about a week, then baby brine shrimp", "grow_out": "About 2 to 3 months to around an inch", "parents": "No care; adults eat eggs, so remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Scissortails are fast swimmers, so use at least a 20 gallon long tank for the spawning group. Cover the bottom with plastic mesh raised slightly, a layer of marbles, or a thick mat of java moss so eggs fall out of reach. Add spawning mops or fine-leaved plants in the middle of the tank.\n\nKeep the water at 77 to 80°F. They live happily in a wide range, pH 6 to 7.5, but softer, slightly acidic water around pH 6.5 is commonly used for spawning. A sponge filter is best, and a lid is a must because they jump."}, {"heading": "Choosing and Conditioning the Group", "text": "Sexing is easiest in mature fish. Females are larger and deeper bodied, and they look clearly rounded when full of eggs. Males are slimmer and often a little brighter. A group of 5 to 7 with more females than males works well.\n\nCondition the adults for 1 to 2 weeks with plenty of live and frozen foods such as bloodworms, brine shrimp and daphnia, plus quality flake. Some breeders keep the sexes apart during conditioning and put them together in the evening, which often brings on spawning the next morning."}, {"heading": "Spawning", "text": "Spawning usually starts in the early morning. Males chase females through the plants and the group releases eggs and milt in quick bursts. The eggs are small and slightly sticky, and many fall to the bottom. A good spawn can produce a hundred or more eggs.\n\nAs soon as spawning stops, remove the adults. They will search for and eat any eggs they can reach."}, {"heading": "Eggs and Hatching", "text": "Eggs commonly hatch in about 1 to 2 days at 77 to 80°F. The fry then hang on the glass and plants while they absorb the yolk, and become free swimming a few days later.\n\nRemove eggs that turn white and fuzzy, since fungus can spread. Dim light helps, and a few alder cones or a little methylene blue in a separate hatching container are used by some breeders."}, {"heading": "Raising the Fry", "text": "Feed small amounts several times a day.\n\n- Week 1 of free swimming: infusoria, green water or liquid fry food\n- Weeks 2 to 3: newly hatched baby brine shrimp and microworms\n- Week 4 on: crushed flake and small frozen foods\n\nStart water changes of 10 to 20 percent every couple of days once the fry are eating, matched for temperature. Keep the sponge filter gentle. Fry from a large spawn grow at different rates, so sort them by size if needed."}, {"heading": "Growing Out", "text": "Move the young fish to a bigger tank once they are eating baby brine shrimp well. With regular feeding and weekly water changes of 20 to 30 percent, they reach about an inch in 2 to 3 months, and the dark tail markings that give them their name show early. Give them swimming room, as they are active even when young.\n\nA large spawn can quickly outgrow a single tank. Plan a 20 to 30 gallon grow-out tank, or split the batch across two tanks, so the young fish are not stunted by crowding. Keep a few of the best grown fish from each batch to build your next breeding group, choosing deep-bodied females and active, well-colored males."}, {"heading": "Common Mistakes", "text": "- Leaving adults in after spawning\n- No mesh, marbles or moss to protect eggs\n- A tank that is too small for an active schooling fish\n- No lid; scissortails jump\n- Starting baby brine shrimp before the fry can eat it\n- Not sorting fry by size from a large spawn"}]$g$::jsonb, $g$[{"q": "How do scissortail rasboras breed?", "a": "They are egg scatterers that spawn as a group in fine plants and over the bottom. Adults eat the eggs, so they should be removed after spawning."}, {"q": "How do you tell male and female scissortail rasboras apart?", "a": "Females are larger and deeper bodied, especially when carrying eggs. Males are slimmer."}, {"q": "How long do scissortail rasbora eggs take to hatch?", "a": "Commonly about 1 to 2 days at 77 to 80°F. Fry swim freely a few days after hatching."}, {"q": "What do scissortail rasbora fry eat?", "a": "Start with infusoria or liquid fry food for about a week, then move them to baby brine shrimp."}]$g$::jsonb, $g$Photograph the conditioned group in the spawning tank with your challenge code card when you open the log. Eggs on the mesh or marbles after spawning make a clear stage 2 photo.$g$),
  ($g$aponogeton$g$, $g$122d6865-3f87-416e-9455-dcc04d58f5fb$g$::uuid, null, null, $g$How to Propagate Aponogeton Ulvaceus: Seeds and Tubers$g$, $g$Aponogeton ulvaceus is propagated mainly from seed after flowering. Learn how to collect seeds, raise seedlings and handle the plant's rest periods.$g$, $g$Aponogeton ulvaceus grows from a tuber and, when healthy, sends flower spikes to the surface. Unlike plants that send out runners, its main route to new plants is seed. Many keepers find it sets seed readily in the aquarium, and the seedlings grow into new tubers. It takes patience and a well-fed mother plant, which is why it is a Society class C plant.$g$, $g${"method": "Seeds from flower spikes; tuber division is rarely practical", "light": "Moderate light; very strong light is not needed", "co2": "Not required", "substrate": "Nutrient rich substrate or gravel with root tabs near the tuber", "timeline": "Flowers after months of good growth; seeds sprout within days to a few weeks", "first_steps": "Grow the mother plant to flowering, then help pollination by gently brushing the flower spikes"}$g$::jsonb, $g$[{"heading": "How Aponogeton Ulvaceus Propagates", "text": "Aponogeton ulvaceus grows from a tuber planted in the substrate. A well-established plant sends long stalks to the surface, each ending in a flower spike, often split into two or more parts. Many keepers report that this species sets seed in the aquarium more readily than most aponogetons, especially if the flowers are helped along.\n\nThe tuber itself does not divide reliably. Occasionally an old tuber produces a small side tuber, but propagation from seed is the usual method."}, {"heading": "What You Need", "text": "- A healthy, well-established plant that has been growing for several months\n- A nutrient rich substrate or root tabs near the tuber\n- Moderate light\n- A soft brush or your fingertip for the flowers\n- A shallow container or a quiet corner of a tank for seedlings\n\nAponogeton ulvaceus is a large plant with long, wavy, see-through leaves, so give the mother plant plenty of space. It does not need CO2. Floating plants above it can block the flower stalks from reaching the surface, so keep a gap in the cover above the mother plant when it starts to send up spikes."}, {"heading": "Step by Step", "text": "When the flower spike opens above the water, gently brush the flowers with a soft brush or fingertip every day or two to move pollen around. Leave the spike in place as it fades.\n\nIf seeds develop, they ripen on the spike over a few weeks. Ripe seeds drop into the water, float for a short time and then sink. You can collect them as they fall, or let them settle in the tank.\n\nPlace seeds on the surface of fine substrate in a shallow container or in a calm, bright spot of a tank. Breeders commonly report seeds sprouting within days to a few weeks. Once a seedling has a few leaves, plant it in the substrate with its tiny tuber just at the surface."}, {"heading": "Caring for Seedlings", "text": "Seedlings grow slowly at first while they build a tuber. Keep them in moderate light and add a small piece of root tab nearby once they are planted. Over a few months the young plants grow larger leaves. Keep snails and grazing fish away from very young seedlings.\n\nAs the seedlings grow, give each one its own space, several inches apart at first and more as they mature. A full grown Aponogeton ulvaceus can fill a large part of a tank with its long leaves, so most keepers move extra young plants to other tanks or share them with other hobbyists. Young plants usually reach a good size within several months in a well-fed tank, and may flower themselves once they are mature."}, {"heading": "Understanding Rest Periods", "text": "Aponogetons from Madagascar can go through a rest period after many months of growth. Leaves slow down and die back, leaving the tuber bare. Many keepers simply leave the tuber in place and wait for new growth. Others lift it and store it cool in damp sand for a few weeks before replanting. Either way, do not throw a leafless tuber away, as it is often still alive. A healthy tuber feels firm; a soft, mushy tuber has rotted and should be removed."}, {"heading": "Common Mistakes", "text": "- Burying the tuber deeply, which can cause rot\n- Cutting the flower spike too soon\n- Expecting flowers from a newly planted tuber\n- Throwing out a dormant tuber\n- Not feeding the roots, which leads to weak plants that never flower"}]$g$::jsonb, $g$[{"q": "How do you propagate Aponogeton ulvaceus?", "a": "Mainly from seed. Help the flowers pollinate by gently brushing them, then collect the seeds that drop and let them sprout in a shallow, calm spot."}, {"q": "Why did my Aponogeton lose all its leaves?", "a": "It may be going through a rest period. Leave the tuber in place or store it cool and damp, and new leaves often return."}, {"q": "Can you divide an Aponogeton bulb?", "a": "The tuber does not divide reliably. Seeds are the usual way to get new plants."}, {"q": "Does Aponogeton ulvaceus need CO2?", "a": "No. Moderate light and a nutrient rich substrate or root tabs are enough."}]$g$::jsonb, $g$Take dated photos of the flower spike above the water, the seeds or seedlings, and the young plants after planting. Keep a simple log of dates from flowering to sprouting so your entry shows the whole cycle.$g$),
  ($g$monte-carlo$g$, $g$2daa5f88-79a5-4e0f-a32d-e9a866a4d0f0$g$::uuid, null, null, $g$How to Propagate Monte Carlo: Runners, Portions and Carpets$g$, $g$Monte Carlo spreads by creeping runners into a dense carpet. Learn how to split portions, plant small clumps and grow a carpet with or without CO2.$g$, $g$Monte Carlo (Micranthemum tweediei) is a carpeting plant that creeps across the substrate on thin runners, rooting as it goes. Propagation is simple: split portions off and plant them where you want more carpet. The challenge is getting it to grow fast and low rather than stringy. With enough light, a fine substrate and ideally CO2, it can cover the foreground in a couple of months.$g$, $g${"method": "Runners; creeping stems root at the nodes and can be split into small portions", "light": "Moderate to high; low light gives tall, stringy growth", "co2": "Strongly recommended for a dense carpet; slow growth without", "substrate": "Fine grained soil or fine gravel that small roots can grip", "timeline": "New runners within about 2 to 3 weeks; a full carpet in roughly 1 to 3 months", "first_steps": "Split a mat into thumbnail-sized clumps and plant them an inch or two apart"}$g$::jsonb, $g$[{"heading": "How Monte Carlo Propagates", "text": "Monte Carlo grows as creeping stems with small, round leaves. The stems spread across the substrate and send roots down at the leaf nodes. Each rooted section can live on its own, so any piece with a few leaves and roots can be cut off and planted. Monte Carlo can also be grown out of water in a humid setup, and many nursery pots arrive in this emersed form, which is why new plants sometimes look a little different once they adjust underwater.\n\nIn good conditions the plant spreads on its own into a thick mat. You speed things up by splitting it into many small clumps and spacing them out."}, {"heading": "What You Need", "text": "- A healthy portion or pot of Monte Carlo\n- Fine substrate, ideally an aquarium soil\n- Moderate to high light\n- CO2 injection for the best results\n- Fine scissors and planting tweezers\n\nMonte Carlo is a little more forgiving than some carpet plants and can grow without CO2, but growth is slow and the carpet is thinner. With CO2 and good light it spreads quickly."}, {"heading": "Step by Step", "text": "Remove any rock wool or pot material from new plants. Gently pull or cut the mat into small clumps, each about the size of a thumbnail with a few stems and roots.\n\nPush each clump into the substrate with tweezers, leaving the leaves just above the surface. Space clumps about 1 to 2 inches apart in a grid. Closer spacing fills in sooner. Planting at an angle, with the stems leaning slightly, helps hold the clumps down until roots take hold.\n\nAs the clumps send runners outward, you can also trim edge pieces from the established carpet and replant them into bare areas."}, {"heading": "The Dry Start Method", "text": "Some hobbyists start Monte Carlo out of water. Plant the clumps in moist substrate, keep the tank covered with plastic wrap to hold humidity, mist daily and leave the lights on a normal schedule. After about 4 to 6 weeks the carpet has rooted well, and you can slowly flood the tank. This avoids floating pieces and gives a strong root system before fish go in.\n\nWatch for mold during a dry start. Small patches can usually be removed and the area aired out. When you flood the tank, pour water slowly over a plate or bag so the substrate is not disturbed, and expect a short adjustment period as the leaves switch to underwater growth."}, {"heading": "Caring for New Plants", "text": "Expect some melting of leaves in the first week or two as the plant adjusts. New runners usually appear within 2 to 3 weeks. Once the carpet fills in, trim it regularly with sharp scissors to keep it low. Thick, untrimmed carpets can lift off the substrate as the lower layers die.\n\nFeed the carpet with a regular liquid fertilizer, and use root tabs if your substrate is plain gravel rather than soil. Pale or yellow new leaves often mean a nutrient shortage. Keep the area clean during water changes by hovering the siphon above the carpet rather than digging into it. As the carpet thickens, trim it like a lawn, cutting off the top layer every couple of weeks, and use the trimmings to start new patches elsewhere."}, {"heading": "Common Mistakes", "text": "- Planting large clumps that rot in the middle\n- Low light, which makes the plant grow upward instead of across\n- Coarse gravel that the fine roots cannot grip\n- Letting the carpet grow too thick so it lifts\n- Digging fish that uproot new clumps\n- Adding fish that pick at plants before the carpet has rooted"}]$g$::jsonb, $g$[{"q": "How do you propagate Monte Carlo plants?", "a": "Split the mat into small clumps and plant them an inch or two apart. The runners spread and fill in the gaps."}, {"q": "Does Monte Carlo need CO2?", "a": "It can grow without CO2, but slowly. CO2 and good light give a dense carpet much faster."}, {"q": "How long does Monte Carlo take to carpet?", "a": "With good conditions, roughly 1 to 3 months depending on spacing, light and CO2."}, {"q": "Why is my Monte Carlo floating up?", "a": "Usually the clumps were too big, the substrate is too coarse, or the carpet has grown so thick that lower layers died. Trim regularly and plant small pieces."}]$g$::jsonb, $g$Take a dated photo of the freshly planted clumps from directly above, then repeat the same shot every couple of weeks so the carpet spreading is easy to see.$g$),
  ($g$corydoras-catfish$g$, $g$e1e6cb4e-b0c8-476c-9fce-092144f95e34$g$::uuid, null, null, $g$How to Breed Corydoras Catfish: T-Position, Eggs and Fry$g$, $g$Most Corydoras spawn after a cool water change, sticking eggs on the glass. Learn conditioning, egg care, fungus prevention and raising the fry.$g$, $g$Corydoras are some of the most rewarding catfish to breed. A well-fed group will often spawn after a cool water change, with the classic T-position and eggs stuck all over the glass. Details vary between species, from easy bronze and peppered cories to fussier ones, but the method is much the same. Protecting the eggs from fungus and feeding the fry well are the keys to success.$g$, $g${"method": "Egg depositor; female carries eggs in her pelvic fins and sticks them on glass or plants", "sexing": "Females are larger and wider when seen from above; males are smaller and slimmer", "group": "About 2 males to each female, in a group of 4 to 8", "breeding_tank": "10 to 20 gallons, bare bottom or thin sand, sponge filter, a few plants", "conditioning": "1 to 2 weeks of bloodworms, blackworms, brine shrimp and sinking pellets", "trigger": "A large water change with water a few degrees cooler, often around stormy weather", "spawn": "Varies by species, from a dozen or so to a few hundred eggs", "eggs": "Commonly about 3 to 5 days to hatch at 72 to 77°F", "fry": "Live on yolk for a day or two, then feed on the bottom", "first_foods": "Microworms, newly hatched baby brine shrimp and finely crushed sinking food", "grow_out": "About 2 to 3 months to a sellable size for most common species", "parents": "No care; adults may eat eggs, so move eggs or adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works for most species. Use a bare bottom or a thin layer of fine sand, a sponge filter and a few plants or a spawning mop. Many cories prefer to place eggs on the glass near the surface or near the filter flow.\n\nTemperatures of about 72 to 77°F suit the most commonly bred species, but check your species. Some, like panda cories, prefer the cooler end, while sterbai cories prefer it warmer."}, {"heading": "Choosing and Conditioning the Group", "text": "Female Corydoras are larger and noticeably wider when you look down on them from above. Males are smaller and slimmer, and in many species have slightly more pointed pelvic fins. A ratio of about 2 males to each female works well.\n\nCondition the group for 1 to 2 weeks with heavy feeding of bloodworms, blackworms, brine shrimp and sinking pellets. Females swell visibly when they are full of eggs."}, {"heading": "Triggering and Spawning", "text": "The classic trigger is a large water change, 30 to 50 percent, using water a few degrees cooler than the tank. This mimics the rainy season. Many breeders see spawning within a day or two, and some say it is more likely when a storm front comes through.\n\nDuring spawning, the male presents his side to the female and she clamps on, forming the T-position. She then carries a few eggs in a basket formed by her pelvic fins and presses them onto the glass, plants or decor. This repeats many times over a few hours. Keep feeding the group lightly during spawning sessions."}, {"heading": "Eggs and Fungus Prevention", "text": "Eggs are sticky and can be rolled off the glass gently with a fingertip. Move them to a hatching container with an airstone, or remove the adults instead.\n\nEggs commonly hatch in about 3 to 5 days at 72 to 77°F. Fungus is the biggest risk. Remove any white, fuzzy eggs right away, keep gentle water movement over the eggs, and consider a little methylene blue or a few alder cones in a separate hatching container."}, {"heading": "Raising the Fry", "text": "Fry live off their yolk for a day or two. After that, feed several small meals a day.\n\n- Week 1: microworms and newly hatched baby brine shrimp\n- Weeks 2 to 4: add finely crushed sinking pellets and wafers\n- Week 4 on: larger frozen foods and regular sinking food\n\nCory fry are sensitive to dirty water. Change 10 to 20 percent of the water every day or two and remove uneaten food. A thin layer of sand helps many breeders by giving fry a natural surface to forage."}, {"heading": "Growing Out", "text": "Most common species reach about half an inch in 4 to 6 weeks and a sellable size in about 2 to 3 months. Move them to a larger tank with sand as they grow, and keep up with weekly water changes of 25 to 30 percent.\n\nFeed growing juveniles several times a day with a mix of sinking pellets, baby brine shrimp and small frozen foods. Cories are social, so keep them in a group rather than as single fish. Many species will spawn again every week or two once conditioned, so plan space for more batches."}, {"heading": "Common Mistakes", "text": "- Leaving eggs in with adults and other fish\n- Not removing fungused eggs\n- Overfeeding the fry tank and fouling the water\n- Sharp gravel that damages barbels\n- Applying one species' temperature to all Corydoras\n- Giving up after one water change; some groups take several tries"}]$g$::jsonb, $g$[{"q": "How do Corydoras breed?", "a": "The male and female form a T-position, and the female carries a few eggs in her pelvic fins before sticking them to glass or plants. This repeats many times in one session."}, {"q": "How long do Corydoras eggs take to hatch?", "a": "Commonly about 3 to 5 days at 72 to 77°F, depending on species and temperature."}, {"q": "How do I get my cories to spawn?", "a": "Condition them with rich foods, then do a large water change with slightly cooler water. This often triggers spawning within a day or two."}, {"q": "Do Corydoras eat their eggs?", "a": "Adults and tankmates may eat eggs. Move the eggs to a hatching container or remove the adults after spawning."}]$g$::jsonb, $g$Name the exact species in your log and photograph your group in the breeding tank with your challenge code card before the water change. Eggs on the glass make an easy, clear stage 2 photo.$g$),
  ($g$panda-cory$g$, $g$cda27ccc-451c-4c2a-a8d8-834f9c867c09$g$::uuid, $g$panda-cory$g$, null, $g$How to Breed Panda Corydoras: Cool Water, Eggs and Fry Care$g$, $g$Panda cories spawn after cool water changes, laying small batches of eggs. Learn how to condition, protect the eggs and raise sensitive fry.$g$, $g$Panda corydoras are a favorite for their bold eye patches, and they breed in much the same way as other cories. They prefer slightly cooler water and tend to lay smaller batches of eggs than bronze or peppered cories. The fry are more delicate, which is why they sit in Society class C. With clean water and plenty of tiny food, raising pandas is a very achievable goal.$g$, $g${"method": "Egg depositor; T-position spawning with eggs stuck to glass, plants or mops", "sexing": "Females are larger and wider from above; males are smaller and slimmer", "group": "About 2 males to each female, in a group of 6 or more", "breeding_tank": "10 to 20 gallons, bare bottom or thin sand, sponge filter, spawning mop or plants", "conditioning": "1 to 2 weeks of bloodworms, blackworms, brine shrimp and sinking pellets", "trigger": "A large water change with water a few degrees cooler", "spawn": "Usually small batches, commonly a few dozen eggs or fewer", "eggs": "Commonly about 3 to 5 days to hatch at 72 to 75°F", "fry": "Live on yolk for a day or two, then forage on the bottom; sensitive to dirty water", "first_foods": "Microworms, baby brine shrimp and finely crushed sinking food", "grow_out": "About 2 to 3 months to around three quarters of an inch", "parents": "No care; move eggs to a hatching container or remove adults"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or a thin layer of fine sand, a sponge filter and a spawning mop or some plants. Pandas like cooler water: keep the tank around 72 to 75°F, within the care range of 68 to 77°F. Soft to moderately hard water with a pH of 6 to 7.4 is ideal."}, {"heading": "Choosing and Conditioning the Group", "text": "Look down on your pandas from above. Females are larger and noticeably wider through the body, while males are smaller and slimmer. A group of at least 6, with about 2 males to each female, gives the best chance of spawning.\n\nCondition the group for 1 to 2 weeks with frequent meals of bloodworms, blackworms, brine shrimp and sinking pellets. Ripe females look rounded and full. Keep the tank clean during conditioning with regular water changes, since heavy feeding builds up waste quickly. Some breeders keep feeding heavily and doing cool water changes every few days until a spawn happens."}, {"heading": "Spawning", "text": "Do a large water change, 30 to 50 percent, with water a few degrees cooler than the tank. Spawning often follows within a day or two.\n\nYou will see males chasing a female, then the T-position, where the female clamps onto the male's side. She carries a small number of eggs between her pelvic fins and sticks them to the glass, plants or a mop. Panda spawns are usually small, commonly a few dozen eggs or fewer per session."}, {"heading": "Eggs and Fungus Prevention", "text": "Gently roll the eggs off the glass with a fingertip and move them to a hatching container with an airstone, or lift out the mop. Eggs commonly hatch in about 3 to 5 days at 72 to 75°F.\n\nFungus is the main risk. Remove any white, fuzzy eggs promptly. Some breeders add a little methylene blue or a few alder cones to the separate hatching container. Keep gentle water movement over the eggs."}, {"heading": "Raising the Fry", "text": "Panda fry live on their yolk sac for a day or two. Then feed small amounts several times a day.\n\n- Week 1: microworms and newly hatched baby brine shrimp\n- Weeks 2 to 4: add finely crushed sinking pellets\n- Week 4 on: small frozen foods and regular sinking food\n\nPanda fry are sensitive to poor water quality. Change 10 to 20 percent of the water every day or two and siphon out leftovers. A thin layer of fine sand in the fry tank often improves survival."}, {"heading": "Growing Out", "text": "Juveniles show the panda pattern early. They reach around three quarters of an inch in about 2 to 3 months. Keep them in a group in a tank with fine sand, keep the temperature on the cool side and continue weekly water changes of 25 to 30 percent.\n\nFeed several small meals a day of sinking pellets, baby brine shrimp and small frozen foods. Growth is steady but not fast, so be patient. Sort out runts and give them their own space if they are falling behind. A conditioned group will often spawn again every week or two, so keep a hatching container ready and plan room for several batches."}, {"heading": "Common Mistakes", "text": "- Keeping the breeding tank too warm for this cooler water species\n- Leaving eggs in with adults\n- Not removing fungused eggs quickly\n- Overfeeding fry and letting the water foul\n- Sharp gravel that damages barbels\n- Moving eggs into water with a different temperature"}]$g$::jsonb, $g$[{"q": "How long do panda cory eggs take to hatch?", "a": "Commonly about 3 to 5 days at 72 to 75°F."}, {"q": "How many eggs do panda corydoras lay?", "a": "Usually small batches, commonly a few dozen eggs or fewer per spawning session."}, {"q": "How do you sex panda corydoras?", "a": "Look from above. Females are larger and wider, while males are smaller and slimmer."}, {"q": "Why are my panda cory fry dying?", "a": "The most common cause is poor water quality from uneaten food. Make small, frequent water changes and remove leftovers."}]$g$::jsonb, $g$Open your log and photograph your panda group in the breeding tank with your challenge code card before the cool water change. A close photo of eggs on the glass or mop gives you a clear stage 2 entry.$g$),
  ($g$pygmy-cory$g$, $g$d4e4e033-7d8b-4051-93e8-07ad5ed20c7a$g$::uuid, $g$pygmy-cory$g$, null, $g$How to Breed Pygmy Corydoras: Tiny Eggs and Tinier Fry$g$, $g$Pygmy corydoras stick small eggs on plants and glass after a cool water change. Learn to find the eggs and raise their very small fry.$g$, $g$Pygmy corydoras are tiny, midwater schooling catfish that spawn much like their larger relatives, with a T-position and sticky eggs. The difference is scale: eggs are laid one or a few at a time around the tank, and the fry are very small. That makes finding eggs and feeding fry the main challenges, and it is why they sit in Society class C. A mossy, well-fed group often surprises its owner with fry.$g$, $g${"method": "Egg depositor; T-position spawning, eggs stuck singly or in small groups on plants and glass", "sexing": "Females are larger and rounder from above; males are smaller and slimmer", "group": "A group of 8 or more, ideally with a few more males than females", "breeding_tank": "5 to 10 gallons, bare bottom or thin sand, fine-leaved plants or moss, sponge filter", "conditioning": "1 to 2 weeks of small live and frozen foods: baby brine shrimp, daphnia, chopped bloodworms", "trigger": "A water change with slightly cooler water after good conditioning", "spawn": "Small; eggs laid one or a few at a time, often a few dozen in total", "eggs": "Commonly about 3 to 4 days to hatch at 72 to 77°F", "fry": "Very small; live on yolk for a day or two, then forage on surfaces and the bottom", "first_foods": "Microworms, vinegar eels and powdered food, then baby brine shrimp", "grow_out": "About 2 to 3 months to near adult size, which is only about an inch", "parents": "No care; adults and tankmates may eat eggs, so move eggs or remove adults"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is plenty for a breeding group of pygmy cories. Use a bare bottom or a thin layer of fine sand, a sponge filter on gentle flow and a good amount of fine-leaved plants or java moss. Pygmies often stick eggs on plant leaves and the glass rather than one spot.\n\nKeep the temperature at 72 to 77°F, within the care range of 72 to 79°F, with soft to moderately hard water around pH 6 to 7.5. A tight lid and a calm, species-only setup give the best results."}, {"heading": "Sexing and Conditioning the Group", "text": "Pygmy corydoras are about an inch long at most, so sexing takes a close look. Females are larger and rounder, especially from above, while males are smaller and slimmer. A group of 8 or more gives you a good mix and helps these social fish feel secure.\n\nCondition the group for 1 to 2 weeks with small, frequent meals of baby brine shrimp, daphnia, chopped bloodworms and fine sinking food. Females that fill out noticeably are ready."}, {"heading": "Spawning", "text": "Do a water change of about 30 percent with water a few degrees cooler than the tank. Spawning often follows within a day or two, though some groups need several tries.\n\nYou will see males chasing a female, then the classic T-position. The female carries one or a few eggs in her pelvic fins and sticks them on a leaf, moss or the glass. Eggs are spread around the tank rather than in one cluster. A session often adds up to a few dozen eggs, but small spawns are normal for this species."}, {"heading": "Eggs and Hatching", "text": "The eggs are small and clear and easy to miss. Check the glass, plant leaves and moss carefully with a flashlight. Roll eggs off the glass gently with a fingertip, or move the plants and moss with eggs into a hatching container with an airstone. You can also remove the adults instead.\n\nEggs commonly hatch in about 3 to 4 days at 72 to 77°F. Remove any eggs that turn white and fuzzy quickly so fungus does not spread. A few alder cones in a hatching container can help."}, {"heading": "Raising the Fry", "text": "Pygmy cory fry are very small and need fine foods. They live off their yolk for a day or two.\n\n- Week 1: microworms, vinegar eels and fine powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp\n- Week 4 on: crushed sinking food and small frozen foods\n\nFeed small amounts several times a day and siphon out leftovers. Change 10 to 20 percent of the water every day or two with water of the same temperature. A little moss and a thin layer of sand give the fry places to forage and help survival."}, {"heading": "Growing Out", "text": "Pygmies grow to near adult size, about an inch, in roughly 2 to 3 months. Keep the young in a group, since they are social from the start. Move them to a larger planted tank once they are eating baby brine shrimp well and continue weekly water changes of 20 to 30 percent. They will often begin swimming midwater in small schools like the adults."}, {"heading": "Common Mistakes", "text": "- Missing the eggs because they are scattered and small\n- Leaving eggs in a tank with other fish\n- Feeding food that is too large for the fry\n- Big swings in temperature during water changes\n- Keeping too few adults, which makes them shy and less likely to spawn"}]$g$::jsonb, $g$[{"q": "How do pygmy corydoras breed?", "a": "They spawn in the T-position like other cories. The female carries one or a few eggs at a time and sticks them on plants or the glass."}, {"q": "How long do pygmy cory eggs take to hatch?", "a": "Commonly about 3 to 4 days at 72 to 77°F."}, {"q": "How do you tell male and female pygmy corydoras apart?", "a": "Females are larger and rounder, especially from above. Males are smaller and slimmer."}, {"q": "What do pygmy cory fry eat?", "a": "Very fine foods such as microworms, vinegar eels and powdered fry food at first. Add baby brine shrimp after about a week."}]$g$::jsonb, $g$Photograph your pygmy group in the breeding tank with your challenge code card when you open the log. Eggs are tiny, so take your stage 2 photo close up on the glass or a leaf with good lighting.$g$),
  ($g$salt-and-pepper-cory$g$, $g$77d8d639-a4f3-4d5b-809a-7a4df70970af$g$::uuid, $g$salt-and-pepper-cory$g$, null, $g$How to Breed Salt and Pepper Corydoras (Corydoras Habrosus)$g$, $g$Salt and pepper cories lay small batches of eggs on plants and glass. Learn how to trigger spawning, find the eggs and raise their tiny fry.$g$, $g$Salt and pepper corydoras (Corydoras habrosus) are tiny, bottom-dwelling cories that breed in the same T-position style as larger species, but on a smaller scale. Eggs are laid a few at a time around the tank and the fry are small. With a calm, planted tank, good conditioning and fine foods ready, this is a satisfying Society class C species for anyone who enjoys nano fish.$g$, $g${"method": "Egg depositor; T-position spawning, eggs placed singly or in small groups on plants and glass", "sexing": "Females are larger and rounder from above; males are smaller and slimmer", "group": "A group of 6 to 10, with a few more males than females", "breeding_tank": "5 to 10 gallons, fine sand or bare bottom, fine-leaved plants or moss, sponge filter", "conditioning": "1 to 2 weeks of small live and frozen foods: baby brine shrimp, daphnia, chopped bloodworms", "trigger": "A water change with slightly cooler water after good conditioning", "spawn": "Small batches, commonly a few dozen eggs or fewer", "eggs": "Commonly about 3 to 4 days to hatch at 72 to 77°F", "fry": "Very small; live on yolk briefly, then forage on the bottom", "first_foods": "Microworms, vinegar eels and fine powdered food, then baby brine shrimp", "grow_out": "About 2 to 3 months to near adult size, which is about an inch", "parents": "No care; move eggs to a hatching container or remove the adults"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is ideal. Use fine sand or a bare bottom, a gentle sponge filter, and fine-leaved plants or moss for the female to stick eggs on. Unlike pygmy corydoras, Corydoras habrosus stays near the bottom most of the time.\n\nKeep the water at 72 to 77°F, within the care range of 72 to 79°F, with a pH of 6 to 7.5 and soft to moderately hard water. A calm, species-only tank works best. Larger or boisterous tankmates will eat eggs and stress these small catfish, and a peaceful tank also makes it easier to spot spawning when it happens."}, {"heading": "Sexing and Conditioning the Group", "text": "Sexing these tiny fish takes a close look from above. Females are larger and rounder through the body, and males are smaller and slimmer. In a group of 6 to 10 you will almost always have both.\n\nCondition with small, frequent meals for 1 to 2 weeks: baby brine shrimp, daphnia, chopped bloodworms and quality sinking food. Females should look noticeably full before you try to trigger a spawn."}, {"heading": "Spawning", "text": "A water change of about 30 percent with slightly cooler water is the usual trigger. Spawning often follows within a day or two, but some groups need a few rounds.\n\nYou will see males chasing a female and the T-position, after which she places one or a few eggs on a plant leaf, moss or the glass. Spawns are small, commonly a few dozen eggs or fewer, and eggs are spread around the tank."}, {"heading": "Eggs and Hatching", "text": "Search carefully, since the eggs are small and scattered. Roll eggs off the glass with a fingertip or move plants and moss into a hatching container with an airstone. Removing the adults is another option.\n\nEggs commonly hatch in about 3 to 4 days at 72 to 77°F. Remove any eggs that turn white and fuzzy. A few alder cones in a separate hatching container can help prevent fungus."}, {"heading": "Raising the Fry", "text": "The fry live on their yolk for a day or two, then begin foraging on the bottom.\n\n- Week 1: microworms, vinegar eels and fine powdered fry food\n- Weeks 2 to 3: add newly hatched baby brine shrimp\n- Week 4 on: crushed sinking pellets and small frozen foods\n\nFeed small amounts several times a day and remove leftovers with a pipette or siphon. Change 10 to 20 percent of the water every day or two with temperature matched water. A thin layer of sand helps the fry forage naturally."}, {"heading": "Growing Out", "text": "Salt and pepper cories reach near adult size, about an inch, in roughly 2 to 3 months. Keep the young together in a group and move them to a larger tank with fine sand as they grow. Keep up weekly water changes of 20 to 30 percent and feed a mix of sinking pellets and live or frozen foods. The speckled pattern shows early, which makes them easy to tell from other small cories.\n\nA conditioned group will often spawn again every week or two, so keep a hatching container ready and plan space for several small batches. Because each spawn is small, many breeders collect eggs from a few sessions and raise them together. Keep the best grown fish to start your next breeding group."}, {"heading": "Common Mistakes", "text": "- Missing the scattered eggs\n- Leaving eggs with adults or tankmates\n- Feeding food too large for the fry\n- Coarse gravel that damages barbels\n- Confusing this species with pygmy cories, which swim midwater"}]$g$::jsonb, $g$[{"q": "How do salt and pepper corydoras breed?", "a": "They spawn in the T-position. The female places one or a few eggs at a time on plants or glass, so spawns are spread around the tank."}, {"q": "How long do Corydoras habrosus eggs take to hatch?", "a": "Commonly about 3 to 4 days at 72 to 77°F."}, {"q": "How big do salt and pepper cories get?", "a": "About an inch as adults. Fry reach near adult size in roughly 2 to 3 months."}, {"q": "What is the difference between habrosus and pygmy corydoras?", "a": "Habrosus has a speckled salt and pepper pattern and stays near the bottom. Pygmies have a dark side stripe and often swim midwater."}]$g$::jsonb, $g$Name the species as Corydoras habrosus in your log and photograph the group with your challenge code card in stage 1. A clear close up of eggs on a leaf or the glass works well for stage 2.$g$),
  ($g$hoplo-catfish$g$, $g$e3f214af-a456-44a2-b6ea-a67e0f74b5c9$g$::uuid, $g$hoplo-catfish$g$, null, $g$How to Breed Spotted Hoplo Catfish: Bubble Nests and Fry$g$, $g$Spotted hoplos are catfish that build bubble nests, guarded by the male. Learn sexing, triggering a spawn and raising the fast-growing fry.$g$, $g$The spotted hoplo is a surprise for many keepers: a catfish that builds a bubble nest. The male blows a large nest under a floating object and guards the eggs fiercely. Spawns are big and the fry grow fast once they start eating. The main challenges are space for a fish that reaches about 6 inches and managing the protective male, which is why it sits in Society class C.$g$, $g${"method": "Bubble nester; male builds a nest under a floating object and guards the eggs", "sexing": "Mature males have a thick first pectoral spine that turns orange to reddish when breeding", "group": "One male with one or two females", "breeding_tank": "40 gallons or more, floating object such as a plate or leaf, sponge filter, lid", "conditioning": "1 to 2 weeks of bloodworms, earthworms, sinking pellets and shrimp", "trigger": "A large water change with cooler water, often with lowered water level and rainy weather", "spawn": "Commonly several hundred eggs", "eggs": "Commonly about 3 to 5 days to hatch at 77 to 80°F", "fry": "Drop from the nest after hatching, absorb yolk in a day or two, then eat eagerly", "first_foods": "Baby brine shrimp, microworms and finely crushed sinking food", "grow_out": "Fast; about 2 months to around an inch for well-fed fry", "parents": "Male guards nest; remove the female after spawning, and move fry before the male turns on them"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Spotted hoplos reach about 6 inches, so a 40 gallon tank or larger is the minimum, in line with the care data. Keep the water at 77 to 80°F within the care range of 72 to 82°F. They tolerate a wide pH range of 6 to 8.\n\nFloat something for the male to build under. Breeders commonly use a plastic plate, a piece of foam, a lid or a large floating leaf. Use a sponge filter with gentle flow and keep a tight lid, as hoplos can jump. Some breeders lower the water level a few inches."}, {"heading": "Sexing and Conditioning", "text": "Hoplos are easiest to sex when mature. The male's first pectoral fin ray is a thick spine, longer and heavier than the female's, and in breeding condition it turns orange to reddish. Females have thinner spines and are often plumper.\n\nCondition the group for 1 to 2 weeks with plenty of bloodworms, earthworms, shrimp and sinking pellets. Keep up water changes while you feed heavily, as hoplos produce a lot of waste."}, {"heading": "Spawning", "text": "A large water change with cooler water is the usual trigger, and many breeders report better results during rainy or stormy weather. The male builds a large, foamy bubble nest under the floating object, often several inches across.\n\nThe pair spawn under the nest in a T-position similar to Corydoras. The female collects eggs in her pelvic fins and places them in the nest. Spawns commonly run to several hundred eggs. Once spawning ends, remove the female, as the male defends the nest aggressively."}, {"heading": "Eggs and the Male's Care", "text": "The male guards the nest and adds bubbles to keep the eggs covered. Do not put your hand near the nest; he may bite. Eggs commonly hatch in about 3 to 5 days at 77 to 80°F.\n\nMany breeders move the nest before hatching by sliding the plate or foam out with the eggs attached and placing it in a separate hatching tank with an airstone. Others leave the male in charge until hatching, then move the fry, as males may eat fry once they leave the nest."}, {"heading": "Raising the Fry", "text": "After hatching, fry drop to the bottom and live on their yolk for a day or two. Then they eat eagerly.\n\n- Week 1: newly hatched baby brine shrimp and microworms\n- Weeks 2 to 3: add finely crushed sinking pellets and wafers\n- Week 4 on: chopped frozen foods and small pellets\n\nFeed several times a day. Hoplo fry eat a lot and make a lot of waste, so change 20 to 30 percent of the water every day or two. Large spawns need room; split fry between tanks if they are crowded."}, {"heading": "Growing Out", "text": "Hoplo fry grow fast when fed well, reaching around an inch in about 2 months. Move them to larger tanks as they grow and keep up frequent water changes. Plan ahead for a large spawn: a few hundred juveniles take a lot of space and food, and adults need big tanks.\n\nSort the fry by size every couple of weeks, since faster growers can outcompete smaller siblings. Feed a mix of sinking pellets, chopped frozen foods and live foods several times a day. Juveniles are hardy and peaceful, and they do well in groups. Keep a few of your best grown fish if you want to start a second generation, choosing males that develop strong pectoral spines."}, {"heading": "Common Mistakes", "text": "- A tank too small for a 6 inch fish\n- No floating object for the nest\n- Leaving the female in with a guarding male\n- Reaching near the nest and getting bitten\n- Underestimating how much space a big spawn needs"}]$g$::jsonb, $g$[{"q": "Do hoplo catfish build bubble nests?", "a": "Yes. The male builds a large bubble nest under a floating object and guards the eggs."}, {"q": "How do you sex spotted hoplos?", "a": "Mature males have a thick, heavy first pectoral spine that turns orange to reddish in breeding condition. Females have thinner spines."}, {"q": "How long do hoplo eggs take to hatch?", "a": "Commonly about 3 to 5 days at 77 to 80°F."}, {"q": "Will a male hoplo eat his fry?", "a": "He guards the eggs, but may eat fry once they leave the nest. Move the nest or the fry to a separate tank."}]$g$::jsonb, $g$Open your log with a photo of the male and female in the tank with your floating plate in place and your challenge code card. A clear shot of eggs in the bubble nest under the plate makes a good stage 2 photo.$g$),
  ($g$sterbai-cory$g$, $g$b0860b68-3522-4604-861f-5b656b8ac1f2$g$::uuid, $g$sterbai-cory$g$, null, $g$How to Breed Sterbai Corydoras: Warm Water, Eggs and Fry$g$, $g$Sterbai cories spawn after a cool water change in warm, soft water. Learn conditioning, egg care, fungus prevention and raising the fry.$g$, $g$Sterbai corydoras, with their orange pectoral fins and spotted pattern, are one of the most popular cories to breed. They prefer warmer water than many cories but spawn in the same classic T-position style. Spawns can be generous, and the fry grow steadily on simple foods. Egg fungus and clean water for the fry are the main things to manage, which puts them in Society class C.$g$, $g${"method": "Egg depositor; T-position spawning, eggs stuck on glass, plants or mops", "sexing": "Females are larger and wider from above; males are smaller and slimmer", "group": "About 2 males to each female, in a group of 6 or more", "breeding_tank": "15 to 20 gallons, bare bottom or fine sand, spawning mop or plants, sponge filter", "conditioning": "1 to 2 weeks of bloodworms, blackworms, brine shrimp and sinking pellets", "trigger": "A large water change with water a few degrees cooler than the tank", "spawn": "Commonly a few dozen eggs, sometimes more than 100", "eggs": "Commonly about 3 to 5 days to hatch at 77 to 80°F", "fry": "Live on yolk for a day or two, then forage on the bottom", "first_foods": "Microworms, baby brine shrimp and finely crushed sinking food", "grow_out": "About 2 to 3 months to around an inch", "parents": "No care; adults may eat eggs, so move eggs or remove adults"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 15 to 20 gallon tank works well for a breeding group. Use a bare bottom or a thin layer of fine sand, a sponge filter and a spawning mop or a few plants. Sterbai cories like it warmer than many cories: keep the tank at about 77 to 80°F, inside the care range of 73 to 82°F. Soft to moderately hard water with a pH of 6 to 7.5 suits them."}, {"heading": "Sexing and Conditioning the Group", "text": "Look down on the fish from above. Females are larger and noticeably wider, while males are smaller and slimmer. Both sexes have the bright orange pectoral fin spines, so these do not help with sexing. A group of 6 or more with about 2 males per female works well.\n\nCondition for 1 to 2 weeks with frequent meals of bloodworms, blackworms, brine shrimp and quality sinking pellets. Ripe females look rounded through the belly. Keep up water changes during heavy feeding so waste does not build up in the tank."}, {"heading": "Spawning", "text": "The usual trigger is a large water change, 30 to 50 percent, with water a few degrees cooler than the tank. Spawning often follows within a day or two, and repeating the change every few days helps a reluctant group.\n\nDuring spawning, males chase the female until one forms a T-position with her. She carries a few eggs in her pelvic fins and sticks them on the glass, plants or a mop. Spawns are commonly a few dozen eggs, and sometimes more than 100 over a session."}, {"heading": "Eggs and Fungus Prevention", "text": "Roll the eggs gently off the glass with a fingertip and move them to a hatching container with an airstone, or lift out the mop. Eggs commonly hatch in about 3 to 5 days at 77 to 80°F.\n\nFungus is the main risk. Remove any white, fuzzy eggs right away. Many breeders add a little methylene blue or a few alder cones to the separate hatching container and keep a gentle flow of water over the eggs."}, {"heading": "Raising the Fry", "text": "Fry live on their yolk for a day or two, then begin feeding on the bottom.\n\n- Week 1: microworms and newly hatched baby brine shrimp\n- Weeks 2 to 4: add finely crushed sinking pellets and wafers\n- Week 4 on: small frozen foods and regular sinking food\n\nFeed small amounts several times a day and remove leftovers. Change 10 to 20 percent of the water every day or two with water at the same temperature. A thin layer of fine sand helps the fry forage and many breeders find it improves survival."}, {"heading": "Growing Out", "text": "Young sterbai show their spots early and their orange fins as they grow. They reach around an inch in about 2 to 3 months. Move them to a larger tank with fine sand as they grow, keep them in a group and continue weekly water changes of 25 to 30 percent. Conditioned adults often spawn again every week or two.\n\nFeed growing juveniles several small meals a day of sinking pellets, baby brine shrimp and small frozen foods. Sort out slower growers if they fall behind. Because spawns can repeat often, plan your tank space before you start, and keep a hatching container ready for the next batch. Keep the young fish warm, as they share the adults' preference for the warmer end of the range."}, {"heading": "Common Mistakes", "text": "- Keeping the breeding tank too cool for this warmer water species\n- Leaving eggs in with adults\n- Not removing fungused eggs quickly\n- Overfeeding fry and fouling the water\n- Sharp gravel that damages barbels"}]$g$::jsonb, $g$[{"q": "How long do sterbai cory eggs take to hatch?", "a": "Commonly about 3 to 5 days at 77 to 80°F."}, {"q": "How do you sex sterbai corydoras?", "a": "Look from above. Females are larger and wider, and males are smaller and slimmer. Both sexes have orange pectoral fins."}, {"q": "What temperature do sterbai cories breed at?", "a": "They prefer warmer water than many cories, around 77 to 80°F. A cooler water change is still the usual spawning trigger."}, {"q": "Do sterbai corydoras eat their eggs?", "a": "Adults may eat eggs, so move the eggs to a hatching container or remove the adults after spawning."}]$g$::jsonb, $g$Photograph your sterbai group in the breeding tank with your challenge code card before the trigger water change. A close photo of eggs on the glass or mop makes a clear stage 2 entry.$g$),
  ($g$false-julii-cory$g$, $g$41a4fdb7-43f9-4b84-96ad-e302628dc40b$g$::uuid, $g$false-julii-cory$g$, null, $g$How to Breed Three-stripe Corydoras: T-Position to Fry$g$, $g$Breed three-stripe corydoras with a cool water change trigger, then pull the sticky eggs and raise tiny fry on microworms. A moderate catfish project.$g$, $g$Three-stripe corydoras, often sold as false julii, are one of the more cooperative corys to breed once they are well fed and kept in a group. The classic cool water change trigger works well, and watching a T-position spawn is a highlight for any catfish keeper. The real work is protecting the eggs from fungus and keeping the tiny fry clean and fed for the first few weeks.$g$, $g${"method": "Egg depositor (T-position spawner, sticks eggs to glass and plants)", "sexing": "Females larger and noticeably broader seen from above; males slimmer with taller dorsal fin", "group": "2 to 3 males per female, or a group of 6 or more", "breeding_tank": "15 to 20 gallon, sponge filter, bare or sand bottom, a few plants", "conditioning": "1 to 2 weeks of bloodworms, blackworms, brine shrimp and sinking pellets", "trigger": "Large 30 to 50% water change with water 3 to 5°F cooler, ideally before a rainy day", "spawn": "Commonly 50 to 150 eggs over a spawning session, a few at a time", "eggs": "Hatch in about 3 to 5 days at 74 to 77°F", "fry": "Absorb yolk in 2 to 3 days, then forage on the bottom; tiny and delicate", "first_foods": "Microworms, newly hatched brine shrimp, crushed sinking wafers", "grow_out": "About 2 to 3 months to roughly 1 inch", "parents": "No care; adults eat eggs, so move eggs or adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank is plenty for a breeding group. Use an air driven sponge filter so eggs and fry are never sucked into an intake, and keep the bottom bare or covered with a thin layer of fine sand so you can see the eggs and keep things clean.\n\nAdd a few broad leaved plants or a clump of moss, because females often stick eggs on leaves as well as the glass. Keep the water in the site's range of 72 to 79°F, pH 6 to 7.5 and GH 2 to 12. Many breeders keep the tank around 75°F and let the trigger water change drop it a few degrees."}, {"heading": "Conditioning your group", "text": "Corys spawn best in a group with more males than females. Two or three males per female is the usual advice, or simply keep six or more adults and let them sort it out.\n\nFeed heavily for one to two weeks with live or frozen bloodworms, blackworms, brine shrimp and quality sinking pellets two or three times a day. You want the females to look visibly round when viewed from above. Keep up regular water changes during conditioning, because full feeding fouls the water quickly."}, {"heading": "Triggering the spawn and what you'll see", "text": "Once females are plump, do a 30 to 50% water change with water 3 to 5°F cooler than the tank. This mimics the start of the rainy season. Spawning often follows within a day or two, and many breeders notice it happens before a storm, when the air pressure drops.\n\nYou will see males chasing a female and shaking against her. A male positions himself across her head in a T shape and she cups a few eggs in her pelvic fins. She then swims off to find a clean spot and sticks the eggs on the glass, a plant leaf or decor. This repeats over a few hours until she has laid commonly 50 to 150 eggs."}, {"heading": "Caring for the eggs", "text": "Adult corys will eat their own eggs, so either move the adults back to their main tank or remove the eggs. Eggs on glass can be rolled off gently with a fingertip or a credit card edge. Place them in a small hatching container in the same water with gentle aeration.\n\nThe eggs hatch in about 3 to 5 days at 74 to 77°F. Infertile eggs turn white and fuzzy within a day or two. Remove them with a pipette straight away so the fungus does not spread. A few dried oak or Indian almond leaves in the hatching container or a small amount of methylene blue are common ways to reduce fungus."}, {"heading": "Raising the fry", "text": "Newly hatched fry live off their yolk sac for 2 to 3 days. Once they are moving around on the bottom, start feeding.\n\n- Week 1: microworms and newly hatched brine shrimp two or three times a day\n- Weeks 2 to 3: brine shrimp plus finely crushed sinking wafers and pellets\n- Week 4 on: chopped frozen foods and small sinking pellets\n\nCory fry are very sensitive to dirty water. Siphon uneaten food daily and change 10 to 20% of the water every day or two using water matched closely for temperature. A thin layer of sand helps, as many breeders find fry do better foraging in it than on bare glass once they are past the first week. Keep the temperature steady around 75 to 77°F."}, {"heading": "Growing out", "text": "Fry show their stripes after a few weeks and reach roughly half an inch in about a month. Expect around 2 to 3 months to reach about 1 inch, which is a good size for passing them on. Move them into a larger grow out tank as they grow, keep feeding several times a day and keep up frequent water changes. Spreading out the numbers is the easiest way to speed growth."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults, who eat them within hours\n- Letting fungus spread from dead eggs to healthy ones\n- Overfeeding fry and skipping water changes, which is the top cause of sudden fry losses\n- Using a filter intake the fry can be pulled into\n- Expecting a spawn from thin, underfed females"}]$g$::jsonb, $g$[{"q": "How do I tell male and female three-stripe corydoras apart?", "a": "Look from above. Females are larger and much broader through the body, while males are slimmer and often have a slightly taller dorsal fin."}, {"q": "How long do corydoras eggs take to hatch?", "a": "Three-stripe cory eggs usually hatch in about 3 to 5 days at 74 to 77°F. Cooler water slows hatching."}, {"q": "Do corydoras eat their eggs?", "a": "Yes. Adults and tank mates will eat eggs and fry, so move the eggs to a hatching container or move the adults out after spawning."}, {"q": "Why do my cory eggs turn white?", "a": "White, fuzzy eggs are usually infertile or have fungus. Remove them quickly so the fungus does not spread to healthy eggs."}]$g$::jsonb, $g$Open your log while the group is conditioning so your stage 1 photo shows the males and plump females together with the challenge code card. For stage 2, a clear photo of eggs on the glass is ideal, since they are easy to spot before you move them.$g$),
  ($g$whiptail-catfish$g$, $g$ad0b8a5b-d21b-4b05-93dc-300a5b6b0ab4$g$::uuid, $g$whiptail-catfish$g$, null, $g$How to Breed Whiptail Catfish: Tubes, Eggs and Tiny Fry$g$, $g$Whiptail catfish breed in tubes or caves with the male guarding eggs. Spawning is easy for a healthy pair; raising the fry well takes care.$g$, $g$Whiptail catfish (Rineloricaria) are quiet, peaceful catfish that will often spawn in a simple tube once a mature pair is settled. The male guards the eggs inside the tube, which is fascinating to watch. Getting eggs is the easier half; the fry are delicate grazers that need clean water and plenty of soft food, which is why this is a Society class C fish.$g$, $g${"method": "Cave spawner (eggs laid in a tube or cave, guarded by the male)", "sexing": "Mature males grow bristles on the sides of the head and thick pectoral spines; females lack them", "group": "One pair, or 1 male to 2 females", "breeding_tank": "20 gallon with sponge filter and 1 inch wide tubes or narrow caves", "conditioning": "2 to 3 weeks of sinking wafers, blanched vegetables, bloodworms and brine shrimp", "trigger": "Settled mature pair; a cooler water change can help start things", "spawn": "Commonly about 50 to 150 eggs in a sticky cluster", "eggs": "Hatch in roughly 7 to 12 days at 75 to 78°F, depending on temperature", "fry": "Leave the tube after the yolk sac is used up; tiny thin grazers", "first_foods": "Biofilm, crushed algae and vegetable wafers, blanched vegetables, baby brine shrimp", "grow_out": "Around 3 to 4 months to about 1.5 to 2 inches", "parents": "Male guards eggs; adults usually ignore fry but egg eating happens if disturbed"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank suits a pair or a male with two females. Use a sponge filter or a well covered intake, a sand bottom, and a few PVC tubes or clay caves about 1 inch wide and 6 to 8 inches long. Whiptails like a snug fit, so a tube only a little wider than the male's body works better than a big cave.\n\nKeep water within the site's range of 72 to 79°F, pH 6 to 7.5 and GH 2 to 15. Many breeders run the tank around 75 to 77°F with good oxygen and moderate flow across the tubes."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing is easy in mature fish. Males develop a fringe of short bristles (odontodes) along the sides of the head and thicker, bristly pectoral fin spines. Females have smooth heads and a rounder belly when full of eggs. Young fish can be hard to sex, so a group of four to six juveniles gives you the best odds of a pair.\n\nCondition for two to three weeks with sinking algae and vegetable wafers, blanched zucchini or spinach, plus bloodworms and brine shrimp. Feed in the evening, as whiptails are most active after dark."}, {"heading": "Spawning: what you'll see", "text": "The male picks a tube and spends a lot of time inside it. When a ripe female joins him, she lays a sticky clump of eggs on the inside wall and he fertilizes them. The usual clutch is commonly reported at about 50 to 150 eggs.\n\nThe first sign is often the male refusing to leave the tube and fanning steadily with his fins. If you shine a light into the tube carefully you may see a cluster of pale eggs behind him. Water changes with slightly cooler water can encourage spawning, but a settled, well fed pair often spawns without any special trigger."}, {"heading": "Eggs and the guarding male", "text": "The male fans and guards the eggs until they hatch, usually in roughly 7 to 12 days at 75 to 78°F. Most breeders leave him to it, as he does a better job than an air stone. Avoid moving or tipping the tube during this time, as a stressed male may abandon or eat the eggs.\n\nIf a male repeatedly eats clutches, you can move the whole tube into a hatching container with an air stone close to the eggs. Remove any eggs that turn white or fuzzy."}, {"heading": "Raising the fry", "text": "Fry hang on to their yolk sacs for a few days and then leave the tube. They are thin, slow and easy to lose track of, so keep them in the breeding tank or a small bare grow out tank with established biofilm.\n\n- Week 1: biofilm, finely crushed algae wafers, and newly hatched brine shrimp\n- Weeks 2 to 4: add blanched vegetables and crushed sinking pellets\n- Month 2 on: a varied diet of wafers, vegetables and frozen foods\n\nFeed little and often, and do 10 to 20% water changes every two or three days. Fry are sensitive to ammonia, so remove uneaten food daily."}, {"heading": "Growing out", "text": "Growth is steady but not fast. Expect around 3 to 4 months for fry to reach 1.5 to 2 inches. Give them plenty of bottom area rather than tall tanks, and keep feeding vegetable matter alongside protein foods."}, {"heading": "Common mistakes", "text": "- Using caves that are too wide; whiptails prefer snug tubes\n- Disturbing the tube while the male guards eggs\n- Starving fry in a new, clean tank with no biofilm\n- Letting uneaten food rot around tiny fry\n- Assuming young fish are all one sex before bristles develop"}]$g$::jsonb, $g$[{"q": "How do you sex whiptail catfish?", "a": "Mature males grow small bristles along the sides of the head and on the pectoral fin spines. Females have smooth heads and look rounder when carrying eggs."}, {"q": "How long do whiptail catfish eggs take to hatch?", "a": "Breeders commonly report about 7 to 12 days, with warmer water at the faster end. The male guards them the whole time."}, {"q": "Do whiptail catfish eat their babies?", "a": "Adults usually leave fry alone, but a stressed male may eat eggs. Avoid disturbing the tube while he is guarding."}, {"q": "What do baby whiptail catfish eat?", "a": "Biofilm, crushed algae and vegetable wafers, blanched vegetables, and newly hatched brine shrimp. Feed small amounts several times a day."}]$g$::jsonb, $g$Whiptails often spawn out of sight, so for stage 2 a photo of the eggs taken with a flashlight into the tube, or of the tube lifted briefly in a container, works well. Rineloricaria can be hard to identify to species, so note the exact fish you are logging and keep photos of the adults.$g$),
  ($g$black-neon-tetra$g$, $g$3bbc3c9d-05b1-4849-9793-532a093e6efe$g$::uuid, $g$black-neon-tetra$g$, null, $g$How to Breed Black Neon Tetras: Soft Water and Tiny Fry$g$, $g$Black neon tetras scatter eggs in soft, slightly acidic water. Remove the adults, keep the eggs dim, and feed infusoria first. A moderate tetra project.$g$, $g$Black neon tetras are a good first step into breeding egg scattering tetras. A well conditioned pair will spawn readily in a dim, soft water tank, often producing a large batch of eggs. The challenge is that adults eat the eggs, the eggs dislike bright light, and the fry are tiny for the first week, so a little preparation makes the difference.$g$, $g${"method": "Egg scatterer (eggs fall among fine plants or mesh)", "sexing": "Females deeper and rounder in the belly; males slimmer", "group": "One pair, or 2 males to 1 female; group spawning also works", "breeding_tank": "5 to 10 gallon, bare bottom with mesh or marbles, java moss, sponge filter", "conditioning": "1 to 2 weeks apart on brine shrimp, bloodworms, daphnia and quality flakes", "trigger": "Soft, slightly acidic water, dim light, and fresh morning light after an evening move", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 24 to 36 hours at 77 to 80°F", "fry": "Free swimming 3 to 5 days after hatching; very small", "first_foods": "Infusoria or paramecium, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 8 to 10 weeks to show color and reach about 0.75 inch", "parents": "No care; adults eat eggs, so remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is ideal. Cover the bottom with plastic mesh, marbles or a thick mat of java moss so eggs fall out of reach of the parents. Use a small sponge filter and keep the light low, or cover the sides with paper.\n\nThe site lists a range of pH 5.5 to 7.5 and GH 3 to 15 for keeping. For spawning, aim for the soft, acidic end: pH 6 to 6.5 and GH under 6, at 77 to 80°F. Rain water or RO water mixed with tap water and filtered over peat or leaves are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Females are rounder and deeper bodied, especially when full of eggs, while males are slimmer. Separate the sexes for one to two weeks if you can and feed generously with live or frozen brine shrimp, bloodworms and daphnia, plus a good flake.\n\nPick the roundest female and the most active, best colored male. Some breeders use two males with one female, which can improve fertility. Group spawning a few males and females together in a larger tank also works and needs less fuss over picking pairs, though egg eating is higher.\n\nStart preparing fry food now. Set up an infusoria culture and a vinegar eel or microworm culture a week or two ahead, because the fry will need them within days of hatching."}, {"heading": "Spawning: what you'll see", "text": "Move the pair into the breeding tank in the evening. Spawning commonly happens the next morning as light reaches the tank. The male chases the female through the moss, they quiver side by side, and a few eggs are released and fertilized each time. A full spawn is commonly 100 to 300 eggs over a couple of hours.\n\nIf nothing happens after two or three days, return the fish to conditioning and try again. A small, cooler water change of soft water can help start things."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning ends, as they will eat the eggs. Keep the tank dim, since the eggs and newly hatched fry are light sensitive. Eggs hatch in about 24 to 36 hours at 77 to 80°F.\n\nSome eggs will go white and fuzzy; these are infertile. Remove what you can with a pipette. A little methylene blue or a few dried leaves can help keep fungus down in soft water."}, {"heading": "Raising the fry", "text": "The fry hang on the glass and plants after hatching and become free swimming about 3 to 5 days later. At that point they need very small food.\n\n- Days 1 to 7 of free swimming: infusoria or paramecium, several times a day\n- Week 2: vinegar eels or microworms, adding newly hatched brine shrimp once they can take it\n- Weeks 3 to 6: brine shrimp and finely crushed flakes\n\nStart small water changes of about 10% every couple of days in the second week, using matched soft water. Keep the temperature steady around 77 to 79°F and gradually raise the light."}, {"heading": "Growing out", "text": "Black neons show their black and white stripes at a few weeks old and reach about three quarters of an inch in about 8 to 10 weeks. Move them into a larger tank with more frequent water changes as they grow, and keep feeding several small meals a day."}, {"heading": "Common mistakes", "text": "- Leaving adults in with the eggs\n- Bright light on the eggs and young fry\n- Hard, alkaline water, which lowers fertility\n- Offering baby brine shrimp before the fry can eat it\n- Big water changes that swing temperature or hardness"}]$g$::jsonb, $g$[{"q": "How do you tell a male black neon tetra from a female?", "a": "Females are noticeably rounder and deeper in the body, especially when full of eggs. Males are slimmer."}, {"q": "How long do black neon tetra eggs take to hatch?", "a": "About 24 to 36 hours at 77 to 80°F. The fry become free swimming roughly 3 to 5 days after that."}, {"q": "Will black neon tetras breed in a community tank?", "a": "They may spawn, but the eggs and fry are almost always eaten. A separate breeding tank is the reliable way."}, {"q": "What do black neon tetra fry eat?", "a": "Start with infusoria or paramecium, then move to vinegar eels or microworms and newly hatched brine shrimp as they grow."}]$g$::jsonb, $g$Photograph your chosen pair in the breeding tank with the challenge code card before spawning, as stage 1 must be logged first. Eggs are small, so a close photo of eggs on the mesh or moss with a flashlight makes the stage 2 evidence clear.$g$),
  ($g$black-phantom-tetra$g$, $g$216e0cad-082f-4767-a1c3-235ae90679b5$g$::uuid, $g$black-phantom-tetra$g$, null, $g$How to Breed Black Phantom Tetras: Pairs, Eggs and Fry$g$, $g$Black phantom tetras spawn in soft, acidic water and scatter eggs over plants. Separate the eggs from adults and start fry on infusoria. Moderate.$g$, $g$Black phantom tetras are peaceful and easy to keep, and a well conditioned pair will spawn in a quiet, soft water tank. The males' displays are a big part of the fun. Like most tetras, the parents eat their eggs and the fry start very small, so success comes from a separate breeding tank and good tiny live foods.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Males have a larger black dorsal fin; females show red in the fins and a rounder body", "group": "One pair, or a small group with more males than females", "breeding_tank": "10 gallon, dim, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on live or frozen bloodworms, brine shrimp and daphnia", "trigger": "Soft, acidic water and morning light after moving the pair in", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 24 to 36 hours at 77 to 80°F", "fry": "Free swimming in about 3 to 5 days; very small", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 8 to 12 weeks to reach roughly 0.75 inch", "parents": "No care; remove adults after spawning or they eat the eggs"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 gallon tank with a sponge filter and a thick mat of java moss, a spawning mop, or mesh over the bottom. Keep lighting dim and cover the back and sides.\n\nThe site's keeping range is 72 to 82°F, pH 6 to 7.5 and GH 3 to 15. For spawning, drop to the soft and acidic side: about pH 6 to 6.5, GH under 6, and around 77 to 80°F. Filtering over peat or using a mix of RO and tap water are common ways to soften."}, {"heading": "Conditioning and choosing a pair", "text": "Males are easy to spot by their tall, jet black dorsal fin, which they flare at each other. Females are rounder, often show reddish pink in the pelvic, anal and adipose fins, and have a smaller dorsal.\n\nCondition for one to two weeks with bloodworms, brine shrimp and daphnia, plus a quality flake. A female ready to spawn will look full and heavy.\n\nMale black phantoms spend a lot of time sparring with spread fins. This is mostly display and rarely causes damage, but if you condition several males together, give them plenty of plants and space. Pick the boldest male with the fullest dorsal fin and the plumpest female. Have infusoria and microworm or vinegar eel cultures running before you spawn them, since the fry will need food within a few days of hatching."}, {"heading": "Spawning: what you'll see", "text": "Move the pair into the breeding tank in the evening. Most spawns happen the next morning. The male displays with spread fins, then drives the female into the moss, where they release eggs and milt side by side. Each pass drops a few eggs, and a full spawn is commonly 100 to 300 eggs.\n\nIf they have not spawned in two or three days, a small water change with slightly cooler soft water may help. Otherwise return them to conditioning and try again in a week."}, {"heading": "Eggs and fungus", "text": "Remove the adults straight after spawning. Keep the tank dim, because tetra eggs are sensitive to light. They hatch in about 24 to 36 hours at 77 to 80°F.\n\nInfertile eggs turn white and fuzzy. Remove them where you can, and consider a few dried leaves or a light dose of methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "The fry hang on surfaces at first and become free swimming roughly 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: brine shrimp and finely powdered flake or fry food\n\nStart 10% water changes every couple of days from the second week. Match temperature and hardness closely, and slowly increase lighting."}, {"heading": "Growing out", "text": "Black phantom fry grow steadily and reach about three quarters of an inch in about 8 to 12 weeks. The black shoulder spot appears early, and males start to show their taller dorsal fins by about 3 to 4 months.\n\nA large spawn will quickly outgrow a 10 gallon tank. Move the fry to a bigger tank or split them across tanks as soon as they are eating brine shrimp well. Keep up regular water changes of 20 to 30% a week and feed small meals several times a day for the fastest, most even growth."}, {"heading": "Common mistakes", "text": "- Keeping eggs in bright light\n- Hard water that cuts fertility\n- Leaving adults in with the eggs\n- Feeding too large a food in the first week\n- Overfeeding a bare tank and fouling the water"}]$g$::jsonb, $g$[{"q": "How can you tell male and female black phantom tetras apart?", "a": "Males have a large black dorsal fin and spar with each other. Females are rounder and usually show red or pink in their lower fins and adipose fin."}, {"q": "How long do black phantom tetra eggs take to hatch?", "a": "About 24 to 36 hours at 77 to 80°F. Fry become free swimming a few days later."}, {"q": "Do black phantom tetras eat their eggs?", "a": "Yes. Remove the adults as soon as spawning finishes."}, {"q": "What water do black phantom tetras need to breed?", "a": "Soft, slightly acidic water works best, around pH 6 to 6.5 with low hardness, at 77 to 80°F."}]$g$::jsonb, $g$Get a stage 1 photo showing the male's big black dorsal and the female's red fins side by side with your challenge code card, so the pair is obvious. Log stage 3 only once fry are swimming freely, at least 3 days after your stage 2 eggs.$g$),
  ($g$diamond-tetra$g$, $g$e2ef179b-16d0-4028-af15-4dc261674913$g$::uuid, $g$diamond-tetra$g$, null, $g$How to Breed Diamond Tetras: Soft Water Spawning Guide$g$, $g$Diamond tetras scatter eggs over fine plants in soft, acidic water. Remove the adults, keep the eggs dim and start fry on infusoria. A moderate project.$g$, $g$Diamond tetras are one of the showier tetras to breed, with sparkling scales and long finned males. They spawn like most egg scattering tetras, and a conditioned pair in soft water can produce a lot of eggs. Expect to protect the eggs from the parents, guard against fungus and supply tiny foods for the first week, which is why this sits in Society class C.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Males have longer, flowing dorsal and anal fins and more sparkle; females rounder", "group": "One pair, or 2 males to 1 female", "breeding_tank": "10 to 20 gallon, dim, moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, brine shrimp, daphnia and quality flake", "trigger": "Soft acidic water, morning light, a slightly cooler soft water change", "spawn": "Commonly a few hundred eggs from a large female", "eggs": "Hatch in about 1 to 2 days at 77 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 3 months to around 1 inch", "parents": "No care; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Diamonds are a little larger than many tetras, so a 10 to 20 gallon tank works well. Use a sponge filter, a mat of java moss or a spawning mop, and mesh or marbles on the bottom. Keep the light dim.\n\nThe site lists 72 to 82°F, pH 5.5 to 7.5 and GH 4 to 15 for keeping. For spawning, aim for soft, acidic water: pH around 6 to 6.5 with low hardness, at 77 to 80°F."}, {"heading": "Conditioning and choosing a pair", "text": "Adult males develop long, trailing dorsal and anal fins and a stronger violet sparkle. Females are rounder with shorter fins. Note that the full sparkle takes many months to develop, so young fish can be hard to sex.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and a good flake. Separating the sexes during this time often improves results.\n\nChoose a female that looks clearly full of eggs and a male in his best color. Prepare an infusoria culture and a vinegar eel or microworm culture at least a week ahead, as you will need them within a few days of the eggs hatching. Having baby brine shrimp hatching on schedule for week two also saves a lot of stress."}, {"heading": "Spawning: what you'll see", "text": "Add the pair in the evening. Spawning commonly starts with the first light next morning. The male displays with spread fins and leads the female into the plants, where they quiver together and scatter eggs. A large, well fed female can lay a few hundred eggs over a couple of hours.\n\nIf they do not spawn within a few days, try a small water change with slightly cooler soft water. Some pairs need a second attempt after another week of conditioning, so do not give up after one try.\n\nA pair can be spawned again every couple of weeks if they are well fed between spawns, so a missed or poor first spawn is not a big loss."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning is over. Keep the tank dark or very dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nPull out white, fungused eggs where you can. A few dried leaves or a mild dose of methylene blue are common ways to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: brine shrimp and finely crushed flake\n\nFrom week two, change about 10% of the water every couple of days with matched water. Keep the temperature steady near 78°F."}, {"heading": "Growing out", "text": "Diamond tetra fry grow at a moderate pace, reaching about 1 inch in roughly 3 months. The famous sparkle develops slowly and can take most of a year to show fully. Give the growing fish more space and keep feeding varied foods.\n\nMove the young fish into a larger, planted tank once they are eating brine shrimp well. Weekly water changes of 20 to 30% and several small meals a day give the most even growth. Sort out any runts so they are not outcompeted at feeding time."}, {"heading": "Common mistakes", "text": "- Choosing young fish before they can be sexed reliably\n- Bright light on eggs\n- Hard, alkaline water\n- Leaving parents in the tank\n- Feeding food that is too large in the first week"}]$g$::jsonb, $g$[{"q": "How do you sex diamond tetras?", "a": "Adult males have longer, flowing dorsal and anal fins and more sparkle. Females are rounder with shorter fins. Young fish are hard to tell apart."}, {"q": "How long do diamond tetra eggs take to hatch?", "a": "About 1 to 2 days at 77 to 80°F, with fry free swimming a few days later."}, {"q": "When do diamond tetras get their sparkle?", "a": "The sparkle builds slowly and can take many months to most of a year to fully develop."}, {"q": "Do diamond tetras eat their eggs?", "a": "Yes. Move the adults out once spawning is finished."}]$g$::jsonb, $g$Use mature fish for your stage 1 photo so the male's long fins are clearly visible next to the female and the challenge code card. Fry stay small for a while, so plan your stage 5 photo in a small clear container where the young fish are easy to count.$g$),
  ($g$ember-tetra$g$, $g$5ec0268c-7d44-4f17-8d00-0fa94a43ba2c$g$::uuid, $g$ember-tetra$g$, null, $g$How to Breed Ember Tetras: Moss, Soft Water and Micro Fry$g$, $g$Ember tetras scatter small batches of eggs in moss. The challenge is tiny fry that need infusoria for a week or more. A moderate nano tank project.$g$, $g$Ember tetras are tiny, bright and surprisingly willing to spawn in a mature, mossy tank. Many breeders first notice a few fry appearing in a planted species tank. Getting good numbers is harder, because the eggs are few and small and the fry are among the tiniest of any common tetra, so a ready supply of microscopic food is the key to success.$g$, $g${"method": "Egg scatterer (eggs dropped into moss and fine plants)", "sexing": "Males slimmer and more intense orange red; females rounder and slightly paler", "group": "One pair or a small group with a couple of males per female", "breeding_tank": "5 to 10 gallon, mature, dense java moss, sponge filter, dim light", "conditioning": "1 to 2 weeks on baby brine shrimp, daphnia, cyclops and fine flake", "trigger": "Soft, acidic water and morning light in a mature mossy tank", "spawn": "Small batches; commonly a few dozen eggs per spawn", "eggs": "Hatch in about 24 to 36 hours at 77 to 80°F", "fry": "Free swimming in about 3 to 4 days; extremely small", "first_foods": "Infusoria or paramecium, then vinegar eels, then baby brine shrimp after 1 to 2 weeks", "grow_out": "About 2 to 3 months to around half an inch with color", "parents": "No care; adults eat eggs and fry, so separate them or provide thick moss"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is enough. The best results come from a mature tank that has been running for weeks with plenty of biofilm and microscopic life. Fill it with dense java moss or other fine leaved plants, use a gentle sponge filter, and keep the light low.\n\nThe site lists 73 to 82°F, pH 5.5 to 7 and GH 2 to 10 for embers. For breeding, stay soft and acidic: around pH 6 to 6.5 and GH under 5, at 77 to 80°F. A few dried leaves help soften and tint the water and grow infusoria at the same time."}, {"heading": "Conditioning and choosing a pair", "text": "Males are slimmer with a deeper orange red color, especially when displaying. Females are rounder through the belly and a little paler. Condition for one to two weeks with live or frozen baby brine shrimp, daphnia, cyclops and a fine flake.\n\nEmbers are tiny, so their foods should be tiny too. Pick one plump female with one or two of the brightest males, or move a small group of four to six fish into the breeding tank. Start an infusoria culture and a vinegar eel culture before you set them up."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the morning. The male flashes his colors and drives the female into the moss, where they quiver together and release a few eggs at a time. Embers lay far fewer eggs than larger tetras; a few dozen per spawn is typical, and the eggs are almost invisible.\n\nThere are two common methods. One is to leave the pair in for two or three days and then remove them. The other is a colony approach: keep a small group in a heavily mossed species tank and let a few fry survive among the moss without separating anything. The colony method gives fewer fry per spawn but needs little effort."}, {"heading": "Eggs and fungus", "text": "Once the adults are out, keep the tank dim. Eggs hatch in about 24 to 36 hours at 77 to 80°F. Because the eggs are so small and hidden in moss, you may not see them at all until fry appear.\n\nFungus is less of a problem in a mature, leafy tank, but keep the water clean and avoid overfeeding the adults while they are in the tank."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 4 days after hatching and are tiny, close to the size of a dust speck. This is the stage where most attempts fail.\n\n- Week 1: infusoria or paramecium several times a day, plus whatever grows on the moss\n- Week 2: vinegar eels added, along with very fine powdered fry food\n- Weeks 2 to 3 on: newly hatched brine shrimp once their bellies can take it\n\nDo not change much water in the first week; top up with matched soft water. From week two, small changes of about 10% every few days keep things clean. Keep the temperature steady at 77 to 79°F."}, {"heading": "Growing out", "text": "Ember fry grow slowly at first and then pick up speed once they eat baby brine shrimp. Expect around 2 to 3 months to reach about half an inch and start showing orange color. They can join the adults in a planted tank once they are too big to be eaten, usually at about a third of an inch."}, {"heading": "Common mistakes", "text": "- Starting in a brand new, sterile tank with no microscopic food\n- Offering baby brine shrimp too early; the fry are too small\n- Large water changes that shock tiny fry\n- Hard water, which cuts fertility\n- Expecting large spawns like bigger tetras"}]$g$::jsonb, $g$[{"q": "How do I tell male and female ember tetras apart?", "a": "Males are slimmer and a deeper orange red. Females are rounder through the belly and a little paler."}, {"q": "Will ember tetras breed in a community tank?", "a": "They often spawn in planted tanks, but most eggs and fry are eaten. A mature mossy species tank gives a few fry a real chance."}, {"q": "How many eggs do ember tetras lay?", "a": "Far fewer than larger tetras. A few dozen per spawn is typical."}, {"q": "What do ember tetra fry eat?", "a": "Infusoria or paramecium first, then vinegar eels and fine powdered food, then newly hatched brine shrimp after a week or two."}]$g$::jsonb, $g$If you use a colony tank, open your log before the fish go in and show the group with the challenge code card for stage 1. Ember fry are tiny, so for stage 3 a close photo against a dark background or in a small white dish makes them easy to see.$g$),
  ($g$glowlight-tetra$g$, $g$1ed9a59e-d97f-4da5-9173-c1cbac9f51a9$g$::uuid, $g$glowlight-tetra$g$, null, $g$How to Breed Glowlight Tetras: Pairs, Eggs and First Foods$g$, $g$Glowlight tetras spawn in pairs over fine plants in soft water. Remove adults, keep eggs dim, and feed infusoria first. A solid first tetra to breed.$g$, $g$Glowlight tetras are one of the friendliest tetras to breed. A well conditioned pair often spawns the morning after being moved into a soft water tank, with the male and female rolling side by side through the plants. The usual tetra challenges apply: adults eat the eggs, the eggs prefer low light, and the fry need tiny foods for the first week.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Females rounder and deeper bodied; males slimmer", "group": "One pair", "breeding_tank": "5 to 10 gallon, dim, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on brine shrimp, bloodworms, daphnia and quality flake", "trigger": "Soft, slightly acidic water and morning light", "spawn": "Commonly 100 to 200 eggs", "eggs": "Hatch in about 24 hours at 78 to 80°F", "fry": "Free swimming in about 3 to 5 days; very small", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 2 to 3 months to around 0.75 inch", "parents": "No care; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 5 to 10 gallon tank with a sponge filter, mesh or marbles on the bottom, and a mat of java moss or a spawning mop. Keep the room dim and cover the sides.\n\nThe site lists 74 to 82°F, pH 5.5 to 7.5 and GH 2 to 12 for glowlights. For spawning, aim for soft, slightly acidic water around pH 6 to 6.5 and GH under 6, at 78 to 80°F. Filtering over peat or mixing RO water with tap water are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and noticeably rounder, especially from the side, while males are slimmer. Condition for one to two weeks on brine shrimp, bloodworms, daphnia and flake, ideally with the sexes kept apart.\n\nChoose a female that looks full of eggs and an active, well colored male. Start an infusoria culture and a microworm or vinegar eel culture before you spawn them.\n\nA female that has been well fed for two weeks is usually obvious: she looks swollen behind the pelvic fins when viewed from above. If she still looks slim, give it another week. Spawning an underconditioned female tends to give small spawns with many infertile eggs, which only invites fungus into the tank."}, {"heading": "Spawning: what you'll see", "text": "Move the pair in the evening. In the morning the male chases the female and the two often swim side by side and roll over together as they release eggs, a behavior many breeders describe as a barrel roll. Eggs drop into the moss a few at a time. A full spawn is commonly 100 to 200 eggs.\n\nIf nothing happens in two or three days, try a small water change with slightly cooler soft water. If that fails, return them to conditioning for another week."}, {"heading": "Eggs and fungus", "text": "Remove the adults right after spawning. Keep the tank dim, as tetra eggs are light sensitive. Eggs hatch in about 24 hours at 78 to 80°F.\n\nInfertile eggs turn white and grow fungus. Remove them where you can and consider a few dried leaves or a light dose of methylene blue to keep fungus down."}, {"heading": "Raising the fry", "text": "The fry hang on the glass and moss at first, then become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching temperature and hardness. Slowly increase light as the fry grow. Keep the temperature steady around 78°F, since swings stress tiny fry.\n\nA common trick is to add a few small snails or a little established moss from another tank before the fry hatch. They help keep uneaten food from fouling the water while the fry are too small to clean up after."}, {"heading": "Growing out", "text": "Glowlight fry grow at a steady pace and reach about three quarters of an inch in 2 to 3 months. The glowing stripe appears after a few weeks. Move them to a larger tank as they grow, feed several small meals a day and keep up weekly water changes of 20 to 30%."}, {"heading": "Common mistakes", "text": "- Bright light on the eggs and young fry\n- Leaving the parents in the tank\n- Water that is too hard\n- Feeding food that is too big in the first week\n- Overfeeding a bare breeding tank\n- Moving fry to new water without matching temperature"}]$g$::jsonb, $g$[{"q": "How do you tell glowlight tetra males from females?", "a": "Females are bigger and rounder through the belly. Males are slimmer and more streamlined."}, {"q": "How long do glowlight tetra eggs take to hatch?", "a": "About 24 hours at 78 to 80°F. Fry become free swimming a few days after hatching."}, {"q": "Are glowlight tetras easy to breed?", "a": "They are one of the easier tetras to spawn, but you still need soft water, a separate tank and tiny first foods to raise the fry."}, {"q": "Do glowlight tetras eat their eggs?", "a": "Yes. Remove the adults as soon as spawning is finished."}]$g$::jsonb, $g$Glowlight pairs often spawn the first morning, so open your log and take the stage 1 pair photo with the challenge code card before you move them in. Photograph eggs in the moss with a flashlight for stage 2.$g$),
  ($g$beckford-pencilfish$g$, $g$3644a66b-02e6-4fd2-8374-06be6ff54014$g$::uuid, $g$beckford-pencilfish$g$, null, $g$How to Breed Golden Pencilfish: Daily Eggs and Tiny Fry$g$, $g$Golden pencilfish lay a few eggs a day among plants over many days. Protect eggs from the adults and feed infusoria first. A moderate soft water project.$g$, $g$Golden pencilfish (Nannostomus beckfordi) are among the easier pencilfish to breed, but they spawn differently from most tetras. Instead of one big burst, a pair lays a few eggs at a time over days, and the adults happily eat them. Breeders who move plants or eggs daily, or who use a heavily planted tank, are rewarded with tiny fry that need careful early feeding.$g$, $g${"method": "Egg scatterer (a few eggs at a time among fine plants, over several days)", "sexing": "Males slimmer with brighter red and white tipped pelvic fins; females rounder", "group": "One pair, or 1 male to 2 females", "breeding_tank": "5 to 10 gallon, dense fine plants or moss, sponge filter, dim light", "conditioning": "1 to 2 weeks on daphnia, baby brine shrimp, cyclops and fine flake", "trigger": "Soft, acidic water and a settled pair in a well planted tank", "spawn": "A few eggs a day, adding up to a few dozen over a spawning period", "eggs": "Hatch in roughly 1 to 3 days at 77 to 79°F", "fry": "Free swimming about 3 to 5 days after hatching; extremely small", "first_foods": "Infusoria or paramecium, then vinegar eels, then baby brine shrimp", "grow_out": "About 3 months to roughly 1 inch", "parents": "No care; adults eat eggs, so move egg laden plants or the adults"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty. Plant it heavily with fine leaved plants or moss, add a gentle sponge filter, and keep the light low. Floating plants help keep the surface dim.\n\nThe site lists a wide range of 72 to 80°F, pH 5 to 7.5 and GH 1 to 12. For breeding, aim for the soft, acidic end: around pH 6 to 6.5 and GH under 5, at 77 to 79°F."}, {"heading": "Conditioning and choosing a pair", "text": "Males are slimmer, show a stronger red in the fins and stripe, and usually have white or bluish tips on the pelvic fins. Females are rounder and paler. Like other pencilfish, both sexes switch to a pattern of dark blotches at night, which is normal.\n\nCondition for one to two weeks with small live and frozen foods such as daphnia, cyclops and baby brine shrimp. Pencilfish have small mouths, so keep foods fine. Start infusoria and vinegar eel cultures in advance."}, {"heading": "Spawning: what you'll see", "text": "Pencilfish do not spawn in a single burst. The male displays with spread fins, leads the female into the plants and the pair release a few eggs at a time. This continues on and off for days. The total from one pair is commonly a few dozen eggs over a spawning period.\n\nBecause the adults eat eggs, many breeders use one of two methods. One is to move the clumps of moss or plants into a separate hatching tank every day or two and replace them. The other is to leave a pair in a very heavily planted tank for about a week and then remove the adults."}, {"heading": "Eggs and fungus", "text": "The eggs are small, clear and hard to see. They hatch in roughly 1 to 3 days at 77 to 79°F, depending on temperature. Keep the hatching tank dim.\n\nFungus is usually limited in a planted, soft water setup, but remove any white eggs you can see and avoid overfeeding nearby."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 3 to 5 days after hatching. They are very small and need microscopic food.\n\n- Week 1: infusoria or paramecium several times a day\n- Week 2: vinegar eels and very fine powdered food\n- Week 3 on: newly hatched brine shrimp, then crushed flake\n\nKeep water changes small, about 10% every few days with matched soft water, and avoid temperature swings. If you move plants with eggs every few days, you will end up with fry of different ages, so keep batches in separate containers if you can, as larger fry outcompete smaller ones."}, {"heading": "Growing out", "text": "Pencilfish fry grow slowly at first. Expect roughly 3 months to reach about 1 inch, and a little longer for the full adult color. Feed several small meals a day and keep up regular water changes in a planted grow out tank.\n\nGolden pencilfish stay peaceful as they grow, so a planted community style grow out tank with only small, gentle tank mates works well once the young are about half an inch. Males start to show the red fins and white pelvic tips as they mature, which makes it easy to pick out future breeding pairs. Weekly water changes of 20 to 30% and fine, varied foods give the best color."}, {"heading": "Common mistakes", "text": "- Waiting for one big spawn, when pencilfish lay a few eggs a day\n- Leaving eggs with the adults for weeks\n- Offering food too large for the fry's tiny mouths\n- Hard or alkaline water\n- Mixing fry of very different sizes"}]$g$::jsonb, $g$[{"q": "How do you sex golden pencilfish?", "a": "Males are slimmer and brighter red, usually with white or bluish tips on the pelvic fins. Females are rounder and paler."}, {"q": "How long do pencilfish eggs take to hatch?", "a": "Breeders commonly report about 1 to 3 days at 77 to 79°F."}, {"q": "Why does my pencilfish look blotchy at night?", "a": "Pencilfish change to a night pattern of dark blotches or bars when the lights go off. It is normal and fades in the morning."}, {"q": "Do pencilfish eat their eggs?", "a": "Yes. Move the plants with eggs to a separate tank every day or two, or remove the adults after about a week."}]$g$::jsonb, $g$Because pencilfish spawn a few eggs at a time, a stage 2 photo of eggs on a moss clump in a white dish is often clearer than shooting the main tank. Keep track of dates if you move plants in batches, as stage 3 has to come at least 3 days after your logged spawn.$g$),
  ($g$lemon-tetra$g$, $g$92240cd8-5cca-41d5-90fc-f52ae10b1e9e$g$::uuid, $g$lemon-tetra$g$, null, $g$How to Breed Lemon Tetras: Conditioning, Eggs and Fry$g$, $g$Lemon tetras scatter many eggs over fine plants in soft water. Remove the adults, keep eggs dim and feed infusoria first. A moderate tetra to breed.$g$, $g$Lemon tetras are a classic breeding tetra, with males that show off bright yellow and black fins when they are ready to spawn. A conditioned pair or small group can produce a large batch of eggs in a soft water tank. The steps are the usual ones for egg scatterers: separate the eggs from the adults, keep things dim and supply tiny live foods.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Males have a wider black edge on the anal fin and brighter yellow; females rounder", "group": "One pair, or a small group with more males than females", "breeding_tank": "10 gallon, dim, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, brine shrimp, daphnia and quality flake", "trigger": "Soft, slightly acidic water and morning light", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 1 to 2 days at 77 to 80°F", "fry": "Free swimming in about 3 to 5 days", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 3 months to around 1 inch", "parents": "No care; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank works well. Add a sponge filter, mesh or marbles on the bottom, and a mat of java moss or a spawning mop. Keep the light dim.\n\nThe site lists 72 to 81°F, pH 5.5 to 7.5 and GH 3 to 15 for keeping lemons. For spawning, aim for soft, slightly acidic water: around pH 6 to 6.5 and GH under 6, at 77 to 80°F."}, {"heading": "Conditioning and choosing a pair", "text": "Mature males show a broader black edge along the bright yellow anal fin, and the top of the eye turns a vivid red when they are in condition. Females are rounder and slightly paler.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and flake. Separating the sexes helps. Choose a plump female and the most colorful male, or put a small group of two males and two females into a larger breeding tank. Get infusoria and microworm or vinegar eel cultures going a week ahead of time."}, {"heading": "Spawning: what you'll see", "text": "Move the fish in the evening. Spawning usually starts the next morning. Males display with spread yellow fins, chase the female into the plants and the pair quiver side by side to release eggs. A full spawn is commonly 100 to 300 eggs.\n\nIf they do not spawn in a few days, try a small, slightly cooler soft water change, then go back to conditioning if needed.\n\nWatch the male's color. A ready male turns a much stronger yellow and the black on his fins becomes very sharp. A pale, shy male in the breeding tank usually means the fish are not yet settled. Give them a day or two before deciding the attempt has failed."}, {"heading": "Eggs and fungus", "text": "Remove the adults straight after spawning. Keep the tank dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nRemove white, fungused eggs where you can. A few dried leaves or a light dose of methylene blue can help limit fungus.\n\nThe eggs are small and slightly sticky, so most will be caught in the moss or under the mesh. Leave them where they fell rather than trying to move them."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching temperature and hardness. Gradually increase the light.\n\nA large spawn can produce more fry than one small tank can support. Once they are on baby brine shrimp, thin them out into a second tank rather than letting the water quality slide."}, {"heading": "Growing out", "text": "Lemon tetra fry reach around 1 inch in about 3 months. The yellow color builds slowly and the full adult color takes several more months. Grow them out in a larger tank with weekly 20 to 30% water changes and varied foods. Lemons that get a good mix of foods tend to color up better as adults.\n\nOnce the young fish are about half an inch they can move into a planted tank with other small, peaceful fish. Keep back a few of the best colored males and roundest females as your next breeding group. Avoid pairing siblings for generation after generation; bring in unrelated stock from time to time."}, {"heading": "Common mistakes", "text": "- Leaving the parents with the eggs\n- Bright light on the eggs\n- Hard water lowering fertility\n- Feeding food too large in the first week\n- Crowding a large spawn into a small tank\n- Expecting full adult color from young fish"}]$g$::jsonb, $g$[{"q": "How do you tell male and female lemon tetras apart?", "a": "Males have a wider black edge on the yellow anal fin and brighter color. Females are rounder and paler."}, {"q": "How long do lemon tetra eggs take to hatch?", "a": "About 1 to 2 days at 77 to 80°F, with fry free swimming a few days later."}, {"q": "Why are my lemon tetras pale?", "a": "Lemon tetras color up best with good feeding and mature age. Young or stressed fish are often pale."}, {"q": "Do lemon tetras eat their eggs?", "a": "Yes. Remove the adults as soon as spawning ends."}]$g$::jsonb, $g$A stage 1 photo with the male's black edged anal fin clearly visible next to the female and the challenge code card shows you have a real pair. Lemon fry are pale and small, so a dark background helps for stage 3 and later photos.$g$),
  ($g$penguin-tetra$g$, $g$25597711-ef13-4665-8c1b-eb71981e1bb5$g$::uuid, $g$penguin-tetra$g$, null, $g$How to Breed Penguin Tetras: A Prolific Egg Scatterer$g$, $g$Penguin tetras are prolific egg scatterers that can lay hundreds of eggs. Remove adults, keep eggs dim and start fry on infusoria. A moderate project.$g$, $g$Penguin tetras are known in the hobby as prolific spawners, and a well conditioned female can produce a very large batch of eggs. They are peaceful and not fussy about water, which makes them a good choice for breeders moving up from easy livebearers. The challenges are the usual ones: hungry parents, fungus on infertile eggs and tiny fry that need small live foods.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Females deeper bodied and rounder; males slimmer", "group": "One pair, or 2 males to 1 female", "breeding_tank": "10 to 20 gallon, dim, moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, brine shrimp, daphnia and quality flake", "trigger": "Soft, slightly acidic water and morning light", "spawn": "Commonly several hundred eggs; large females can lay more", "eggs": "Hatch in about 1 to 2 days at 77 to 80°F", "fry": "Free swimming in about 3 to 5 days", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 3 months to around 1 inch", "parents": "No care; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 to 20 gallon tank with a sponge filter, mesh or marbles on the bottom, and a thick mat of java moss or a spawning mop. Keep the light low.\n\nThe site lists 72 to 82°F, pH 6 to 7.5 and GH 2 to 15. Penguins are not as fussy as some tetras, but softer, slightly acidic water around pH 6.5 and GH under 8, at 77 to 80°F, improves fertility and hatch rates."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and deeper through the belly, while males are slimmer. Condition for one to two weeks on bloodworms, brine shrimp, daphnia and quality flake.\n\nPick the roundest female and an active male, or try two males with one female. Because penguins can lay a lot of eggs, prepare plenty of infusoria and microworms or vinegar eels in advance, and think about where a big batch of fry will go."}, {"heading": "Spawning: what you'll see", "text": "Move the fish into the breeding tank in the evening. Spawning commonly happens the next morning. The male chases the female into the plants and they quiver side by side, releasing eggs a few at a time. Penguin tetras are often described as prolific; several hundred eggs from one spawn is commonly reported.\n\nIf they do not spawn in two or three days, try a small cooler water change, then return them to conditioning if needed.\n\nPenguins swim at a characteristic head up angle, and a ready male will display around the female with spread fins. Spawning usually lasts a couple of hours. Once the female looks noticeably slimmer and the chasing stops, the spawn is over."}, {"heading": "Eggs and fungus", "text": "Remove the adults right after spawning. Keep the tank dim. Eggs hatch in about 1 to 2 days at 77 to 80°F.\n\nWith so many eggs, some will be infertile. Remove white, fungused eggs where you can, and consider a few dried leaves or a light dose of methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nA large batch of fry fouls water fast. Start 10 to 20% water changes every day or two from week two, matching temperature and hardness. Split the fry into more tanks as they grow rather than letting water quality drop. A few small snails in the fry tank help clean up uneaten food. Keep the temperature steady at 77 to 79°F."}, {"heading": "Growing out", "text": "Penguin fry grow at a good pace and show the black tail stripe early. Expect about 3 months to reach roughly 1 inch. Keep feeding several times a day, keep up weekly 20 to 30% water changes and give the growing fish room. Thinning out a large spawn early leads to bigger, healthier young fish.\n\nBy around half an inch the young fish can share a planted tank with other small, peaceful species. Penguins are a schooling fish, so keep the young in groups. When it is time to pass them on, a group of at least six is the friendliest way to rehome them."}, {"heading": "Common mistakes", "text": "- Leaving the parents in with the eggs\n- Not planning space for a big spawn\n- Letting fungus spread across a large batch of eggs\n- Feeding too large a food in the first week\n- Skipping water changes in a crowded fry tank\n- Bright light on eggs and newly hatched fry"}]$g$::jsonb, $g$[{"q": "How do you tell male and female penguin tetras apart?", "a": "Females are larger and rounder in the belly. Males are slimmer."}, {"q": "How many eggs do penguin tetras lay?", "a": "Penguins are known as prolific spawners, and several hundred eggs from one spawn is commonly reported."}, {"q": "How long do penguin tetra eggs take to hatch?", "a": "About 1 to 2 days at 77 to 80°F. Fry are free swimming a few days later."}, {"q": "Do penguin tetras eat their eggs?", "a": "Yes. Remove the adults as soon as spawning is over."}]$g$::jsonb, $g$Penguin spawns are large, so for stage 5 focus on a clear photo of a good group of 60 day fry with the challenge code card rather than trying to count every fish. Note the date of your stage 2 eggs so you can time stages 3, 4 and 5 correctly.$g$),
  ($g$red-phantom-tetra$g$, $g$40f9385e-09a6-40d5-959e-d94d2ffe4657$g$::uuid, $g$red-phantom-tetra$g$, null, $g$How to Breed Red Phantom Tetras: Soft Water and Fry Care$g$, $g$Red phantom tetras scatter eggs in soft, acidic water. Remove the adults, protect eggs from light and feed infusoria first. A moderate tetra project.$g$, $g$Red phantom tetras are a little more demanding than their black cousins. They like soft, acidic water and slightly cooler temperatures, and they spawn best when well conditioned and settled. Once you get the water right, a pair will scatter eggs among fine plants, and the fry respond well to the same careful early feeding that works for other small tetras.$g$, $g${"method": "Egg scatterer (eggs among fine plants or moss)", "sexing": "Males have a taller, mostly red dorsal fin; females have a black and white patch in the dorsal", "group": "One pair, or 2 males to 1 female", "breeding_tank": "10 gallon, dim, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, brine shrimp, daphnia and quality flake", "trigger": "Very soft, acidic water around pH 6 and morning light", "spawn": "Commonly 100 to 300 eggs from a well conditioned female", "eggs": "Hatch in about 1 to 2 days at 75 to 78°F", "fry": "Free swimming in about 3 to 5 days; very small", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 3 months to roughly 0.75 inch", "parents": "No care; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank with a sponge filter, mesh or marbles on the bottom and a thick mat of java moss or a spawning mop is ideal. Keep the light dim and cover the sides.\n\nThe site lists a cooler, softer range for red phantoms: 71 to 79°F, pH 5 to 7 and GH 1 to 12. For spawning, keep the water soft and acidic, around pH 6 and GH under 4, at about 75 to 78°F. Peat filtration, dried leaves and RO water are common ways to get there."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing is fairly easy in adults. Males have a taller, more pointed, mostly red dorsal fin and are slimmer. Females have a smaller dorsal fin marked with black and white, and a rounder belly.\n\nCondition for one to two weeks with bloodworms, brine shrimp, daphnia and a quality flake. Wild caught or recently imported fish may need longer to settle and recover before they spawn well. Pick the roundest female and a male in strong color.\n\nSet up infusoria and microworm or vinegar eel cultures at least a week ahead. The fry need tiny food within days of hatching, and it is hard to start a culture fast enough once they are already swimming."}, {"heading": "Spawning: what you'll see", "text": "Move the pair into the breeding tank in the evening. Spawning commonly starts the next morning. The male displays with his red fins spread, leads the female into the moss, and the pair quiver side by side to release a few eggs at a time. A well conditioned female commonly lays 100 to 300 eggs.\n\nIf they do not spawn in a few days, a small water change with slightly cooler, very soft water may help. Some pairs need a second or third try.\n\nYou can also try a small group spawn with two males and one or two females in a slightly larger tank. Competition between males often triggers spawning in fish that ignore each other as a single pair. Expect more egg eating in a group spawn, so remove the adults promptly."}, {"heading": "Eggs and fungus", "text": "Remove the adults as soon as spawning ends. Keep the tank dark or very dim, as the eggs are light sensitive. Eggs hatch in about 1 to 2 days at 75 to 78°F.\n\nIn very soft water, fungus can spread quickly from dead eggs. Remove white eggs where you can and consider a few dried leaves or a light dose of methylene blue."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 3 to 5 days after hatching.\n\n- First week free swimming: infusoria or paramecium several times a day\n- Week 2: vinegar eels or microworms, then newly hatched brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nStart 10% water changes every couple of days from week two, matching the soft water closely. Keep the temperature steady and slowly increase the light."}, {"heading": "Growing out", "text": "Red phantom fry grow steadily and reach about three quarters of an inch in around 3 months. Red color builds gradually as they mature. Grow them on in a larger tank with weekly 20 to 30% water changes and varied foods. Slowly acclimate young fish to slightly harder water if they are going to buyers with different tap water.\n\nOnce the young fish are about half an inch they can share a planted tank with other small, peaceful fish. Keep a group of the best colored young as future breeders, and bring in unrelated fish now and then to avoid inbreeding over many generations."}, {"heading": "Common mistakes", "text": "- Water that is too hard or alkaline\n- Running the breeding tank too warm\n- Bright light on eggs\n- Leaving the adults in after spawning\n- Feeding food that is too large in the first week"}]$g$::jsonb, $g$[{"q": "How do you tell male and female red phantom tetras apart?", "a": "Males have a taller, mostly red dorsal fin. Females have a smaller dorsal fin with black and white markings and a rounder belly."}, {"q": "How long do red phantom tetra eggs take to hatch?", "a": "About 1 to 2 days at 75 to 78°F, with fry free swimming a few days later."}, {"q": "What water do red phantom tetras need to breed?", "a": "Very soft, acidic water around pH 6 with low hardness gives the best results."}, {"q": "Do red phantom tetras eat their eggs?", "a": "Yes. Remove the adults as soon as spawning is over."}]$g$::jsonb, $g$Make sure your stage 1 photo shows both dorsal fins clearly, the male's tall red one and the female's black and white patch, along with the challenge code card. That makes the pair easy to verify.$g$),
  ($g$splash-tetra$g$, $g$0d52ec10-0c51-4bd1-b214-366b1ca133d4$g$::uuid, $g$splash-tetra$g$, null, $g$How to Breed Splash Tetras: Eggs Laid Above the Water$g$, $g$Splash tetras leap to lay eggs above the waterline and the male splashes them until they hatch. A tight lid and tiny foods are key. Moderate.$g$, $g$Splash tetras have one of the most remarkable spawning behaviors in the hobby. The pair leaps out of the water together to stick their eggs on a leaf or the underside of a lid, and the male then keeps them wet by splashing water over them until they hatch. Seeing it happen is a real reward, and breeding them is quite manageable with the right tank setup.$g$, $g${"method": "Egg layer above the waterline (male splashes eggs to keep them wet)", "sexing": "Males larger with longer fins and red to orange markings; females smaller with shorter fins", "group": "One pair", "breeding_tank": "15 to 20 gallon, lowered water level, tight glass lid, overhanging leaf or slate", "conditioning": "1 to 2 weeks on mosquito larvae, fruit flies, bloodworms and brine shrimp", "trigger": "Soft, slightly acidic water and a gap of a few inches below the lid", "spawn": "Commonly several dozen to over 100 eggs from repeated leaps", "eggs": "Hatch in about 2 to 3 days at 77 to 80°F; fry drop into the water", "fry": "Free swimming within a few days of hatching; small", "first_foods": "Infusoria or vinegar eels, then baby brine shrimp", "grow_out": "About 3 months to roughly 1 inch", "parents": "Male tends eggs; remove adults once eggs hatch, as they may eat fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and a tight fitting glass lid. Splash tetras are excellent jumpers, so the lid is essential. Lower the water level to leave a gap of about 2 to 4 inches between the surface and the lid.\n\nGive the pair a spawning surface above the water. Many breeders let them use the underside of the glass lid, or place a broad plant leaf or a sloping piece of slate that overhangs the surface. Floating plants help the fish feel secure.\n\nThe site lists 73 to 82°F, pH 5 to 7.5 and GH 1 to 12. For spawning, soft and slightly acidic water around pH 6 to 6.5 at 77 to 80°F works well."}, {"heading": "Conditioning and choosing a pair", "text": "Males are larger and more colorful, with longer, flowing fins edged in red or orange. Females are smaller with shorter fins and less color.\n\nCondition for one to two weeks. Splash tetras feed heavily at the surface, so mosquito larvae, fruit flies, bloodworms and brine shrimp are ideal, along with flake. Pick a plump female and a male in full color.\n\nKeep the pair in the breeding tank for a few days before expecting a spawn. A settled male starts patrolling a spot just under the lid or leaf, which is usually where the eggs will be laid. If he picks a spot you cannot see well, that is fine; the splashing tells you where the eggs are."}, {"heading": "Spawning: what you'll see", "text": "The male courts the female near the surface and leads her to the spot he has picked. The pair then leap out of the water together, cling to the surface for a moment, and lay a few eggs before dropping back. This repeats many times, and the total commonly reaches several dozen to over 100 eggs.\n\nAfterward the male stays close to the egg site and regularly flicks water onto the eggs with his tail to keep them from drying out. Watching this is the best way to confirm a spawn."}, {"heading": "Eggs and hatching", "text": "Leave the male to do his job. The eggs hatch in about 2 to 3 days at 77 to 80°F, and the fry drop into the water below. Keep the room humid and the lid closed so the eggs do not dry out.\n\nOnce the eggs have hatched, remove both adults, as they may eat the fry. If the male is not tending the eggs, some breeders keep them moist with a gentle mist of tank water instead."}, {"heading": "Raising the fry", "text": "The fry become free swimming within a few days of hatching and stay near the surface.\n\n- First week: infusoria or vinegar eels several times a day\n- Week 2: newly hatched brine shrimp and very fine powdered food\n- Weeks 3 to 8: baby brine shrimp and crushed flake\n\nChange about 10% of the water every couple of days from week two, matching temperature and softness. Keep the lid on even for fry, as young splash tetras jump too.\n\nThe fry do best with a little floating plant cover and gentle filtration. Feed small amounts often, and siphon the bottom every day or two so leftover food does not foul the water."}, {"heading": "Growing out", "text": "Fry grow at a moderate pace, reaching about 1 inch in roughly 3 months. Males start to show longer fins as they mature. Grow them on in a covered tank with regular water changes and small surface foods."}, {"heading": "Common mistakes", "text": "- No lid, or a lid with gaps; splash tetras will jump out\n- Water level too high, leaving no space for egg laying\n- Removing the male before the eggs hatch\n- Leaving adults in with newly hatched fry\n- Letting the room dry out so eggs shrivel"}]$g$::jsonb, $g$[{"q": "Why does the splash tetra jump out of the water?", "a": "The pair leaps out together to lay eggs above the waterline, usually on a leaf or the underside of the lid. The male then splashes water on them until they hatch."}, {"q": "How long do splash tetra eggs take to hatch?", "a": "About 2 to 3 days at 77 to 80°F. The fry drop into the water when they hatch."}, {"q": "How do you tell male and female splash tetras apart?", "a": "Males are bigger and more colorful with longer fins edged in red or orange. Females are smaller with shorter fins."}, {"q": "Do splash tetras eat their fry?", "a": "They may. Remove both adults once the eggs have hatched."}]$g$::jsonb, $g$A photo of the eggs stuck above the waterline, ideally with the male splashing below, is excellent stage 2 evidence. Open your log and photograph the pair with the challenge code card before you lower the water level.$g$),
  ($g$angelfish$g$, $g$24cb1a77-ecc5-49e0-822e-72f970210973$g$::uuid, $g$angelfish$g$, null, $g$How to Breed Angelfish: Pairs, Slates and Raising Fry$g$, $g$Angelfish pair off and lay eggs on slates or leaves. Learn to sex them, hatch the eggs, and raise fry on baby brine shrimp. A moderate cichlid project.$g$, $g$Angelfish are one of the classic aquarium fish to breed, and watching a pair clean a slate and lay neat rows of eggs never gets old. The hardest part is often getting a true pair, because angels are hard to sex until they spawn. Young pairs commonly eat their first few batches of eggs, but they usually improve, and the fry are big enough to eat baby brine shrimp from the start.$g$, $g${"method": "Substrate spawner (eggs laid on slate, leaves or glass)", "sexing": "Unreliable by shape; best told by the breeding tube at spawning (male narrow, female blunt)", "group": "One pair; raise 6 juveniles to let a pair form", "breeding_tank": "20 to 30 gallon tall tank, sponge filter, slanted slate or broad leaf", "conditioning": "2 to 3 weeks on bloodworms, brine shrimp, blackworms and quality pellets", "trigger": "A bonded pair, warm stable water and frequent water changes", "spawn": "Commonly 200 to 1000 eggs", "eggs": "Hatch in about 2 to 3 days at 80 to 82°F", "fry": "Wigglers for about 4 to 5 days, then free swimming", "first_foods": "Newly hatched brine shrimp", "grow_out": "About 6 to 8 weeks to quarter size, 3 months or more to sell", "parents": "Parents fan and guard eggs; young pairs often eat eggs and improve with time"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A pair needs a tall tank of at least 20 to 30 gallons. Use a sponge filter or a well covered intake and a bare bottom for easy cleaning. Add a spawning site: a slanted slate, a length of PVC pipe, a broad plant leaf or a cone leaning against the glass.\n\nThe site lists 76 to 84°F, pH 6 to 7.5 and GH 3 to 15. Domestic angels spawn readily in that range. Most breeders keep spawning pairs at about 80 to 82°F with stable water and regular changes."}, {"heading": "Getting and conditioning a pair", "text": "Angelfish are hard to sex until they spawn. The most reliable way to get a pair is to raise about six young fish together and watch for two that claim a corner and chase the others away. Once they spawn, you can see the breeding tubes: the female's is broad and blunt, the male's is narrow and pointed.\n\nCondition for two to three weeks with bloodworms, brine shrimp, blackworms and quality pellets. Do frequent water changes during this time. Angels usually reach breeding age at around 8 to 12 months."}, {"heading": "Spawning: what you'll see", "text": "A pair ready to spawn will choose a site and clean it carefully with their mouths for a day or more. The breeding tubes then drop. The female makes passes along the surface laying rows of eggs, and the male follows to fertilize them. Spawns are commonly 200 to 1000 eggs, with older, larger females at the upper end.\n\nHealthy pairs often spawn every 1 to 2 weeks if they are well fed and their eggs are removed.\n\nIf you choose to let the parents raise the eggs, keep the tank quiet, avoid moving decor and keep other fish out. Parents that get through to free swimming fry can be great to watch, as they herd the cloud of babies around the tank."}, {"heading": "Eggs and fungus", "text": "You have two choices. Leave the eggs with the parents, who will fan and guard them, or remove the slate to a separate hatching tank. Many breeders remove the eggs, especially with young pairs that eat their first few spawns.\n\nIn a hatching container, place an air stone near the eggs so bubbles gently move water across them, and add a little methylene blue to help prevent fungus. Eggs hatch in about 2 to 3 days at 80 to 82°F. Infertile eggs turn white; remove them if you can."}, {"heading": "Raising the fry", "text": "After hatching, the fry are wigglers that hang from the slate or the bottom for about 4 to 5 days while they absorb their yolk. Once they swim freely, start feeding.\n\n- Weeks 1 to 2: newly hatched brine shrimp two or three times a day\n- Weeks 3 to 4: brine shrimp plus finely crushed flake or small pellets\n- Week 5 on: frozen foods and small pellets\n\nChange 10 to 20% of the water every day or two once they are eating, siphoning uneaten food. Keep the temperature around 80°F.\n\nA bare bottom makes it much easier to see and remove leftover brine shrimp. If you hatch eggs artificially, wait until the fry are swimming before you remove the methylene blue with water changes."}, {"heading": "Growing out", "text": "Angel fry grow quickly with good feeding. Fins and body shape develop within a few weeks, and they reach about quarter size in roughly 6 to 8 weeks. Most breeders sell them at quarter to half dollar body size, which takes around 2 to 3 months or more. Thin out the fry into more tanks as they grow; crowding stunts them."}, {"heading": "Common mistakes", "text": "- Buying two adults and assuming they are a pair\n- Giving up when a young pair eats its first spawns\n- No fungus control on artificially hatched eggs\n- Feeding fry before they are free swimming\n- Crowding fry in too small a tank"}]$g$::jsonb, $g$[{"q": "How can you tell if an angelfish is male or female?", "a": "It is hard by body shape alone. The surest way is to look at the breeding tubes when they spawn: the female's is broad and blunt, the male's is narrow and pointed."}, {"q": "How long do angelfish eggs take to hatch?", "a": "About 2 to 3 days at 80 to 82°F. The fry then spend around 4 to 5 more days as wigglers before swimming."}, {"q": "Why do my angelfish eat their eggs?", "a": "Young or stressed pairs often eat their first few spawns. Many improve with experience, or you can hatch the eggs yourself."}, {"q": "What do baby angelfish eat?", "a": "Newly hatched brine shrimp is the standard first food, once the fry are free swimming."}]$g$::jsonb, $g$For stage 1, photograph the bonded pair next to their cleaned spawning site with the challenge code card. A photo of the egg rows on the slate makes stage 2 easy to verify.$g$),
  ($g$crystal-red-shrimp$g$, $g$175ae6ce-c87d-4d25-b2ad-77b14bda46bf$g$::uuid, $g$crystal-red-shrimp$g$, null, $g$Breeding Crystal Red Shrimp: Soft Water Colony Guide$g$, $g$Crystal red shrimp breed in soft, acidic water with very stable conditions. Females carry eggs for about a month. A moderate shrimp breeding project.$g$, $g$Crystal red shrimp are the classic Caridina for hobbyists who want a step up from cherry shrimp. In stable, soft, acidic water they breed steadily, and there is no fry stage to worry about, as babies hatch as tiny copies of the adults. The challenge is keeping water parameters steady, because these shrimp are much less forgiving than Neocaridina.$g$, $g${"method": "Egg carrying (female carries eggs; babies hatch fully formed)", "sexing": "Females larger with a deeper, broader abdomen; males smaller and slimmer", "group": "A colony of 10 or more with mixed sexes", "breeding_tank": "10 gallon or larger, active buffering soil, sponge filter, mature with biofilm", "conditioning": "Stable water, varied shrimp foods, leaf litter and biofilm", "trigger": "A female's molt releases scent; males search for her", "spawn": "Commonly 20 to 30 eggs per female", "eggs": "Carried about 30 days at 70 to 74°F", "fry": "Babies hatch as tiny shrimp a couple of millimeters long", "first_foods": "Biofilm, powdered shrimp foods and leaf litter", "grow_out": "About 4 to 5 months to breeding size", "parents": "Adults do not harm babies; remove fish predators"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Start with a 10 gallon or larger tank, an active buffering soil that holds pH low, and a sponge filter so babies cannot be sucked in. Let the tank cycle fully and mature for several weeks so biofilm forms on every surface.\n\nThe site lists 68 to 76°F, pH 5.8 to 6.8 and GH 4 to 6. Most breeders keep crystal reds at about 70 to 74°F. Use RO or rain water remineralized with a GH only shrimp mineral, so KH stays near zero. Total dissolved solids around 100 to 200 are commonly targeted. Stability matters more than any single number."}, {"heading": "Choosing and conditioning a colony", "text": "Females are larger with a deeper, broader abdomen that forms a pouch for eggs. Males are smaller and slimmer. A group of 10 or more shrimp almost always includes both sexes.\n\nFeed small amounts of varied foods: a quality shrimp pellet, powdered biofilm food, blanched vegetables and leaf litter such as dried oak or almond leaves. Remove uneaten food after a few hours. Do small, steady water changes with matched water rather than large ones."}, {"heading": "Mating and berried females", "text": "When a mature female molts, she releases a scent into the water. Males start swimming fast around the tank searching for her, which breeders call the mating dance. Mating happens within hours.\n\nShortly after, the female moves eggs under her tail, where she carries and fans them. A berried female commonly carries about 20 to 30 eggs. The eggs are carried for about 30 days at 70 to 74°F, and you will see them darken and develop eyes as they mature."}, {"heading": "Avoiding dropped eggs", "text": "Stressed females can drop their eggs. The common causes are large water changes, sudden parameter swings, catching or moving berried females, and high temperatures. Keep things calm and stable while females are carrying. Top up evaporation with RO water so TDS does not creep up.\n\nTemperature is a big factor. Crystal reds are sensitive to warm water, and summer heat is a common reason for berried females dropping eggs or colonies crashing. If the room gets warm, a small fan across the surface or a cooler room helps. Check your soil too: active buffering soils lose their effect over time, often after a year or two, and pH slowly rises. When that happens, breeding usually slows down long before shrimp start dying, so a sudden drop in berried females is a useful early warning."}, {"heading": "Raising the babies", "text": "Babies hatch as tiny copies of the adults, only a couple of millimeters long, and immediately start grazing.\n\n- Weeks 1 to 4: biofilm, powdered baby shrimp food, leaf litter\n- Month 2 on: shrimp pellets and the same foods as adults\n\nMature tanks with lots of moss and biofilm raise more babies. Keep the sponge filter clean but not sterile, and avoid strong flow. Do not keep fish in the breeding tank, as almost any fish will eat baby shrimp."}, {"heading": "Growing out", "text": "Crystal red babies grow slowly compared with cherry shrimp. Expect around 4 to 5 months before young females carry their first eggs. Grading out the best colored shrimp for breeding keeps the colony quality high.\n\nOnce the colony grows, move the best shrimp into a separate tank and sell or move on the rest. Keeping lower grade shrimp with your best breeders slowly dilutes color over generations."}, {"heading": "Common mistakes", "text": "- Using tap water with high KH that drives pH up\n- Large or sudden water changes\n- Overfeeding and polluting a small tank\n- Adding shrimp to a tank that has not matured\n- Keeping fish in the shrimp tank, as they eat babies\n- Medications or plant products containing copper"}]$g$::jsonb, $g$[{"q": "How long are crystal red shrimp pregnant?", "a": "Females carry their eggs for about 30 days at 70 to 74°F. Babies then hatch as tiny shrimp."}, {"q": "How do you tell male and female crystal red shrimp apart?", "a": "Females are larger with a deeper, broader abdomen. Males are smaller and slimmer."}, {"q": "Why is my crystal red shrimp dropping eggs?", "a": "Usually stress from big water changes, parameter swings, handling, or high temperature. Keep conditions stable while females carry eggs."}, {"q": "Can crystal red shrimp live in tap water?", "a": "Most hobbyists use RO or rain water remineralized for shrimp, since many tap waters are too hard for them to breed well."}]$g$::jsonb, $g$For stage 2, a clear photo of a berried female with the eggs visible under her tail is ideal. Stage 3 for shrimp means tiny babies seen grazing, so a close photo on moss or glass works well.$g$),
  ($g$rabbit-snail$g$, $g$bda36123-0b63-4ac1-be38-b4024daa1a21$g$::uuid, $g$rabbit-snail$g$, null, $g$How to Breed Rabbit Snails: Slow Livebearers from Sulawesi$g$, $g$Rabbit snails are slow livebearers that release one large egg capsule at a time. Warm, hard water and patience are the keys. A moderate project.$g$, $g$Rabbit snails (Tylomelania) breed slowly but steadily in warm, hard water. Instead of laying clutches of eggs, a female releases a single large white egg capsule every so often, and a fully formed baby snail emerges. Breeding them is mostly about providing the right water and food, then being patient, which suits keepers who enjoy slow, rewarding projects.$g$, $g${"method": "Livebearer (single egg capsule, baby emerges fully formed)", "sexing": "Separate sexes, but very hard to sex by sight; keep a group", "group": "A group of 5 or more to get both sexes", "breeding_tank": "20 gallon or larger, warm, hard water, sand bottom, leaf litter", "conditioning": "Steady feeding of vegetables, sinking pellets and leaf litter", "trigger": "Warm, stable, hard water and good feeding over time", "spawn": "Usually one egg capsule at a time, sometimes a few", "eggs": "Breeders commonly report a new capsule every few weeks; baby emerges soon after", "fry": "Baby is a small, fully formed snail a few millimeters long", "first_foods": "Biofilm, blanched vegetables, crushed sinking pellets", "grow_out": "Many months to reach adult size; growth is slow", "parents": "Adults ignore babies; keep fish that eat small snails out"}$g$::jsonb, $g$[{"heading": "How rabbit snails reproduce", "text": "Rabbit snails have separate sexes, so you need both a male and a female. After mating, the female carries a developing egg inside her body and later releases a single large white egg capsule. A fully formed baby snail emerges from it. Some females release more than one capsule at a time, but one is typical.\n\nBreeders commonly report a new capsule every few weeks from a healthy female. Output is slow compared with most snails, so a colony grows gradually rather than exploding."}, {"heading": "Setting up the breeding tank", "text": "A 20 gallon or larger tank gives a group room to roam. Use a soft sand bottom, plenty of hiding spots, and some leaf litter. A sponge filter or a well covered intake protects babies.\n\nRabbit snails come from warm lakes and rivers on Sulawesi. The site lists 76 to 84°F, pH 7.2 to 8.5 and GH 8 to 20. Most breeders keep them at about 78 to 82°F in hard, alkaline water. Low pH and soft water can damage the shell over time."}, {"heading": "Choosing and conditioning a group", "text": "Telling males from females by looking at the shell is very difficult, and the shell is not a reliable guide. The simple answer is to keep a group of at least five snails, which almost always includes both sexes.\n\nFeed well and steadily. Rabbit snails eat blanched vegetables like zucchini and spinach, sinking pellets and wafers, algae and decaying leaves. A well fed group in warm, stable, hard water is the best trigger for breeding."}, {"heading": "Egg capsules and babies", "text": "Look for a white, round egg capsule on rocks, glass or decor. It is often found near the bottom. A baby snail emerges from it as a tiny, fully formed rabbit snail, a few millimeters long.\n\nThere is nothing you need to do at this stage. Leave the capsule where it is and keep the water stable.\n\nCapsules are easy to overlook in a tank with gravel or lots of decor, which is one reason a sand bottom and a fairly simple layout help. Check the tank regularly with a flashlight. If you find a capsule, note the date so you can time your Society stages. Avoid moving it unless it is somewhere fish could reach it."}, {"heading": "Raising the babies", "text": "Babies graze on biofilm right away. Add a little extra food for them:\n\n- First weeks: biofilm, algae, crushed sinking pellets, blanched vegetables\n- Following months: the same foods as the adults\n\nKeep up regular water changes with matched hard water. Make sure the babies can reach food without competing with large adults; scatter food around the tank."}, {"heading": "Growing out", "text": "Growth is slow. Babies can take many months to reach adult size, and it is common for a colony to take a year or more to build up. Good feeding and warm, stable water give the best growth. Small snails are easy to miss, so check around rocks and in the sand before deciding none survived.\n\nBecause breeding is slow, plan on keeping your colony for the long term rather than expecting quick numbers. Rabbit snails live for several years, and a healthy group will keep adding babies year round in warm water. Avoid moving young snails until they are large enough to handle easily and to be counted in photos."}, {"heading": "Common mistakes", "text": "- Soft, acidic water that erodes shells\n- Water too cool for steady breeding\n- Keeping only one or two snails and hoping for a pair\n- Fish tank mates that eat small snails\n- Copper based medicines or plant products"}]$g$::jsonb, $g$[{"q": "How do rabbit snails reproduce?", "a": "They have separate sexes. After mating, the female releases a single large egg capsule from which a fully formed baby snail emerges."}, {"q": "How often do rabbit snails have babies?", "a": "Breeders commonly report a new egg capsule every few weeks from a healthy female. It is a slow process."}, {"q": "How do you tell male and female rabbit snails apart?", "a": "It is very hard to tell by sight. Keeping a group of five or more is the reliable way to get both sexes."}, {"q": "Do rabbit snails take over a tank?", "a": "No. They breed slowly and do not overrun tanks like some small snails."}]$g$::jsonb, $g$For stage 2, photograph the white egg capsule with something for scale. For stage 3, a clear photo of the newly emerged baby snail is your evidence. Make sure your stage 1 photo shows the whole group with the challenge code card, since you can't show a confirmed pair.$g$),
  ($g$blue-gularis$g$, $g$e68f5750-5484-40ae-bc0c-522dfd7fbecd$g$::uuid, $g$blue-gularis$g$, null, $g$How to Breed Blue Gularis Killifish: Peat and Big Fry$g$, $g$Blue gularis bury eggs in peat that incubate for weeks before hatching into large, hungry fry. Watch male aggression. A moderate killifish project.$g$, $g$The blue gularis is one of the largest and most striking killifish, and breeding it is a satisfying step into bottom spawning killies. Pairs dive into soft peat to lay their eggs, which then need several weeks of incubation before hatching. The fry are large and eat baby brine shrimp from the start, so the real challenges are managing an aggressive male and being patient with the eggs.$g$, $g${"method": "Bottom spawner, semi-annual (eggs laid in peat, long incubation)", "sexing": "Males large and colorful with long fins; females smaller, plain brown with rounded fins", "group": "1 male to 2 or 3 females", "breeding_tank": "20 to 30 gallon, covered, peat layer or bottom mop, sponge filter, hiding spots", "conditioning": "2 to 3 weeks on bloodworms, blackworms, brine shrimp and other meaty foods", "trigger": "A well fed group with a soft peat bottom to spawn into", "spawn": "Eggs laid a few at a time over days; dozens over a couple of weeks", "eggs": "Commonly about 4 to 8 weeks in damp peat at 72 to 77°F; varies with method", "fry": "Hatch large and swim almost right away", "first_foods": "Newly hatched brine shrimp from day one", "grow_out": "Fast; several months to adult color and size", "parents": "No care; adults eat eggs and fry, so collect the peat"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Blue gularis grow to about 4.5 inches, so use a 20 to 30 gallon tank with a tight lid, since killifish jump. Add a sponge filter, plenty of plants or floating cover for the females to hide in, and a spawning medium on the bottom. Most breeders use a layer of boiled, rinsed peat, either across the bottom or in a container the fish can dive into. A bottom spawning mop also works.\n\nThe site lists 72 to 79°F, pH 6 to 7.5 and GH 4 to 15. Many breeders keep them around 72 to 76°F. Slightly soft water helps, but they are not extremely fussy."}, {"heading": "Conditioning and choosing a group", "text": "Males are unmistakable: large, with bright blue, red and yellow colors and long, extended fins. Females are smaller, brownish, with rounded fins and only faint markings.\n\nMales can be rough on females, so use one male with two or three females, and give the females places to hide. Condition for two to three weeks on meaty foods such as bloodworms, blackworms, brine shrimp and chopped earthworms. Many gularis will refuse dry food, so plan on frozen or live food."}, {"heading": "Spawning: what you'll see", "text": "The male displays with fully spread fins and leads a female down to the peat or mop. The pair press together and dive into the substrate, laying and fertilizing eggs inside it. A female lays a few eggs at a time, and spawning goes on daily for as long as she is in condition. Over a couple of weeks you can collect dozens of eggs.\n\nThe eggs are fairly large and clear when fresh. You may see them if you gently sift the peat over a white dish."}, {"heading": "Incubating the eggs", "text": "Collect the peat every one to two weeks. Squeeze out most of the water until it is damp, not dripping, and store it in a labeled, dated bag or container at about 72 to 77°F. Incubation is commonly reported at about 4 to 8 weeks, depending on temperature and method. Some breeders incubate eggs in shallow water instead, which can be faster.\n\nCheck the eggs every couple of weeks. When they are ready you will see the dark eyes of the developing fry inside. Wet the peat with tank water in a small container, and the fry should hatch within a day or so. If only a few hatch, dry the peat again and rewet it a few weeks later."}, {"heading": "Raising the fry", "text": "Blue gularis fry are large for killifish and can eat newly hatched brine shrimp right away.\n\n- Weeks 1 to 2: baby brine shrimp two or three times a day\n- Weeks 3 to 4: baby brine shrimp and chopped blackworms or grindal worms\n- Month 2 on: frozen bloodworms and other meaty foods\n\nKeep fry in a shallow tank at first and change about 20% of the water every two or three days. Siphon uneaten food. Grade fry by size, as bigger siblings will bully or eat smaller ones."}, {"heading": "Growing out", "text": "Fry grow quickly with plenty of food. Males start showing color after a couple of months, and adult size and full fins take several months. Keep grow out tanks covered and separate growing males if they start fighting."}, {"heading": "Common mistakes", "text": "- One male with one female, which can lead to the female being harassed\n- Peat left too wet or allowed to dry out completely\n- Giving up on eggs before they have had enough time\n- No lid; these fish jump\n- Mixing fry of different sizes"}]$g$::jsonb, $g$[{"q": "Is the blue gularis an annual killifish?", "a": "It is usually called semi-annual. Eggs are laid in the substrate and need several weeks of incubation, often in damp peat, before hatching."}, {"q": "How long do blue gularis eggs take to hatch?", "a": "Breeders commonly report about 4 to 8 weeks in damp peat, depending on temperature and method."}, {"q": "How do you tell male and female blue gularis apart?", "a": "Males are larger and brightly colored with long fins. Females are smaller, brown and have rounded fins."}, {"q": "What do blue gularis fry eat?", "a": "They are large enough to eat newly hatched brine shrimp from the first day."}]$g$::jsonb, $g$Date and label every bag of peat. Stage 2 can be a close photo of eggs sifted from the peat, and stage 3 can be logged once fry are swimming, which will be weeks later. Make sure stages 3 to 5 follow the minimum gaps.$g$),
  ($g$clown-killifish$g$, $g$67e96a9c-4a7d-4b3e-9f1b-7b46d6d22c63$g$::uuid, $g$clown-killifish$g$, null, $g$How to Breed Clown Killifish: Floating Plants and Micro Fry$g$, $g$Clown killifish lay a few eggs a day among floating plants. Eggs take one to two weeks to hatch and fry need microfoods. A moderate nano tank project.$g$, $g$Clown killifish, also called rocket panchax, are tiny surface fish that spawn steadily in a planted nano tank. Instead of one big spawn, females lay a few eggs a day in floating plants or mops near the surface. The slow hatch and very small fry make this a patient breeder's fish, but many hobbyists find fry appearing on their own in a well planted species tank.$g$, $g${"method": "Non annual egg depositor (eggs laid in floating plants or top mops)", "sexing": "Males have a colorful red and blue rocket shaped tail; females have clear fins", "group": "1 male to 2 or 3 females, or a small colony", "breeding_tank": "5 to 10 gallon, covered, floating plants or mop, sponge filter", "conditioning": "1 to 2 weeks on baby brine shrimp, daphnia, fruit flies and microworms", "trigger": "Soft, slightly acidic water and good feeding", "spawn": "A few eggs a day over many days", "eggs": "Commonly reported to hatch in about 8 to 14 days at 75 to 77°F", "fry": "Tiny, stay at the surface, swim right after hatching", "first_foods": "Infusoria or paramecium, then vinegar eels, then baby brine shrimp", "grow_out": "About 3 months to adult size", "parents": "No care; adults may eat some fry, so remove eggs or keep dense cover"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank with a tight lid is ideal, because clown killies jump. Add plenty of floating plants with trailing roots, a spawning mop near the surface, and a gentle sponge filter. These fish live at the surface and prefer very little flow.\n\nThe site lists 73 to 79°F, pH 5 to 7 and GH 2 to 8. For breeding, soft, slightly acidic water around pH 6 to 6.5 at 75 to 77°F works well."}, {"heading": "Conditioning and choosing a group", "text": "Males are easy to spot by their bright tail fin, streaked with red and blue in a rocket shape, and colorful dorsal and anal fins. Females have the same dark vertical bands but plain, clear fins.\n\nCondition for one to two weeks with small live and frozen foods: baby brine shrimp, daphnia, microworms and wingless fruit flies. Use one male with two or three females, or a small colony in a heavily planted tank.\n\nA colony tank is the low effort option: a small group in a mature, heavily planted 10 gallon with lots of floating plants will usually produce a trickle of fry that hide at the surface among the roots. Separating eggs gives far more fry, but needs more containers and more food cultures. Either way, start infusoria and vinegar eel cultures before you expect the first hatch."}, {"heading": "Spawning: what you'll see", "text": "The male displays with spread fins next to a female near the surface. The pair settle together into floating plant roots or the mop, and she lays a single egg or a few eggs at a time. This goes on daily rather than in one burst.\n\nEggs are tiny and clear. You can find them by gently checking the mop or plant roots with a flashlight. Each female adds only a few eggs per day, so numbers build up slowly.\n\nIf you pick eggs, a simple routine works well: check the mop every two or three days, move eggs into a small labeled container with the date, and keep each batch separate. That way you know roughly when each batch should hatch and can match the fry to the right food."}, {"heading": "Incubating the eggs", "text": "You can leave eggs in the tank and let some fry survive among the plants, or pick eggs from the mop every few days and move them to a small container with tank water. Commonly reported hatch time is about 8 to 14 days at 75 to 77°F, so be patient.\n\nA small dose of methylene blue or a few dried leaves can limit fungus. Remove white or fuzzy eggs."}, {"heading": "Raising the fry", "text": "Clown killifish fry are very small and stay at the surface. They swim right away and need tiny foods.\n\n- Week 1: infusoria or paramecium several times a day\n- Week 2: vinegar eels and finely powdered food\n- Week 3 on: microworms, then newly hatched brine shrimp\n\nKeep fry in shallow water with floating plants. Change about 10% of the water every couple of days, matching temperature and softness. Because eggs hatch over many days, fry will be different sizes, so separate bigger ones from smaller ones."}, {"heading": "Growing out", "text": "Growth is slow. Expect about 3 months for fry to reach adult size, around 1.25 inches. Males start showing tail color a few weeks before then. Keep grow out tanks covered and well planted.\n\nYoung clown killies are peaceful and do well together in groups. Once they are about half grown they can rejoin the adults in a planted tank. Keep feeding several small meals a day of live or frozen foods, as well fed fry reach breeding size sooner and color up better."}, {"heading": "Common mistakes", "text": "- Strong filter flow that pushes these surface fish around\n- No lid\n- Feeding baby brine shrimp too soon\n- Expecting one large spawn\n- Discarding eggs too early when they can take up to two weeks to hatch"}]$g$::jsonb, $g$[{"q": "How long do clown killifish eggs take to hatch?", "a": "Commonly reported at about 8 to 14 days at 75 to 77°F."}, {"q": "How do you tell male and female clown killifish apart?", "a": "Males have a bright red and blue rocket shaped tail. Females have clear fins with the same black bands."}, {"q": "Do clown killifish eat their fry?", "a": "They may eat some, but many fry survive in dense floating plants. For more fry, move eggs to a separate container."}, {"q": "What do clown killifish fry eat?", "a": "Infusoria or paramecium first, then vinegar eels, and newly hatched brine shrimp after a week or two."}]$g$::jsonb, $g$Because the eggs can take up to two weeks to hatch, don't panic if stage 3 comes much later than stage 2. A photo of eggs on a mop strand against a dark background makes good stage 2 evidence.$g$),
  ($g$rachovii-killifish$g$, $g$e27c026d-5298-4717-9a98-8e03e8947d9c$g$::uuid, $g$rachovii-killifish$g$, null, $g$How to Breed Rachovi Killifish: Peat, Diapause and Hatching$g$, $g$Rachovi killifish are annuals: eggs are stored in damp peat for months, then hatched by wetting. Fast growing fry. A moderate killifish project.$g$, $g$Nothobranchius rachovii is one of the most colorful annual killifish. In the wild they live in seasonal pools that dry out, so their eggs are made to survive months in damp mud. Breeding them means collecting eggs in peat, storing the peat for months and then rewetting it. Once you get the timing right, the fry grow incredibly fast and are a joy to raise.$g$, $g${"method": "Annual killifish (eggs stored in damp peat for months)", "sexing": "Males brilliant blue with red markings and dark tail edges; females plain brown", "group": "1 male to 2 or 3 females", "breeding_tank": "10 gallon, covered, bowl or layer of boiled peat, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, blackworms and brine shrimp", "trigger": "Mature fish and a peat bottom to dive into", "spawn": "Eggs laid a few at a time each day; dozens over a few weeks", "eggs": "Commonly 3 to 6 months in damp peat at room temperature before hatching", "fry": "Hatch within hours of wetting and swim right away", "first_foods": "Newly hatched brine shrimp, with microworms or vinegar eels as backup", "grow_out": "Very fast; adult color in about 6 to 10 weeks", "parents": "No care; collect peat to protect eggs"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank with a tight lid is enough for a male and two or three females. Add a sponge filter and a layer of peat or a container of boiled, rinsed peat for spawning. Use plants or floating cover to give females places to rest from the male.\n\nThe site lists 68 to 76°F, pH 6.5 to 7.5 and GH 4 to 12. Many breeders keep rachovii around 72 to 76°F. Avoid very soft, acidic water, which can increase the risk of velvet."}, {"heading": "Conditioning and choosing a group", "text": "Males are a brilliant mix of blue and red with dark edges on the tail. Females are plain brown and smaller. They mature fast and live only about a year in most aquariums, so breed them while they are young and healthy.\n\nCondition with live and frozen bloodworms, blackworms and brine shrimp. Annual killies rarely accept dry food. Keep one male with two or three females to spread his attention."}, {"heading": "Spawning: what you'll see", "text": "The male displays to a female with spread fins and leads her to the peat. They press together and dive into it side by side, laying and fertilizing an egg or a few at a time. This repeats daily. Over a few weeks you can collect dozens of eggs.\n\nAfter a spawning period, give the females a rest by moving them to a separate tank for a week or two with heavy feeding. This keeps them in good condition and protects them from a persistent male. You can then put them back for another round of spawning."}, {"heading": "Storing the eggs", "text": "Every one to two weeks, remove the peat and squeeze out most of the water until it is damp but not wet. Place it in a labeled, dated bag or container and store it at room temperature, about 70 to 77°F.\n\nIncubation is long. Breeders commonly report about 3 to 6 months for rachovii, depending on temperature and the eggs themselves. Check the eggs every few weeks. When they are ready, you can see the developing fry's dark eyes, often with a gold ring around them. If the peat starts to dry out, mist it lightly."}, {"heading": "Hatching and raising the fry", "text": "To hatch, place the peat in a small container and add an inch or two of cool, soft water, a bit cooler than the tank. Fry usually hatch within hours.\n\n- Days 1 to 3: newly hatched brine shrimp, with microworms or vinegar eels for fry that are too small\n- Weeks 1 to 4: baby brine shrimp several times a day, adding chopped worms\n- Month 2 on: bloodworms, blackworms and other meaty foods\n\nMove the fry out of the peat after a day or so. Keep water shallow at first and change 20% every few days. Re-dry the peat; often more eggs hatch on a second wetting a few weeks later."}, {"heading": "Growing out", "text": "Rachovii grow very fast with heavy feeding. Males often start showing color within a few weeks, and fish can be mature in about 6 to 10 weeks. Because they are short lived, plan new batches of eggs on a regular schedule to keep your line going.\n\nKeep males apart if they fight as they mature, and give females cover. Heavy feeding with small meals several times a day and frequent water changes gives the best growth. A good habit is to always have at least two or three bags of peat incubating at different stages, so a single bad batch never ends your line."}, {"heading": "Common mistakes", "text": "- Storing peat too wet, which rots eggs\n- Letting peat dry out completely\n- Wetting eggs before they are developed\n- Only keeping one generation and losing the line when adults age\n- Starving fry, which slows growth"}]$g$::jsonb, $g$[{"q": "How long do rachovii killifish eggs take to hatch?", "a": "Breeders commonly report about 3 to 6 months in damp peat at room temperature."}, {"q": "How do you hatch Nothobranchius eggs?", "a": "Add cool, soft water to the peat in a small container. Developed eggs usually hatch within hours."}, {"q": "How long do rachovii killifish live?", "a": "Usually about a year in an aquarium, which is why breeders keep eggs in storage."}, {"q": "Can you tell males from females?", "a": "Yes. Males are blue and red with dark tail edges, while females are smaller and plain brown."}]$g$::jsonb, $g$Date every peat bag and photograph the eyed eggs as your stage 2 evidence. With months between spawn and hatch, keep your log notes clear so the stage timings are easy to follow.$g$),
  ($g$turquoise-killifish$g$, $g$2c6de8f1-3e99-47f9-abb0-7b5535c88793$g$::uuid, null, null, $g$How to Breed Turquoise Killifish: Fast Annual Breeding$g$, $g$Turquoise killifish are annuals with eggs stored in damp substrate. Fry grow incredibly fast and can mature in weeks. A moderate killifish project.$g$, $g$Nothobranchius furzeri, the turquoise killifish, is famous for being one of the fastest maturing fish known. In the wild it lives in short lived pools, and in the aquarium its eggs are stored in damp peat or sand before hatching. Its whole life cycle can be completed in a few months, which makes it an exciting fish to breed but means you need to keep eggs in reserve.$g$, $g${"method": "Annual killifish (eggs stored in damp peat or sand)", "sexing": "Males colorful with red or yellow tails; females smaller and plain brown", "group": "1 male to 2 or 3 females", "breeding_tank": "10 to 20 gallon, covered, peat or fine sand container, sponge filter", "conditioning": "1 to 2 weeks on bloodworms, blackworms and brine shrimp", "trigger": "Mature fish and a substrate to spawn in", "spawn": "Eggs laid daily a few at a time; dozens over a few weeks", "eggs": "Incubation varies widely; often weeks to a few months in damp peat or sand", "fry": "Hatch within hours of wetting and swim right away", "first_foods": "Newly hatched brine shrimp from day one", "grow_out": "Extremely fast; mature in as little as 3 to 5 weeks", "parents": "No care; collect the substrate to protect eggs"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank with a tight lid is enough for a male and two or three females. Use a sponge filter and provide a container of boiled peat or fine sand on the bottom for spawning. Plants or floating cover give the females somewhere to rest.\n\nThere is no site care data for this species yet. Turquoise killies are adaptable and commonly kept at about 72 to 79°F in neutral to slightly alkaline water. They do not need very soft water."}, {"heading": "Conditioning and choosing a group", "text": "Males are vivid, with turquoise or blue bodies and either red or yellow tails depending on the strain. Females are smaller and plain brown.\n\nCondition with bloodworms, blackworms and brine shrimp several times a day. Like other annual killies, they rarely accept dry food. Use one male with two or three females so no single female is chased too much.\n\nTurquoise killies are often kept as two strains with red or yellow tails. Keep strains apart if you want to maintain them true, and label your peat bags by strain. Females can be worn down by constant spawning, so rest them in a separate tank for a week or two between rounds with plenty of food."}, {"heading": "Spawning: what you'll see", "text": "The male displays to a female with spread fins and leads her to the substrate. They press together and dive into it, laying an egg or a few at a time. This continues daily. Over a few weeks you can collect dozens of eggs.\n\nThis species is also widely kept in research labs, which is why it is so well known for its fast life cycle. In a home aquarium the basics are the same as for other annual Nothobranchius: a substrate to spawn in, meaty food and a regular routine for collecting and storing eggs."}, {"heading": "Storing the eggs", "text": "Every one to two weeks, collect the peat or sand and squeeze out most of the water. Store it damp in a labeled, dated bag or container at room temperature.\n\nIncubation varies a lot. Some eggs develop in a few weeks, while others pause in a resting stage for months. Breeders often report around 6 weeks to 3 months. Check the eggs regularly; when they are ready you will see the dark eyes of the developing fry."}, {"heading": "Hatching and raising the fry", "text": "To hatch, place the substrate in a container and add an inch or two of cool water. Fry usually hatch within hours.\n\n- Days 1 to 7: newly hatched brine shrimp several times a day\n- Week 2: baby brine shrimp plus chopped blackworms or grindal worms\n- Week 3 on: bloodworms and other meaty foods\n\nMove the fry out of the substrate after a day or so. Keep water shallow at first and change 20% every few days. Re-dry the substrate; more eggs may hatch on a later wetting."}, {"heading": "Growing out", "text": "Turquoise killifish grow incredibly fast. With heavy feeding, they can mature in as little as 3 to 5 weeks. They are also short lived, often only a few months to about a year depending on strain and care. Keep a steady supply of eggs in storage so your line continues.\n\nFeed growing fry several small meals a day and keep up frequent water changes, since heavy feeding fouls water fast. Separate males if they fight as they mature. Many breeders start a new round of spawning as soon as the young fish mature, while also keeping older bags of eggs in storage as a backup."}, {"heading": "Common mistakes", "text": "- Storing substrate too wet or letting it dry out completely\n- Wetting eggs before they are developed\n- Underfeeding the fast growing fry\n- Losing the line because adults aged out and no eggs were saved\n- No lid; they jump"}]$g$::jsonb, $g$[{"q": "How fast do turquoise killifish grow?", "a": "With heavy feeding they can mature in as little as 3 to 5 weeks, among the fastest of any fish."}, {"q": "How long do turquoise killifish eggs take to hatch?", "a": "Incubation varies a lot. Some eggs are ready in weeks, while others rest for months in damp substrate."}, {"q": "How long do turquoise killifish live?", "a": "Often a few months to about a year, depending on the strain and care."}, {"q": "What do turquoise killifish fry eat?", "a": "Newly hatched brine shrimp from the first day."}]$g$::jsonb, $g$Because they grow so fast, turquoise killies can reach the 60 day stage 5 as young adults, so get a clear photo of the colorful young males and plain females with the challenge code card.$g$),
  ($g$celebes-halfbeak$g$, $g$6ad9ec9e-d5b1-48cd-9878-1dafaeb31c25$g$::uuid, null, null, $g$How to Breed Celebes Halfbeaks: Gestation, Fry and Setup$g$, $g$Celebes halfbeaks bear large live fry every 6 to 8 weeks. Learn sexing, a calm breeding setup and how to avoid stillbirths with good nutrition.$g$, $g$Celebes halfbeaks are true livebearers from Sulawesi, and their fry are born big enough to eat baby brine shrimp from day one. The challenge is not getting broods, it is getting healthy ones: stressed or poorly fed females often drop stillborn or premature young. With a calm, well planted tank and plenty of live and frozen food, a small group will produce steady broods.$g$, $g${"method": "Livebearer (internal fertilization)", "sexing": "Males smaller, with red and black fin tips and a modified anal fin; females larger and plainer", "group": "1 male to 2 or 3 females", "breeding_tank": "20 gallons or more, long, tight lid, floating plants and gentle filtration", "conditioning": "Daily live or frozen foods (mosquito larvae, brine shrimp, fruit flies) for 3 to 4 weeks", "trigger": "Mature, well fed fish breed continuously; no special trigger needed", "spawn": "Commonly 10 to 20 fry per brood", "eggs": "Gestation commonly reported as about 6 to 8 weeks at 75 to 79°F", "fry": "Born free swimming, roughly half an inch long, and stay near the surface", "first_foods": "Baby brine shrimp, daphnia, microworms and finely crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks; sexable at around 3 months", "parents": "No care; adults may eat some fry, so use dense floating plants or move fry out"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a long tank of 20 gallons or more with a tight lid, because halfbeaks jump when startled. Keep the temperature around 75 to 79°F with neutral to slightly alkaline, moderately hard water, roughly pH 7 to 8.\n\nThese are surface fish, so open swimming room near the top matters more than depth. Add a mat of floating plants such as water sprite or salvinia at one end for cover and fry refuge, and keep filtration gentle. Bright, sudden light and heavy traffic past the tank make them dash into the glass, so place the tank somewhere quiet."}, {"heading": "Choosing and conditioning a group", "text": "Males are smaller and slimmer, and in most strains show red and black on the fins and the fleshy tip of the lower jaw. Their anal fin is modified for mating, so it looks notched compared with the female's rounded anal fin. Females are larger and plainer.\n\nKeep one male with two or three females; two males in a small tank will spar constantly. Feed live or frozen foods daily for at least three to four weeks before you expect broods: mosquito larvae, brine shrimp, bloodworms and fruit flies are all taken from the surface. Good nutrition is the single biggest factor in healthy broods."}, {"heading": "Pregnancy and birth", "text": "Mating is quick and easy to miss. A pregnant female fills out and becomes deeper bodied over several weeks. Gestation is commonly reported at about 6 to 8 weeks, shorter at the warmer end of the range.\n\nBroods are small for a livebearer, commonly 10 to 20 fry, but the young are large. Many breeders leave the female in a well planted tank rather than a breeding trap, because traps stress halfbeaks and stress is linked to premature and stillborn fry. If you move her, do it early in the pregnancy, not in the final week."}, {"heading": "Raising the fry", "text": "Fry are born free swimming at roughly half an inch and head straight for the surface. Week one: feed baby brine shrimp, microworms and finely crushed flake three or four times a day. Weeks two and three: add chopped daphnia and small frozen foods. From week four, offer the same foods as the adults in smaller sizes, plus fruit flies if you culture them.\n\nKeep fry at 76 to 78°F and change 20 to 30 percent of the water twice a week. They are sensitive to poor water quality, so siphon uneaten food every day."}, {"heading": "Growing out", "text": "With frequent feeding, juveniles reach about an inch in six to eight weeks, and males start to show fin color at around three months. Keep the grow out tank covered and lightly planted at the surface.\n\nAs young males mature, give them plenty of room or the dominant ones will harass the rest. Separating some males into their own tank keeps things calm and gives you clean groups to rehome or sell."}, {"heading": "Keeping broods healthy over time", "text": "A female moved away from the male may still give birth to the brood she is already carrying, so keep watching her for a few weeks after a move. Keep notes of each brood date and size; a sudden drop in size or a run of stillborn fry is a sign the diet or water needs attention.\n\nRest females between broods by keeping the male density low, and keep feeding live food. Older, larger females usually give the biggest and healthiest broods."}, {"heading": "Common mistakes", "text": "- Feeding only dry flake, which is commonly linked to stillborn broods\n- Moving a heavily pregnant female or squeezing her into a small trap\n- Leaving the lid open; halfbeaks jump\n- Keeping two males in a small tank\n- Soft, acidic water; they do best in neutral to slightly hard conditions\n- Expecting large broods; 10 to 20 healthy fry is a good result"}]$g$::jsonb, $g$[{"q": "Are Celebes halfbeaks livebearers?", "a": "Yes. Nomorhamphus are true livebearers: the female carries the young internally and gives birth to free swimming fry."}, {"q": "How long are Celebes halfbeaks pregnant?", "a": "Gestation is commonly reported at about 6 to 8 weeks, depending on temperature and the female's condition."}, {"q": "Why does my halfbeak keep having stillborn fry?", "a": "Stillbirths are most often linked to poor diet and stress. Feed varied live and frozen foods and avoid moving or netting females late in pregnancy."}, {"q": "Do Celebes halfbeaks eat their fry?", "a": "Adults may eat some fry, though the young are large. Thick floating plants or moving fry to a grow out tank keeps losses low."}]$g$::jsonb, $g$Open your log and photograph the male and females with your challenge code card before the first brood; for stage 2, a clear photo of newborn fry counts as evidence. Halfbeak fry grow steadily, so stage 5 at 60 days is very achievable with daily feeding.$g$),
  ($g$rainbow-characodon$g$, $g$21bd4662-a42b-47a1-b31f-1e927490076f$g$::uuid, $g$rainbow-characodon$g$, null, $g$Breeding Rainbow Goodeids (Characodon lateralis): Full Guide$g$, $g$Rainbow goodeids give birth to a few large fry every couple of months. Learn sexing, cool water needs, gestation and how to raise healthy young.$g$, $g$The rainbow goodeid is a small livebearer from the high desert springs of Durango, Mexico, and it is rare in the wild, so every captive brood helps keep it going. Broods are small and fry are born large, so raising them is straightforward once you keep the water cool and clean. The tricky parts are male aggression and patience between broods.$g$, $g${"method": "Livebearer (goodeid, fry nourished internally)", "sexing": "Males redder with a notched anal fin (andropodium); females plainer with a normal anal fin", "group": "1 male to 3 or more females, or a larger colony with cover", "breeding_tank": "20 gallons or more, dense plants, cool hard water", "conditioning": "Varied diet with plenty of vegetable matter plus frozen foods for 3 to 4 weeks", "trigger": "Healthy adults breed through the year; many breeders give a cooler winter rest", "spawn": "Usually 5 to 20 fry per brood", "eggs": "Gestation commonly reported at about 7 to 8 weeks at 68 to 75°F", "fry": "Born large and free swimming; any trophotaeniae remnants drop off within a day or two", "first_foods": "Baby brine shrimp, crushed flake with vegetable content and microworms", "grow_out": "Around 1 inch in 2 to 3 months; mature at about 4 to 6 months", "parents": "No care; adults may eat fry, so give dense cover or move fry out"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon or larger tank works for a small group. Keep the water cool, around 64 to 75°F, with a pH of 7 to 8 and hard water, GH 10 to 20, matching the conditions this species is kept in long term. Most breeders get the best broods at roughly 68 to 75°F.\n\nPlant heavily with fine leaved plants and floating cover. Males are territorial and nippy, so plenty of sight breaks spreads the aggression around. A sponge filter or gentle canister keeps water clean without blasting the fish."}, {"heading": "Choosing and conditioning a group", "text": "Males are smaller, deeper red on the body and fins, and have the notched front section of the anal fin called an andropodium. Females are plainer, olive to silvery, with a normal anal fin and a fuller belly.\n\nKeep one male with three or more females, or a larger colony with lots of cover. This is an omnivore: feed a quality flake with vegetable content, blanched greens or algae, plus frozen brine shrimp and daphnia. Condition for three to four weeks before you start counting on broods."}, {"heading": "Pregnancy and birth", "text": "Goodeids nourish their young inside the female through a placenta like connection, so broods are small and the fry are well developed. Gestation is commonly reported at about 7 to 8 weeks. Expect roughly 5 to 20 fry per brood.\n\nA pregnant female becomes noticeably deeper. Rather than a cramped breeding trap, many keepers move a heavily pregnant female to a planted 5 to 10 gallon tank and return her after the birth. Newborns may show short trailing threads, the remains of the trophotaeniae; these drop off within a day or two."}, {"heading": "Raising the fry", "text": "Fry are large and can eat baby brine shrimp, microworms and finely crushed flake right away. Week one: feed three or four small meals a day. Weeks two to four: add crushed spirulina flake and chopped frozen daphnia so they get plant matter. After a month they eat the same foods as the adults in smaller sizes.\n\nKeep fry at about 70 to 74°F and change 25 percent of the water twice a week. Cool, clean water matters more than warm water for this species."}, {"heading": "Growing out", "text": "Young reach around an inch in two to three months and show their sex at about four to six months. Grow them in a separate tank, because adult males harass smaller fish.\n\nKeep a record of where your line came from. Rainbow goodeids exist as separate wild populations, and responsible breeders keep each population pure rather than mixing them, so the captive stock stays useful for conservation."}, {"heading": "A cool winter rest", "text": "In the wild this fish lives at high altitude where winters are cool. Many breeders let the tank drift down toward the mid 60s°F for six to eight weeks in winter, then warm it back to about 72°F in spring. Breeding often slows during the rest and picks up again afterwards with larger, healthier broods.\n\nThis is not strictly required, and fish kept steady at around 70°F will still breed, but a seasonal rhythm is widely reported to help long term vigor. Reduce feeding a little while the water is cool, and keep up water changes so quality stays high."}, {"heading": "Common mistakes", "text": "- Keeping them too warm; above the mid 70s°F they do poorly over time\n- Soft, acidic water\n- Too few females, so one is chased constantly\n- No plant matter in the diet\n- Mixing different populations or related species\n- Netting pregnant females late in gestation"}]$g$::jsonb, $g$[{"q": "How long are rainbow goodeids pregnant?", "a": "Gestation is commonly reported at about 7 to 8 weeks, and it runs longer in cooler water."}, {"q": "How many fry do rainbow goodeids have?", "a": "Broods are small, usually around 5 to 20 fry, but the young are large and easy to raise."}, {"q": "What are the strings on newborn goodeid fry?", "a": "They are trophotaeniae, structures that fed the fry inside the mother. They fall off on their own within a day or two."}, {"q": "Is the rainbow goodeid endangered?", "a": "It is threatened in the wild, which is why keeping captive lines healthy and unmixed is so valuable."}]$g$::jsonb, $g$Photograph the male and females with your challenge code card when you open the log, then a photo of the newborn fry serves as stage 2. Note the population or source of your fish in the log, since keepers of goodeids value that record.$g$),
  ($g$whitei-goodeid$g$, $g$d0334313-4f79-4c39-ac74-2acb8e468efd$g$::uuid, null, null, $g$How to Breed Ilyodon whitei: Goodeid Livebearer Guide$g$, $g$Ilyodon whitei is a Mexican goodeid that bears well developed live fry. Learn sexing, gestation, brood size and how to raise and grow out the young.$g$, $g$Ilyodon whitei is an active goodeid from western Mexico that gives birth to large, well developed fry. It is less common in the hobby than other livebearers, so a breeding line is genuinely useful to other keepers. Broods are modest and the fry are easy to feed; the real work is giving the adults room, keeping water clean and hard, and protecting the young from hungry parents.$g$, $g${"method": "Livebearer (goodeid, fry nourished internally)", "sexing": "Males slimmer and more colorful with a notched anal fin (andropodium); females fuller", "group": "1 male to 3 or more females", "breeding_tank": "30 gallons or more, open swimming room, plants and rock cover", "conditioning": "Flake with vegetable content, algae and frozen foods for 3 to 4 weeks", "trigger": "Healthy, well fed adults breed through the year", "spawn": "Breeders report roughly 10 to 30 fry per brood, more from large females", "eggs": "Gestation commonly reported at about 7 to 8 weeks at 72 to 77°F", "fry": "Born large and free swimming; trophotaeniae remnants drop off within days", "first_foods": "Baby brine shrimp and crushed flake with spirulina", "grow_out": "About 1 inch in 2 to 3 months; mature at around 6 months", "parents": "No care; adults eat fry, so move the female or fry out"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Ilyodon are active swimmers that grow to roughly 3 inches, so a 30 gallon or larger tank suits a group. Breeders keep them at about 72 to 77°F in hard, alkaline water, pH 7 to 8. Give a good current and strong filtration, since many populations come from flowing water, and keep nitrate low with regular changes.\n\nAdd rock piles and a few hardy plants for cover, but leave open swimming space. A tight lid is wise."}, {"heading": "Choosing and conditioning a group", "text": "As in other goodeids, males have the notched front section of the anal fin called an andropodium, and they are usually slimmer and more colorful in the fins. Females are fuller bodied with a normal anal fin.\n\nKeep one male with three or more females so no single female gets all the attention. These fish graze, so feed a flake with vegetable content, algae wafers or blanched greens, and frozen brine shrimp, daphnia or bloodworms several times a week. Condition for three to four weeks."}, {"heading": "Pregnancy and birth", "text": "Goodeid young are nourished inside the mother through ribbon like structures called trophotaeniae, so the fry are born large and well formed. Gestation is commonly reported at about 7 to 8 weeks. Breeders report broods of roughly 10 to 30, with larger females producing more.\n\nWhen a female looks heavy and square in front of the anal fin, move her to a planted 10 gallon tank with matched water, or simply leave dense cover in the main tank. Avoid small plastic traps, which stress goodeids."}, {"heading": "Raising the fry", "text": "Newborns may trail short threads, which are the trophotaeniae remnants; they drop off on their own. Week one: feed baby brine shrimp and crushed spirulina flake three or four times a day. Weeks two to four: add chopped frozen daphnia and brine shrimp. After a month, feed small adult foods.\n\nKeep fry at 74 to 76°F and change 25 percent of the water twice a week. They grow best with frequent small meals and clean, hard water."}, {"heading": "Growing out", "text": "Juveniles reach about an inch in two to three months and begin to show their sex at around four to six months. A separate grow out tank of 20 gallons or more keeps them safe from adults and lets you feed heavily.\n\nIlyodon species are known to hybridize, so never house different Ilyodon together, and keep records of your line's origin. Pure, labelled stock is what other goodeid keepers want.\n\nFeed grow out fish three or four small meals a day and change 30 percent of the water twice a week. Sort out the largest males if they start chasing their siblings hard."}, {"heading": "Water quality and feeding through the year", "text": "Goodeids from flowing water dislike stale conditions. Change 30 to 40 percent of the water weekly in the adult tank, and match temperature and hardness when you do. Rising nitrate tends to show first as fewer, smaller broods.\n\nAlgae on rocks and glass is useful grazing for this species, so do not scrub every surface clean. Keep a steady rhythm of one vegetable meal and one protein meal a day for adults, and slightly increase protein for pregnant females. Breeding generally continues year round when conditions are stable, with the best broods from well grown females."}, {"heading": "Common mistakes", "text": "- Housing different Ilyodon species together\n- Soft or acidic water\n- Weak filtration and high nitrate\n- One female with an eager male\n- Leaving fry in with hungry adults and no cover\n- Moving heavily pregnant females into small traps"}]$g$::jsonb, $g$[{"q": "How long is Ilyodon whitei pregnant?", "a": "Gestation is commonly reported at about 7 to 8 weeks, depending on temperature."}, {"q": "How do you tell male from female Ilyodon whitei?", "a": "Males have a notched anal fin, the andropodium, and are usually slimmer and more colorful. Females have a normal anal fin and fuller body."}, {"q": "Do goodeids eat their fry?", "a": "Yes, adults often eat newborns. Thick cover or moving the female to give birth protects the brood."}, {"q": "Can I keep Ilyodon whitei with other Ilyodon?", "a": "It is best not to, because Ilyodon species can hybridize. Keep each species and population on its own."}]$g$::jsonb, $g$Show the male, females and your challenge code card in the stage 1 photo before any brood arrives. A photo of the newborn fry, threads and all, makes clear stage 2 evidence.$g$),
  ($g$wrestling-halfbeak$g$, $g$2d89b543-c688-49dd-9aa6-faf5d295cdd9$g$::uuid, $g$wrestling-halfbeak$g$, null, $g$How to Breed Wrestling Halfbeaks: Gestation and Fry Care$g$, $g$Wrestling halfbeaks bear live fry every few weeks but stillbirths are common. Learn sexing, diet and setup for healthy broods and how to raise fry.$g$, $g$Wrestling halfbeaks are small surface livebearers from Southeast Asia, named for the jaw wrestling males use to settle disputes. They breed readily, but stressed or poorly fed females often lose broods to stillbirth, so success comes down to diet and calm. Get those right and you will see regular broods of small, surface hugging fry that take live food from birth.$g$, $g${"method": "Livebearer (internal fertilization)", "sexing": "Males smaller with a modified anal fin and often a red or yellow fin spot; females larger", "group": "1 male to 3 or 4 females", "breeding_tank": "20 gallons or more, long, tight lid, floating plants", "conditioning": "Daily live or frozen foods (fruit flies, mosquito larvae, brine shrimp) for 3 to 4 weeks", "trigger": "Well fed adults breed continuously", "spawn": "Commonly 10 to 30 fry per brood", "eggs": "Gestation commonly reported at about 4 to 8 weeks, shorter at 78 to 80°F", "fry": "Born free swimming, about 0.4 inch, and stay right at the surface", "first_foods": "Baby brine shrimp, microworms, crushed flake and tiny fruit flies", "grow_out": "About 1 inch in 2 months; mature at 3 to 4 months", "parents": "No care; adults eat fry, so give dense floating plants or move fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A long 20 gallon tank gives these surface swimmers the room they need. Keep the temperature at 72 to 82°F, with breeders often aiming for 76 to 80°F, and pH 6.5 to 8 with moderate hardness. Fit a tight lid, because halfbeaks jump when frightened.\n\nCover part of the surface with floating plants such as salvinia, frogbit or water sprite. This gives females a place to rest and newborns somewhere to hide. Keep the current gentle, as these fish are weak swimmers against strong flow."}, {"heading": "Choosing and conditioning a group", "text": "Males are smaller and slimmer, with an anal fin modified for mating, and in many strains a red, orange or yellow patch on the dorsal fin. Females are larger and deeper bodied with a normal anal fin.\n\nUse one male with three or four females. Males lock jaws and wrestle, which rarely causes serious harm, but a beak can be damaged if two males fight in a cramped tank. Feed small live or frozen foods every day: fruit flies, mosquito larvae, daphnia and brine shrimp. Poor diet is the main cause of stillborn broods."}, {"heading": "Pregnancy and birth", "text": "A pregnant female grows deeper behind the head and develops a dark area near the vent. Gestation is commonly reported at about 4 to 8 weeks, with shorter times in warmer water. Broods are commonly 10 to 30 fry.\n\nHalfbeaks are easily stressed, and stress is linked to premature birth. Rather than netting females into small traps, many breeders leave them in a heavily planted tank and collect fry from the surface each morning, or move a female into a planted nursery tank early in the pregnancy."}, {"heading": "Raising the fry", "text": "Fry are born at about 0.4 inch, free swimming, and stay at the very top of the water. They feed from the surface, so choose foods that float or drift slowly. Week one: baby brine shrimp, microworms and finely crushed flake three or four times a day. Weeks two and three: add flightless fruit flies and chopped daphnia. From week four, feed small adult foods.\n\nKeep fry at 76 to 80°F and change 20 to 30 percent of the water twice a week, siphoning leftovers daily."}, {"heading": "Growing out", "text": "Young reach about an inch in two months and males begin to show fin color and their modified anal fin at around three months. Keep grow out tanks covered and with floating plants.\n\nOnce young males mature, thin them out or give them their own tank so wrestling stays harmless. Breeders often keep several females per male in grow out groups they plan to sell.\n\nFruit fly cultures are a big help at this stage. Young halfbeaks grow noticeably faster on live insects than on flake alone."}, {"heading": "Water quality and stress control", "text": "Halfbeaks react badly to sudden changes, so make water changes moderate, around 20 to 25 percent weekly, and match the temperature closely. Many keepers find their broods improve once the tank is in a low traffic spot with dim, stable lighting and a dark background.\n\nKeep tankmates small and peaceful, or better, give the breeding group a tank of its own. Fast surface feeders will outcompete halfbeaks for food, which leaves females underfed during pregnancy. If you see females pacing the glass or hiding constantly, reduce the number of males first."}, {"heading": "Common mistakes", "text": "- Feeding only dry flake, a common cause of stillborn broods\n- Leaving the tank uncovered\n- Overcrowding males together\n- Netting late term females into small traps\n- Strong current that pushes fry down from the surface\n- Feeding foods that sink straight past the fry"}]$g$::jsonb, $g$[{"q": "How long are wrestling halfbeaks pregnant?", "a": "Gestation is commonly reported at about 4 to 8 weeks, depending on temperature and the female's condition."}, {"q": "Why are my halfbeak fry born dead?", "a": "Stillbirths are common in this species and are mostly linked to poor nutrition and stress. Varied live and frozen food and a calm tank help most."}, {"q": "Do wrestling halfbeaks eat their babies?", "a": "Yes, adults will eat fry. Floating plants and daily removal of newborns keep losses low."}, {"q": "Is the wrestling halfbeak a livebearer?", "a": "Yes. Dermogenys pusilla gives birth to live, free swimming fry."}]$g$::jsonb, $g$Photograph the male and females with your challenge code card before the first brood, and log the date you first spot fry for stage 2. Fry stay at the surface, which makes them easy to photograph for the later stages.$g$),
  ($g$apistogramma-agassizii$g$, $g$cf675af0-ad2c-452b-9024-9a105510725d$g$::uuid, $g$apistogramma-agassizii$g$, null, $g$How to Breed Apistogramma agassizii: Caves, Water and Fry$g$, $g$Agassiz's dwarf cichlids spawn in caves in soft, acidic water and the female guards the fry. Learn setup, sexing, egg care and how to raise the young.$g$, $g$Apistogramma agassizii is one of the classic dwarf cichlids, and watching a bright yellow female herd a cloud of fry around the tank is a highlight of the hobby. Spawning is not hard once the water is soft and acidic, but young females often eat early clutches and the fry need tiny live foods. Patience and clean water are the keys.$g$, $g${"method": "Cave spawner (female guards eggs and fry)", "sexing": "Males larger with long fins and a spade shaped tail; females smaller, turn yellow when breeding", "group": "One pair, or 1 male to 2 or 3 females with a cave each", "breeding_tank": "20 gallons, soft acidic water, caves, leaf litter and plants", "conditioning": "Live and frozen foods (brine shrimp, daphnia, bloodworms) for 2 to 3 weeks", "trigger": "Soft acidic water, warm 80 to 82°F, water changes with soft water", "spawn": "Commonly 50 to 150 eggs on the cave ceiling", "eggs": "Hatch in about 2 to 3 days at 80 to 82°F", "fry": "Free swimming about 7 to 9 days after spawning, herded by the female", "first_foods": "Baby brine shrimp, microworms and vinegar eels", "grow_out": "About 0.75 inch in 6 to 8 weeks; sexable at 3 to 4 months", "parents": "Female guards well; young females may eat early clutches, so be patient"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank is ideal for a pair or a male with two females. Use soft, acidic water: pH 5 to 6.5 and GH 1 to 10, with the lower end of both helping egg survival. Keep the temperature at 80 to 82°F for spawning, within the usual 78 to 84°F range.\n\nProvide a small cave for each female, such as a coconut shell or clay cave with an entrance just big enough for her. Add leaf litter, a sand bottom and some plants. A sponge filter is best because it will not suck up fry."}, {"heading": "Choosing and conditioning a pair", "text": "Males are clearly larger, up to about 3 inches, with long, pointed dorsal fin rays and a spade or lyre shaped tail with color. Females stay smaller, around 2 inches, with rounder fins, and turn bright yellow with black markings when ready to breed.\n\nStart with a pair, or one male with two or three females if the tank allows separate territories. Condition for two to three weeks with live and frozen foods: baby and adult brine shrimp, daphnia, bloodworms and mosquito larvae. Keep up regular water changes with soft water."}, {"heading": "Spawning: what you'll see", "text": "The female turns bright yellow and starts guarding her cave, chasing other fish away. The male displays with spread fins. She then lays eggs on the cave ceiling, commonly 50 to 150, and the male fertilizes them.\n\nAfter spawning she usually drives the male away from the cave. In a small tank this can get rough, so watch that he has places to hide. You may only see the female hovering at the cave entrance; that is a good sign."}, {"heading": "Eggs and hatching", "text": "The eggs are small and reddish. At 80 to 82°F they hatch in about 2 to 3 days, and the wrigglers stay in the cave for several more days while they use up their yolk.\n\nThe female fans and cleans the eggs and removes any that fungus. Very hard or alkaline water is a common reason eggs fail, so keep the water soft. Do not shine lights into the cave or move it; disturbing her is the main reason young females eat their eggs."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 7 to 9 days after spawning and follow the female around the tank. Week one: feed newly hatched baby brine shrimp, microworms and vinegar eels two or three times a day. Weeks two and three: keep up baby brine shrimp and add finely crushed flake. From week four, add chopped frozen foods.\n\nChange 10 to 20 percent of the water every two or three days with matched soft water, and keep the temperature steady at 78 to 82°F. Fry are sensitive to sudden changes."}, {"heading": "Growing out", "text": "Fry reach about three quarters of an inch in six to eight weeks and can be sexed at three to four months. The female will tolerate them for several weeks, but move them to a grow out tank by around a month so she can rest and spawn again.\n\nWater temperature is widely reported to affect the sex ratio in Apistogramma, with very warm water producing mostly males. Many breeders raise fry around 79 to 81°F for a more even mix."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water, which leads to eggs failing to hatch\n- Too many females with too few caves\n- Disturbing the cave in the first days\n- Feeding fry only powdered flake\n- Large water changes with water of a different pH\n- Giving up after the first clutch is eaten; young pairs often improve"}]$g$::jsonb, $g$[{"q": "How do you tell male and female Apistogramma agassizii apart?", "a": "Males are larger with long dorsal fin points and a spade shaped tail. Females are smaller and turn bright yellow with black markings when breeding."}, {"q": "How long do Apistogramma agassizii eggs take to hatch?", "a": "About 2 to 3 days at 80 to 82°F, with fry free swimming roughly a week to 9 days after spawning."}, {"q": "Why does my female Apisto eat her eggs?", "a": "It is common with young or disturbed females. Keep the cave dark and undisturbed, and most improve after a few attempts."}, {"q": "Does temperature affect Apistogramma fry sex?", "a": "Yes, it is widely reported that very warm water skews broods toward males, so many breeders raise fry around 79 to 81°F."}]$g$::jsonb, $g$Open your log with a photo of the pair or trio and your challenge code card, since the female often hides once she spawns. A shot of her herding free swimming fry is perfect for stage 3.$g$),
  ($g$festivum$g$, $g$f4168693-71eb-4353-80ef-e9229e0d8e16$g$::uuid, $g$festivum$g$, null, $g$How to Breed Festivum Cichlids: Pairs, Eggs and Fry Guide$g$, $g$Festivums spawn on leaves or slate and both parents guard the fry, but sexing is tricky. Learn how to pair them, protect eggs and raise healthy young.$g$, $g$Festivums, also called flag cichlids, are calm, graceful cichlids that lay eggs on broad leaves or upright surfaces. A bonded pair is a pleasure to watch, but getting there takes patience: the sexes look almost identical, and new pairs often eat their first clutches. Once a pair settles, they guard their fry well and the young are easy to feed.$g$, $g${"method": "Substrate spawner (on leaves or upright surfaces)", "sexing": "Very hard; males may be slightly larger with longer fins; venting at spawning is surest", "group": "One pair, ideally formed from a group of 6 juveniles", "breeding_tank": "40 gallons or more, tall, broad leaf plants or slate, calm tankmates", "conditioning": "Varied flake plus frozen brine shrimp, mysis and bloodworms for 2 to 3 weeks", "trigger": "Soft slightly acidic water, about 80°F, and a large water change", "spawn": "Commonly 200 to 500 eggs", "eggs": "Hatch in about 2 to 3 days at around 80°F", "fry": "Free swimming about 4 to 5 days after hatching", "first_foods": "Baby brine shrimp, microworms and crushed flake", "grow_out": "About 1 inch in 8 weeks; growth is slow after that", "parents": "Both parents guard; new pairs often eat eggs, so allow several tries"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Festivums are tall bodied fish, so use a tank of 40 gallons or more with good height. Keep the water at 72 to 82°F, with about 80°F for spawning, and pH 6 to 7.5 with soft to moderate hardness; many breeders spawn them at pH 6 to 6.5.\n\nGive them broad leaved plants such as Amazon swords, or a slate leaned against the glass. They prefer upright or angled surfaces. Keep tankmates small and peaceful, because festivums are shy and will not spawn if bullied.\n\nSmall tetras make good dither fish: their calm schooling tells the pair the tank is safe. Avoid barbs and other fin nippers, which festivums cannot handle. Lighting should be moderate, with floating plants to soften it."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing adults by eye is unreliable. Males may be a little larger with slightly longer fins, but this varies. The surest way is to see the breeding tubes at spawning: the female's is broad and blunt, the male's thin and pointed.\n\nBuy six juveniles and let a pair form naturally; paired fish stay together and defend a spot. Condition them for two to three weeks on quality flake or pellets plus frozen brine shrimp, mysis and bloodworms."}, {"heading": "Spawning: what you'll see", "text": "The pair cleans a leaf or slate, often one that is upright or steeply angled. Their colors darken and they shake and tail slap at each other. The female then lays rows of eggs, commonly 200 to 500, with the male following to fertilize.\n\nA large water change with slightly cooler, softer water often triggers a spawn in a conditioned pair. Keep the tank quiet afterwards.\n\nSpawns often come every few weeks once a pair settles in, especially with regular water changes."}, {"heading": "Eggs and hatching", "text": "Both parents fan the eggs and pick off any that turn white with fungus. At around 80°F the eggs hatch in about 2 to 3 days. The parents usually move the wrigglers to a pit or another leaf.\n\nNew pairs often eat their first few clutches. Give them time rather than removing eggs straight away. If a pair keeps eating eggs, some breeders hatch the leaf in a separate tank with an air stone and a drop of methylene blue, but parent raised fry usually do better with this species."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 4 to 5 days after hatching. Week one: feed baby brine shrimp and microworms three times a day. Weeks two and three: keep up baby brine shrimp and add crushed flake. From week four, add small frozen foods.\n\nKeep the temperature around 78 to 80°F and change 15 to 20 percent of the water every two or three days with matched water. The parents guard the school, so avoid putting a net near them."}, {"heading": "Growing out", "text": "Festivum fry grow slowly compared with many cichlids, reaching about an inch in eight weeks and a few inches in four to six months. Move them to their own tank once they are about half an inch, or when the parents start preparing to spawn again.\n\nFeed little and often and keep water clean. Grow out groups are peaceful, so a large group can share a tank without much fighting."}, {"heading": "Common mistakes", "text": "- Guessing the sex of two adults and expecting a pair\n- Busy, aggressive tankmates that stop them spawning\n- Removing eggs too early instead of letting a pair learn\n- No upright surfaces or broad leaves for spawning\n- Hard, alkaline water for egg hatching\n- Netting near the fry and scattering the school"}]$g$::jsonb, $g$[{"q": "How can you tell a male festivum from a female?", "a": "It is very difficult by looks alone. Watching the breeding tubes at spawning is the only reliable method."}, {"q": "How many eggs does a festivum lay?", "a": "Commonly about 200 to 500 eggs per spawn, on a leaf or upright surface."}, {"q": "Why do my festivums eat their eggs?", "a": "New pairs often eat early clutches, especially if disturbed. Most improve after a few spawns in a calm tank."}, {"q": "Are festivums good parents?", "a": "Yes. Once settled, both parents guard the eggs and fry together."}]$g$::jsonb, $g$Pick your pair from a group and photograph the two with your challenge code card before they spawn; a clear shot of the egg covered leaf is ideal stage 2 evidence. Festivum fry grow slowly, so plan feeding well ahead for the stage 5 photo.$g$),
  ($g$green-terror$g$, $g$05dac08a-791c-46db-bc6c-07328f1134dc$g$::uuid, $g$green-terror$g$, null, $g$How to Breed Green Terrors: Pairing, Spawning and Fry Care$g$, $g$Green terrors spawn on flat stones and guard big broods, but pairs can turn violent. Learn safe pairing, spawning setup and how to raise hundreds of fry.$g$, $g$Green terrors are striking, intelligent cichlids that make devoted parents once a pair has formed. They breed readily in a big enough tank, laying hundreds of eggs on a flat stone, and the fry are easy to raise. The real challenge is safety: males can injure or kill an unready female, so careful pairing and plenty of space are essential.$g$, $g${"method": "Substrate spawner (open, on flat stones)", "sexing": "Males larger with a big nuchal hump; fin edging varies; venting at spawning is surest", "group": "One bonded pair", "breeding_tank": "75 gallons or more for a pair, flat stones, caves and sight breaks", "conditioning": "Pellets plus frozen krill, mysis and earthworms for 3 to 4 weeks", "trigger": "Warming to the top of the range, about 77°F, plus a large water change", "spawn": "Commonly 300 to 600 eggs", "eggs": "Hatch in about 3 to 4 days at around 77°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks; 2 inches by about 3 months", "parents": "Both parents guard closely; watch the male for aggression toward the female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Give a pair at least 75 gallons, more if possible, even though a single fish can live in 55 gallons. Keep the water at 70 to 77°F, pH 6.5 to 8 and GH 5 to 20. For spawning, many breeders run the tank at the upper end, around 76 to 77°F.\n\nAdd several flat stones or slates on sand, plus caves and tall decor to break lines of sight so the female has places to escape. Strong filtration is a must, because these are messy, heavy eaters."}, {"heading": "Choosing and conditioning a pair", "text": "Adult males are noticeably larger and develop a pronounced nuchal hump. Fin edging, orange in some lines and whitish in others, is usually brighter in males, but it is not a reliable test on its own. Venting at spawning is the only certain check.\n\nThe safest way to get a pair is to grow up five or six juveniles and let two pair off, then rehome the rest. If you introduce an adult pair, use a tank divider until the female shows interest. Condition for three to four weeks with quality pellets and frozen krill, mysis and earthworms."}, {"heading": "Spawning: what you'll see", "text": "A ready pair darkens, cleans a flat stone and digs pits in the sand. You will see lip locking, tail slapping and shaking. The female lays rows of eggs, commonly 300 to 600, and the male fertilizes them.\n\nIf the male keeps chasing the female hard before she is ready, put in a divider at once. Some breeders use a divider with a gap only the smaller female can pass, so she can escape him.\n\nAfter spawning both parents guard the area fiercely and will attack a hand in the tank, so do maintenance carefully. Remove any other tankmates before the fry are free swimming, or they will be harassed."}, {"heading": "Eggs and hatching", "text": "Both parents fan the eggs and remove any that turn white. At around 77°F the eggs hatch in about 3 to 4 days, and the parents move the wrigglers into pits in the sand. Cooler water slows hatching.\n\nIf a pair keeps eating eggs, give them several chances first. As a backup, a stone of eggs can be hatched in a separate tank with matched water, gentle air near the eggs and a little methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "Fry are free swimming about 4 to 6 days after hatching. Week one: feed newly hatched baby brine shrimp three or four times a day. Weeks two and three: add finely crushed flake and micro pellets. From week four, add chopped frozen foods.\n\nWith hundreds of fry eating heavily, change 30 percent of the water two or three times a week. Keep temperature steady at 75 to 77°F."}, {"heading": "Growing out", "text": "Fry reach about an inch in six to eight weeks and around 2 inches by three months. Move them to grow out tanks by about three to four weeks, before the parents turn on them or start a new spawn.\n\nAs they grow, aggression rises, so sort by size and give plenty of space. Plan ahead for numbers: a single spawn can fill several tanks, and you need homes for them.\n\nFeed juveniles three or four times a day and keep up big water changes. Green terrors grow fast on a good diet but stunt in dirty water."}, {"heading": "Common mistakes", "text": "- Putting two adults together with no divider\n- A tank too small for a pair\n- No hiding places for the female\n- Weak filtration for heavy feeders\n- Leaving fry with the parents too long\n- Raising more fry than you can house or rehome"}]$g$::jsonb, $g$[{"q": "How do I know if my green terror is male or female?", "a": "Adult males are larger with a strong forehead hump. Fin edging helps but is not reliable, and venting at spawning is the only sure check."}, {"q": "How many eggs do green terrors lay?", "a": "Commonly around 300 to 600 eggs per spawn on a flat stone."}, {"q": "Will a male green terror kill the female?", "a": "It can happen with unready or mismatched fish. Pair from a group, give sight breaks and use a divider if he gets rough."}, {"q": "How long do green terror eggs take to hatch?", "a": "Around 3 to 4 days at about 77°F, with fry swimming about 4 to 6 days later."}]$g$::jsonb, $g$Photograph your bonded pair with the challenge code card before the first spawn, then the egg covered stone for stage 2. Moving fry out by about a month keeps them safe through the 30 and 60 day stages.$g$),
  ($g$gymnogeophagus-balzanii$g$, $g$fadb326a-c605-4eac-98e7-aa3f6cf8e2d7$g$::uuid, null, null, $g$How to Breed Gymnogeophagus balzanii: Mouthbrooding Guide$g$, $g$Gymnogeophagus balzanii lays eggs on a stone, then mouthbroods the larvae. Learn seasonal cooling, sexing, holding times and how to raise the fry.$g$, $g$Gymnogeophagus balzanii is a subtropical eartheater from the Paraguay and Paraná basins with an unusual breeding style: eggs are laid on a stone and the larvae are later carried in the mouth. Males with their tall forehead humps are spectacular. Breeding is very achievable, but these fish need a cooler winter rest to stay healthy and spawn well.$g$, $g${"method": "Delayed (larvophile) mouthbrooder: eggs on a stone, larvae carried in mouth", "sexing": "Males larger with a tall forehead hump and long fins; females smaller and plainer", "group": "1 male to 2 or 3 females, or one pair", "breeding_tank": "55 gallons or more, soft sand, flat stones, open space", "conditioning": "Frozen bloodworms, brine shrimp and quality sinking foods for 3 to 4 weeks", "trigger": "Warming to about 77 to 80°F after a cooler winter rest", "spawn": "Breeders report from about 100 to a few hundred eggs", "eggs": "Picked up as hatching larvae after about 1 to 2 days at 77 to 80°F", "fry": "Released free swimming roughly 1 to 2 weeks after spawning; taken back at night or danger", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 8 weeks", "parents": "Female broods (males sometimes share) and both guard; parents rarely eat fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 55 gallon tank or larger suits a trio. Use fine sand, because these eartheaters sift it constantly, and add a few smooth flat stones. Keep decor simple with some cover around the edges and open sand in the middle.\n\nFor spawning, keep the water around 77 to 80°F, pH about 6.5 to 7.5 and soft to moderately hard. They are sensitive to poor water, so use good filtration and change a good share of water every week."}, {"heading": "Seasonal cooling", "text": "This species comes from subtropical waters that cool in winter. Breeders widely report that fish kept warm all year age quickly and spawn poorly. Give them a rest of roughly two to three months at about 64 to 70°F, feeding lightly.\n\nWhen you raise the temperature back to 77 to 80°F in spring and increase feeding and water changes, spawning usually follows within a few weeks."}, {"heading": "Choosing and conditioning a group", "text": "Adult males are larger, with a tall forehead hump, long trailing fins and bright blue spangling. Females are smaller and plainer and lack the hump. Juveniles are hard to sex, so start with six young fish if you can.\n\nKeep one male with two or three females, or a single pair in a smaller setup. Condition for three to four weeks on frozen bloodworms, brine shrimp and mysis, plus a quality sinking pellet."}, {"heading": "Spawning and mouthbrooding", "text": "The pair cleans a flat stone and the female lays eggs on it, with breeders reporting anywhere from about 100 to a few hundred. Both fish guard the stone. Around hatching, roughly 1 to 2 days after spawning, the female picks them up in her mouth; some breeders report the male taking a share too.\n\nThe parents carry the larvae until they can swim, roughly one to two weeks after spawning. A holding fish has a full throat and eats little or nothing.\n\nDo not net or chase a holding fish. Frightened brooders may spit or swallow the young. Keep tankmates calm and few, and keep the lights steady."}, {"heading": "Raising the fry", "text": "Once released, fry stay close to the parents and dart back into a mouth at night or when frightened. Week one: feed baby brine shrimp two or three times a day. Weeks two and three: add crushed flake and micro pellets. From week four, add chopped frozen foods.\n\nKeep fry at 76 to 78°F and change 20 percent of the water every two or three days. The parents are good guardians, so many breeders leave fry with them for the first few weeks.\n\nFry sift sand early, just like their parents, so a little food reaching the bottom is eaten too. Siphon leftovers daily, because uneaten food in sand fouls water quickly."}, {"heading": "Growing out", "text": "Fry reach about an inch in eight weeks. Move them to their own tank by about four to six weeks, before the parents spawn again. Grow them on sand with frequent feeding and clean water.\n\nYoung fish should also get a winter cool down once they are past a few months old, matching the adults. This keeps your line healthy.\n\nKeep the grow out tank bare of rough gravel and feed three or four small meals a day. Males begin to show a hint of the forehead hump at a few months old, which makes picking out future breeders easier."}, {"heading": "Common mistakes", "text": "- Keeping the tank warm all year\n- Gravel instead of sand\n- Netting a holding fish and making it spit\n- Poor water quality\n- Confusing it with the immediate mouthbrooding Geophagus, which pick up eggs right away"}]$g$::jsonb, $g$[{"q": "Is Gymnogeophagus balzanii a mouthbrooder?", "a": "Yes, a delayed one. Eggs are laid on a stone and the larvae are picked up and carried in the mouth around hatching."}, {"q": "Do Gymnogeophagus need a winter cool down?", "a": "Breeders widely recommend a cooler rest of a couple of months at about 64 to 70°F for long term health and better spawning."}, {"q": "How do you sex Gymnogeophagus balzanii?", "a": "Adult males are larger with a tall forehead hump and long fins. Females are smaller and lack the hump."}, {"q": "How long do balzanii carry their young?", "a": "Breeders report fry are released about one to two weeks after spawning and are taken back into the mouth for a while afterwards."}]$g$::jsonb, $g$Photograph the male and females with your challenge code card before spawning; for stage 2, the egg covered stone or a holding fish with a full throat works well. Note the dates of your winter rest in the log too.$g$),
  ($g$macmasters-dwarf-cichlid$g$, $g$8c4197b5-9e1b-4256-93d9-ff39c36746ba$g$::uuid, $g$macmasters-dwarf-cichlid$g$, null, $g$How to Breed Apistogramma macmasteri: Harem Setup and Fry$g$, $g$Macmaster's dwarf cichlids are harem cave spawners in soft, acidic water. Learn sexing, cave setup, egg timing and how to raise the fry to grow out.$g$, $g$Macmaster's dwarf cichlid is a colorful, bold Apistogramma that is often kept as a harem, one male with several females each guarding a cave. Spawning is fairly easy in soft, acidic water, and the females make dedicated mothers. The work is in keeping water stable and giving the tiny fry enough live food in their first weeks.$g$, $g${"method": "Cave spawner (female guards eggs and fry)", "sexing": "Males larger with red tail markings and long fins; females smaller, yellow when breeding", "group": "1 male to 2 or 3 females, each with her own cave", "breeding_tank": "20 gallons or more, caves, leaf litter, soft acidic water", "conditioning": "Live and frozen foods for 2 to 3 weeks", "trigger": "Soft acidic water around 80°F and water changes", "spawn": "Commonly 50 to 150 eggs", "eggs": "Hatch in about 2 to 3 days at around 80°F", "fry": "Free swimming about 7 to 9 days after spawning", "first_foods": "Baby brine shrimp, microworms and vinegar eels", "grow_out": "About 0.75 inch in 6 to 8 weeks", "parents": "Female guards fry; move fry before her next spawn"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works for a pair, with more room needed for a harem. Keep the water at 75 to 84°F, with about 80°F for spawning, pH 5 to 7 and GH 1 to 10. Softer, more acidic water within that range gives better egg survival.\n\nGive each female a cave, such as a coconut shell or clay cave, spaced apart with plants or wood in between. Add leaf litter and a sand bottom. Use a sponge filter so tiny fry are safe.\n\nDried leaves such as Indian almond leaves release tannins that soften and slightly acidify the water and give fry microscopic food to graze. Keep lighting moderate with some floating plants; a calm female is a better mother."}, {"heading": "Choosing and conditioning a group", "text": "Males grow to about 3 inches with long dorsal fin rays and red markings on the tail. Females are smaller and turn bright yellow with black markings when breeding.\n\nThis species is commonly kept as a harem of one male with two or three females. Condition for two to three weeks with live and frozen foods such as brine shrimp, daphnia, bloodworms and mosquito larvae. Keep the water soft and stable.\n\nSmall schooling dither fish such as pencilfish can help a shy pair feel safe, but keep them few, because they will eat free swimming fry. A dedicated tank for the group is easiest."}, {"heading": "Spawning: what you'll see", "text": "The female colors up and claims a cave, chasing others away. The male displays to her, and she lays eggs on the cave ceiling, commonly 50 to 150. After the spawn she guards the cave and may chase the male away.\n\nIn a harem, each female may spawn at a different time, so expect several broods in the same tank once things settle."}, {"heading": "Eggs and hatching", "text": "At about 80°F the eggs hatch in 2 to 3 days. The wrigglers stay in the cave for several more days. The female fans the eggs and removes any that go white with fungus.\n\nKeep the cave dark and undisturbed. Hard water and big swings in pH are common reasons eggs fail. If a young female eats her first clutch, leave her be; many do better the next time."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 7 to 9 days after spawning and follow their mother in a tight group. Week one: feed newly hatched baby brine shrimp, microworms and vinegar eels two or three times a day. Weeks two and three: keep up baby brine shrimp and add crushed flake. From week four, add chopped frozen foods.\n\nChange 10 to 20 percent of the water every two or three days with matched soft water, and keep the temperature at 78 to 82°F.\n\nSiphon leftover food daily. Dirty, warm water is the most common reason a healthy brood dwindles in its first two weeks."}, {"heading": "Growing out", "text": "Fry reach about three quarters of an inch in six to eight weeks. Move them to a grow out tank by about four weeks, especially in a harem where other females may attack a neighbor's fry.\n\nAs in other Apistogramma, very warm water is widely reported to produce mostly males, so raising fry around 79 to 81°F gives a better mix of sexes."}, {"heading": "Common mistakes", "text": "- Too few caves for the number of females\n- Hard water and unstable pH\n- Disturbing the cave in the first days\n- Fry left in a busy harem tank\n- Feeding fry dry food only\n- Expecting a pair to spawn in hard tap water without softening"}]$g$::jsonb, $g$[{"q": "Can Apistogramma macmasteri be kept as a harem?", "a": "Yes, one male with two or three females is common, as long as each female has her own cave and territory."}, {"q": "How long do Apistogramma macmasteri eggs take to hatch?", "a": "About 2 to 3 days at around 80°F, with free swimming fry about a week or so after spawning."}, {"q": "How do you sex Apistogramma macmasteri?", "a": "Males are larger with long fins and red tail markings. Females are smaller and turn yellow with black markings when ready to breed."}, {"q": "What do Apistogramma fry eat?", "a": "Newly hatched baby brine shrimp, microworms and vinegar eels, with crushed flake added after the first week or two."}]$g$::jsonb, $g$Photograph the male and his females with your challenge code card when you open the log. In a harem, record which female spawned so your stage photos follow the same brood.$g$),
  ($g$oscar$g$, $g$59203884-3a62-484f-ad23-d512e429406f$g$::uuid, $g$oscar$g$, null, $g$How to Breed Oscars: Pairing, Spawning and Raising Fry$g$, $g$Oscars lay huge clutches on flat stones and guard their fry, but need a big tank and a true pair. Learn sexing, setup, egg care and raising the fry.$g$, $g$Breeding oscars is mostly about space and patience. A bonded pair will lay a thousand or more eggs on a flat stone and guard the fry together, which is an impressive sight. The hard parts are getting a true pair, since oscars are very difficult to sex, and having the tank room and plan to deal with a huge number of fast growing fry.$g$, $g${"method": "Substrate spawner (open, on flat stones)", "sexing": "Very hard by looks; venting the breeding tubes at spawning is the only reliable method", "group": "One bonded pair, usually formed from a group of juveniles", "breeding_tank": "125 gallons or more for a pair, flat stones, sand, strong filtration", "conditioning": "Quality pellets plus frozen krill, earthworms and mysis for 3 to 4 weeks", "trigger": "Warming to about 78 to 80°F and large partial water changes", "spawn": "Commonly 1,000 to 2,000 eggs, sometimes more", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming roughly a week after spawning", "first_foods": "Baby brine shrimp and crushed flake or fry powder", "grow_out": "About 1 inch in 5 to 6 weeks; growth is fast with heavy feeding", "parents": "Both guard closely; young pairs often eat early clutches"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A single oscar needs at least 75 gallons, and a breeding pair needs more, ideally 125 gallons or larger. Keep the water at 74 to 81°F, with spawning usually at 78 to 80°F, pH 6 to 7.5 and GH 5 to 20.\n\nUse a sand bottom and add one or two large flat stones or slates, which pairs clean and spawn on. Keep decor sturdy, because oscars rearrange everything. Strong filtration and large weekly water changes are essential; oscars are heavy eaters and very messy, and poor water is the most common reason pairs fail to spawn."}, {"heading": "Choosing and conditioning a pair", "text": "Oscars cannot be reliably sexed by color or shape. Many claims, such as spots on the dorsal fin, do not hold up. The only sure method is to see the breeding tubes at spawning time: the female's is broad and blunt, the male's thinner and pointed.\n\nThe best way to get a pair is to raise five or six juveniles together and watch for two that stay close and defend an area. Most pairs first spawn at around a year or more old and roughly 6 inches or larger. Condition for three to four weeks with quality pellets plus frozen krill, mysis and earthworms."}, {"heading": "Spawning: what you'll see", "text": "A ready pair darkens, locks lips, tail slaps and digs. They spend days cleaning a flat stone. Then the female lays rows of eggs, commonly 1,000 to 2,000, with the male following to fertilize.\n\nThe pair becomes defensive and may bite a hand in the tank. Remove any other fish before spawning, or keep the pair alone. A large water change with slightly cooler water often triggers spawning in a conditioned pair."}, {"heading": "Eggs and hatching", "text": "Both parents fan the eggs and pick off any that turn white. At 78 to 80°F, eggs hatch in about 2 to 3 days. The parents move the wrigglers into pits dug in the sand.\n\nYoung pairs often eat their first few clutches. Give them a few attempts before stepping in. If they keep eating eggs, you can move the stone to a separate tank with water from the main tank, gentle aeration beside the eggs and a little methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming roughly a week after spawning. Week one: feed newly hatched baby brine shrimp four times a day. Weeks two and three: keep up brine shrimp and add crushed flake and fry powder. From week four, add crushed pellets and chopped frozen foods.\n\nWith so many fry, water quality falls fast. Change 30 percent of the water every two days and siphon leftover food. Keep the temperature at 78 to 80°F. Thin the numbers early if you cannot keep up, by moving part of the brood to another tank."}, {"heading": "Growing out", "text": "Oscar fry grow quickly, reaching about an inch in five or six weeks and 2 inches or more by two to three months with heavy feeding. Move them away from the parents at around a month, before the pair spawns again.\n\nSize sorting reduces fin nipping and stunting. Plan ahead for homes: a single spawn can produce hundreds of fish that each need a large tank as adults. Raising only part of a spawn is a sensible choice."}, {"heading": "Common mistakes", "text": "- Assuming two adults are a pair because of their color or shape\n- Too small a tank for a pair\n- Poor filtration and too few water changes\n- Leaving fry with the parents too long\n- Raising more fry than you can house or rehome\n- Hand feeding or working in the tank while the pair guards"}]$g$::jsonb, $g$[{"q": "How can you tell if an oscar is male or female?", "a": "It is very hard by looks. Checking the breeding tubes at spawning is the only reliable method."}, {"q": "How many eggs do oscars lay?", "a": "Commonly 1,000 to 2,000 eggs per spawn, and sometimes more from large females."}, {"q": "How long do oscar eggs take to hatch?", "a": "About 2 to 3 days at 78 to 80°F, with fry free swimming around a week after spawning."}, {"q": "Why do my oscars eat their eggs?", "a": "Young or stressed pairs often eat early clutches. Most pairs improve after a few spawns in a calm tank."}]$g$::jsonb, $g$Photograph your pair and the challenge code card together before the first spawn; a shot of the egg covered stone is clear stage 2 evidence. With hundreds of fry, the 60 day stage is about keeping up water changes, so plan tank space early.$g$),
  ($g$red-hump-geophagus$g$, $g$5d9b0c95-fba9-48b3-aca8-1ec5da8030d6$g$::uuid, $g$red-hump-geophagus$g$, null, $g$Breeding Red Hump Eartheaters (Geophagus steindachneri)$g$, $g$Red hump eartheaters are maternal mouthbrooders: the female carries eggs and fry for weeks. Learn harem setup, sexing, holding time and fry care.$g$, $g$The red hump eartheater is one of the few Geophagus that mouthbroods right away: the female picks up the eggs as soon as they are laid. Males with their red forehead humps are striking, and a harem breeds fairly readily. The work is in keeping water clean, giving the female peace while she holds, and raising the fry on good live foods.$g$, $g${"method": "Maternal mouthbrooder (female picks up eggs right away)", "sexing": "Males larger with a red forehead hump; females smaller with little or no hump", "group": "1 male to 3 or more females", "breeding_tank": "55 gallons or more, fine sand, flat stones, open swimming room", "conditioning": "Sinking pellets, frozen bloodworms and brine shrimp for 3 to 4 weeks", "trigger": "Stable warm water around 78 to 80°F and water changes", "spawn": "Commonly reported around 30 to 80 eggs, more from large females", "eggs": "Female holds eggs and fry about 2 to 3 weeks at 78 to 80°F", "fry": "Released free swimming and about a quarter inch; may return to the mouth for a few days", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Female guards fry briefly after release; move fry by about a week"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 55 gallon tank or larger works for one male with three or more females. Keep the water at 72 to 82°F, with breeding at about 78 to 80°F, pH 6.5 to 7.5 and GH 4 to 15.\n\nUse fine sand, because eartheaters sift it all day and coarse gravel can damage their mouths. Add a few flat stones and some rock or wood cover to break up lines of sight, but leave open sand in the middle. Strong filtration and regular water changes matter, since these fish are sensitive to rising nitrate.\n\nSmall, peaceful dither fish such as a school of tetras help the harem feel secure and bring out better color in the male. Avoid boisterous tankmates that compete hard at the bottom, where eartheaters feed."}, {"heading": "Choosing and conditioning a harem", "text": "Mature males are larger and develop a red forehead hump, which is brightest when they are dominant and breeding. Females are smaller with little or no hump. Juveniles are hard to sex, so many breeders raise a group of six to eight young and pick a male and females from them.\n\nKeep one male with at least three females so his attention is shared. Condition for three to four weeks with quality sinking pellets, frozen bloodworms, brine shrimp and mysis."}, {"heading": "Spawning: what you'll see", "text": "The male cleans a flat stone or a spot on the sand and displays to females with his hump flushed red. A ready female follows him and lays a few eggs at a time, then turns and picks them up in her mouth, while the male fertilizes them. Clutches are commonly reported around 30 to 80 eggs.\n\nAfter spawning, the female has a swollen throat and refuses food. She will hide and move away from the male."}, {"heading": "Holding the eggs and fry", "text": "The female holds the eggs and growing fry for roughly 2 to 3 weeks at 78 to 80°F. She eats little or nothing, so she needs to be in good condition before spawning.\n\nMost breeders move a holding female to a quiet 20 gallon tank after a few days, catching her gently with two nets to avoid her spitting. Others leave her in a well decorated harem tank. Avoid stripping fry early unless she is clearly losing condition; full term fry are stronger."}, {"heading": "Raising the fry", "text": "When released, fry are about a quarter inch and free swimming. They may dart back into the female's mouth for a few days. Week one: feed newly hatched baby brine shrimp three times a day. Weeks two and three: add crushed flake and micro pellets. From week four, add chopped frozen foods.\n\nKeep fry at 78 to 80°F with 20 to 30 percent water changes every two or three days. Return the female to the main tank after about a week, once she has fed and recovered."}, {"heading": "Growing out", "text": "Fry reach about an inch in six to eight weeks. Grow them on sand so they can sift naturally, with three or four small feedings a day. They are peaceful as juveniles and can be raised in a single group.\n\nBy three to four months, young males may start to show a small hump, which helps you pick future breeders.\n\nKeep the grow out tank on fine sand, feed sinking foods so the young can sift naturally, and change 30 percent of the water twice a week. Clean water is what keeps young Geophagus growing evenly."}, {"heading": "Common mistakes", "text": "- One female with an eager male, which wears her out\n- Coarse gravel instead of sand\n- Chasing a holding female with a net\n- Stripping fry too early\n- Letting nitrate build up"}]$g$::jsonb, $g$[{"q": "Is the red hump eartheater a mouthbrooder?", "a": "Yes. The female picks up the eggs right after they are laid and carries the eggs and fry in her mouth."}, {"q": "How long does a red hump Geophagus hold her fry?", "a": "Usually about 2 to 3 weeks at 78 to 80°F, then she releases free swimming fry."}, {"q": "How do you sex Geophagus steindachneri?", "a": "Males are larger with a red forehead hump. Females are smaller with little or no hump."}, {"q": "Should I keep one male with several females?", "a": "Yes. One male with three or more females spreads out his attention and reduces stress."}]$g$::jsonb, $g$Photograph the male and his females with your challenge code card before spawning; a clear photo of a holding female with a full throat works as stage 2 evidence. Log the release date carefully, since it sets the timing for stages 3 to 5.$g$),
  ($g$green-severum$g$, $g$09fce4c3-b04d-4525-a9e8-2be23eefdb01$g$::uuid, $g$green-severum$g$, null, $g$How to Breed Severums: Pairing, Spawning and Fry Guide$g$, $g$Severums spawn on flat stones and guard their fry together once a pair forms. Learn how to sex them, set up a breeding tank and raise the fry well.$g$, $g$Severums are big, gentle cichlids that make excellent parents once a pair forms. They lay hundreds of eggs on a flat stone or upright surface and both guard the fry. The main challenges are finding a true pair, since severums are slow to bond and often pick partners themselves, and keeping water clean for a big brood.$g$, $g${"method": "Substrate spawner (open, on stones or upright surfaces)", "sexing": "Males have red brown spots or worm lines on the face; females a plain face and often a dorsal spot", "group": "One pair, ideally formed from a group of juveniles", "breeding_tank": "55 gallons or more, flat stones or slate, sand and some plants", "conditioning": "Pellets with vegetable content plus frozen mysis and brine shrimp for 3 weeks", "trigger": "Warming to about 80 to 82°F, soft slightly acidic water and water changes", "spawn": "Commonly 200 to 1,000 eggs", "eggs": "Hatch in about 3 days at 80 to 82°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Both guard; young pairs may eat early clutches"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A pair needs a 55 gallon tank or larger. Keep the water at 73 to 84°F, with spawning usually at 80 to 82°F, and pH 6 to 7.5 with soft to moderate hardness. Slightly acidic water around pH 6.5 often gives the best hatch rates.\n\nAdd flat stones or slate on sand, and a piece of slate leaning against the glass, because severums often prefer upright surfaces. Some sturdy plants and driftwood make the pair feel secure. Good filtration and weekly water changes of 30 percent or more keep conditions right."}, {"heading": "Choosing and conditioning a pair", "text": "Adult males usually show red brown spots or worm like lines on the face and gill covers, and develop longer, pointed dorsal and anal fins. Females have a plain face and often a dark spot on the dorsal fin. These signs work best on adults; juveniles are hard to sex.\n\nSeverums are choosy, so the best route is to raise five or six juveniles and let a pair form. Condition the pair for about three weeks with quality pellets that include vegetable matter, plus frozen mysis, brine shrimp and some blanched greens."}, {"heading": "Spawning: what you'll see", "text": "The pair cleans a stone or slate for several days, often an upright one. They shake, tail slap and lock lips. The female then lays rows of eggs, commonly 200 to 1,000 depending on her size, and the male follows to fertilize.\n\nAfter spawning, both parents guard. They are calmer than many cichlids but will chase tankmates away from the eggs. Keep the tank quiet and avoid big changes until the fry are swimming.\n\nHealthy pairs often spawn every two to four weeks once settled. If a pair spawns but the eggs turn white within a day, the male may not be fertilizing, which is common in young males and usually improves."}, {"heading": "Eggs and hatching", "text": "At 80 to 82°F, eggs hatch in about 3 days. The parents fan the eggs and remove any that turn white with fungus. After hatching, they move the wrigglers to a pit in the sand or a different surface.\n\nYoung pairs often eat early clutches. Give them a few chances. If a pair keeps eating eggs, you can hatch the stone in a separate tank with matched water, an airstone beside the eggs and a little methylene blue to limit fungus."}, {"heading": "Raising the fry", "text": "Fry become free swimming about 4 to 6 days after hatching. Week one: feed newly hatched baby brine shrimp three or four times a day. Weeks two and three: add crushed flake and fry powder. From week four, add crushed pellets and chopped frozen foods.\n\nChange 20 to 30 percent of the water every two or three days and keep the temperature at 78 to 82°F. Siphon leftover food daily, as a big brood fouls water fast.\n\nThe parents often lead the school around the tank and pick up stragglers in their mouths to return them to the group. This is normal guarding, not eating."}, {"heading": "Growing out", "text": "Fry reach about an inch in six to eight weeks. Move them to their own tank at about a month, before the parents start a new spawn. Severums grow steadily with three or four feedings a day and clean water.\n\nMany fish sold as severums are actually other Heros species, so buy breeding stock from a source that knows what it has, and do not mix different Heros or color forms if you want to sell true fish."}, {"heading": "Common mistakes", "text": "- Forcing two adults together instead of letting a pair form\n- Hard, alkaline water for spawning\n- No upright surfaces\n- Leaving fry in with the parents too long\n- Skipping water changes during grow out"}]$g$::jsonb, $g$[{"q": "How can you tell male and female severums apart?", "a": "Adult males usually show red brown spots or worm lines on the face and longer fins. Females have a plain face and often a dark dorsal spot."}, {"q": "How many eggs do severums lay?", "a": "Commonly 200 to 1,000 eggs, with larger females laying more."}, {"q": "How long do severum eggs take to hatch?", "a": "About 3 days at 80 to 82°F, with fry swimming 4 to 6 days later."}, {"q": "Are severums good parents?", "a": "Yes. Once a pair is settled, both guard the eggs and fry together."}]$g$::jsonb, $g$Photograph your pair with the challenge code card when they start cleaning a stone; the egg covered surface makes great stage 2 evidence. Moving fry to their own tank at about a month keeps them growing well toward stage 5.$g$),
  ($g$bumblebee-goby$g$, $g$59038cf4-915e-428f-983b-24ba7ad7ea4f$g$::uuid, $g$bumblebee-goby$g$, null, $g$How to Breed Bumblebee Gobies: Caves, Eggs and Tiny Fry$g$, $g$Bumblebee gobies spawn in caves and the male guards the eggs, but the tiny fry are hard to raise. Learn setup, sexing, egg care and first foods.$g$, $g$Bumblebee gobies are tiny, characterful fish that will spawn in a small cave or shell, with the male guarding the eggs like a much larger cichlid. Getting a spawn is fairly easy in hard, slightly alkaline water. Raising the fry is the real test: they are very small and need microscopic live foods, so preparation matters.$g$, $g${"method": "Cave spawner (male guards eggs)", "sexing": "Males slimmer and often brighter; females rounder and plumper when full of eggs", "group": "A group of 6 or more with several caves", "breeding_tank": "10 to 20 gallons, small caves or shells, hard alkaline water", "conditioning": "Live and frozen foods (brine shrimp, daphnia, bloodworms) for 3 weeks", "trigger": "Good conditioning, warm stable water around 78 to 82°F", "spawn": "Breeders report about 100 to 200 eggs on the cave ceiling", "eggs": "Breeders report hatching in roughly 4 to 5 days at around 80°F", "fry": "Very small; need tiny live foods from the start", "first_foods": "Infusoria and rotifers, then baby brine shrimp after about a week", "grow_out": "About half an inch in 2 to 3 months; growth is slow", "parents": "Male guards eggs; remove fry or eggs after hatching as adults eat fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank suits a breeding group. Keep the water at 72 to 84°F, with spawning usually at about 78 to 82°F, pH 7 to 8.5 and GH 10 to 20. These fish come from coastal and brackish areas as well as freshwater; many breeders keep them in hard freshwater, and some add a small amount of marine salt for the adults.\n\nProvide several small caves, such as clay pots on their sides, short tubes or snail shells. Each male claims one. Use fine sand and a sponge filter to keep flow gentle.\n\nKeep tankmates out of the breeding tank. Bumblebee gobies are slow, shy feeders, and other fish will take the food before the gobies, leaving females poorly conditioned."}, {"heading": "Choosing and conditioning a group", "text": "Sexing is not always easy. Males are usually slimmer and may show brighter yellow and darker bands when breeding. Females are rounder, especially when carrying eggs. Buying a group of six or more is the easiest way to get both sexes.\n\nBumblebee gobies are picky eaters and often refuse flake. Feed live or frozen foods every day: baby brine shrimp, daphnia, cyclops and chopped bloodworms. Condition for about three weeks before expecting spawns."}, {"heading": "Spawning: what you'll see", "text": "A male guards his cave and displays to females with flared fins and stronger colors. A ripe female enters the cave and lays eggs on the ceiling. Breeders report around 100 to 200 eggs per spawn.\n\nThe male then stays in or near the cave, guarding and fanning. He becomes aggressive toward other fish that come close. You may only see his head at the entrance for several days."}, {"heading": "Eggs and hatching", "text": "Breeders report the eggs hatching in roughly 4 to 5 days at around 80°F. The eggs are small and attached to the cave surface. The male fans them and removes damaged eggs.\n\nAdults will eat the fry once they hatch, so many breeders move the cave with eggs to a separate small tank shortly before hatching. Match the temperature and water chemistry, add gentle aeration near the eggs, and keep the tank dim."}, {"heading": "Raising the fry", "text": "The fry are very small and many breeders find this the hardest stage. Week one: feed infusoria and rotifers several times a day. Some breeders report better survival with a small amount of salt in the fry tank, but keep any change gradual. Week two: start adding newly hatched baby brine shrimp. Weeks three and four: feed baby brine shrimp and microworms.\n\nKeep the fry at 78 to 82°F and change small amounts of water, 10 percent every day or two, with matched water. Keep cultures running before the spawn happens.\n\nStart an infusoria culture and a rotifer or green water culture a week or two before you expect a spawn. Without food ready on day one, most broods are lost."}, {"heading": "Growing out", "text": "Bumblebee goby fry grow slowly, reaching about half an inch in two to three months. They develop their banding as they grow. Feed small live and frozen foods several times a day and keep the water clean.\n\nAs juveniles get bigger, give them small caves of their own, because young males start defending territories early. Do not expect them to take flake; most keep preferring live and frozen foods.\n\nA small amount of fine algae and biofilm in the grow out tank helps, because fry graze between meals."}, {"heading": "Common mistakes", "text": "- Soft, acidic water\n- Expecting them to eat flake\n- Leaving fry in with adults\n- No microscopic foods ready for the fry\n- Too few caves for the males\n- Big, sudden changes in salinity or hardness"}]$g$::jsonb, $g$[{"q": "How do bumblebee gobies breed?", "a": "They are cave spawners. The female lays eggs on the roof of a small cave and the male guards them until they hatch."}, {"q": "How do you tell a male bumblebee goby from a female?", "a": "Males are usually slimmer and brighter when breeding. Females are rounder when full of eggs, but sexing is not always certain."}, {"q": "What do bumblebee goby fry eat?", "a": "Very small live foods like infusoria and rotifers at first, then baby brine shrimp after about a week."}, {"q": "Do bumblebee gobies need brackish water to breed?", "a": "Many breeders spawn them in hard freshwater. Some add a little salt, especially for fry, but sudden changes cause more harm than help."}]$g$::jsonb, $g$Photograph your group and the challenge code card before spawning; a photo of the male guarding his cave, or the eggs on the cave roof, is good stage 2 evidence. Fry are tiny, so use a magnifying lens or close up photo for stage 3.$g$),
  ($g$buffalohead-cichlid$g$, $g$7998e5d0-dd21-40dc-81f5-b81ab8137fa5$g$::uuid, $g$buffalohead-cichlid$g$, null, $g$How to Breed Buffalo Head Cichlids: Caves, Pairs and Fry$g$, $g$Buffalo head cichlids form lasting pairs, spawn in caves and guard fry for weeks. Learn sexing, flowing water setup, egg care and how to raise fry.$g$, $g$Buffalo head cichlids are rheophilic cichlids from the rapids of the Congo River, and they form loyal pairs that spawn in caves and guard their fry for weeks. They breed readily once a pair is settled, and watching the whole family hop along the bottom is a delight. Getting a compatible pair and giving them clean, well oxygenated water is the main work.$g$, $g${"method": "Cave spawner (both parents guard)", "sexing": "Males larger with a bigger forehead hump; females smaller with a small hump", "group": "One pair", "breeding_tank": "30 gallons or more, caves, rock piles, sand, good current and oxygen", "conditioning": "Pellets, frozen bloodworms, brine shrimp and some greens for 3 weeks", "trigger": "Settled pair, good current, stable water at about 78 to 80°F", "spawn": "Breeders report from a few dozen to over 100 eggs", "eggs": "Hatch in about 3 to 4 days at 78 to 80°F", "fry": "Free swimming about 7 to 10 days after spawning; stay near the bottom", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 8 weeks", "parents": "Both guard for weeks; move fry once the next spawn begins"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank works for a pair, with more space better if other fish share the tank. Keep the water at 75 to 82°F, with breeding around 78 to 80°F, pH 6.5 to 7.8 and GH 4 to 15.\n\nThese are river fish from fast water, so give good current and oxygen with a powerhead or strong filter. Build caves from rocks or use clay caves and flowerpots, set on sand so they can dig underneath. Buffalo heads spend most of their time on the bottom, so floor space matters more than height.\n\nKeep tankmates few and sturdy. A breeding pair defends a surprisingly large area for its size and will bully timid fish, so a species tank is simplest. Make sure the lid is tight, as startled fish can jump."}, {"heading": "Choosing and conditioning a pair", "text": "Adult males are larger, with a more pronounced forehead hump. Females are smaller with a less obvious hump. Juveniles are hard to sex, so start with five or six young fish and let a pair form.\n\nOnce a pair bonds, they usually stay together for life. Remove the rest of the group to avoid trouble. Condition for three weeks with quality pellets, frozen bloodworms, brine shrimp and some vegetable matter.\n\nIf you buy an adult pair, check they are both healthy and eating well, and watch closely for the first week. Mismatched fish can fight hard, and one may need to be removed."}, {"heading": "Spawning: what you'll see", "text": "The pair claims a cave and digs out sand from underneath or around it. They become more territorial and chase other fish from the area. The female lays eggs inside the cave, with breeders reporting from a few dozen to over 100 eggs.\n\nBoth parents guard the cave, and you may see little of them for several days. They are dedicated parents, so leave them in peace."}, {"heading": "Eggs and hatching", "text": "At 78 to 80°F, eggs hatch in about 3 to 4 days. The parents fan and clean the eggs, removing any that turn white. The wrigglers stay in the cave while they use up their yolk.\n\nKeep the cave undisturbed and the water clean. Pairs rarely eat eggs once settled, so artificial hatching is seldom needed."}, {"heading": "Raising the fry", "text": "Fry become free swimming roughly 7 to 10 days after spawning. Like their parents, they hop along the bottom rather than swim in open water. Week one: feed newly hatched baby brine shrimp two or three times a day, letting some sink. Weeks two and three: add crushed flake and micro pellets. From week four, add chopped frozen foods.\n\nKeep the temperature around 78°F and change 20 to 30 percent of the water every two or three days, matching temperature and hardness.\n\nSiphon leftover food every day, because it collects around the caves where the fry live. Good flow and oxygen help the fry as much as the adults."}, {"heading": "Growing out", "text": "Fry reach about an inch in eight weeks. The parents guard them for weeks, but move the fry out once the pair begins preparing another spawn, as they may then drive the older fry away.\n\nGrow juveniles in a tank with plenty of small caves and sand. They do best with clean, well oxygenated water and three or four feedings a day.\n\nYoung buffalo heads are slow to show their sex. Raise a group to five or six months before choosing your next breeding pair."}, {"heading": "Common mistakes", "text": "- Weak current and low oxygen\n- No caves set on sand for digging\n- Forcing two adults together instead of letting a pair form\n- Leaving older fry with parents during the next spawn\n- Feeding only floating foods"}]$g$::jsonb, $g$[{"q": "Are buffalo head cichlids cave spawners?", "a": "Yes. The pair spawns inside a cave and both parents guard the eggs and fry."}, {"q": "How can you tell a male buffalo head from a female?", "a": "Adult males are larger with a bigger forehead hump. Females are smaller with a smaller hump."}, {"q": "Do buffalo head cichlids stay paired?", "a": "Yes. Once they bond, pairs usually stay together and spawn repeatedly."}, {"q": "Do buffalo head cichlids need current?", "a": "They come from rapids, so moderate current and high oxygen help them stay healthy and breed."}]$g$::jsonb, $g$Photograph the pair with your challenge code card near their cave before the spawn. The fry hop along the bottom, so a photo of the family outside the cave makes clear stage 3 evidence.$g$),
  ($g$demasoni-cichlid$g$, $g$3bc606e4-5fc7-457b-831a-984743658e3b$g$::uuid, $g$demasoni-cichlid$g$, null, $g$How to Breed Demasoni Cichlids: Colony Setup and Holding$g$, $g$Demasoni are mouthbrooding mbuna that need a crowded colony to curb aggression. Learn sexing, holding times, small clutch sizes and how to raise fry.$g$, $g$Demasoni are small, intensely blue mbuna from Lake Malawi, and the females carry eggs and fry in their mouths for about three weeks. They breed readily, but they are famously aggressive toward each other, so success depends on a crowded colony with plenty of rock. Clutches are small, which makes every brood count.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Very hard; both sexes look alike; males often larger with more egg spots; venting is surest", "group": "Colony of 12 or more, ideally more females than males", "breeding_tank": "55 gallons or more, lots of rockwork with caves, hard alkaline water", "conditioning": "Spirulina and vegetable based foods; avoid rich meaty foods", "trigger": "Stable water, a settled colony and good diet", "spawn": "Small clutches, commonly about 10 to 20 eggs", "eggs": "Female holds about 3 weeks at 78 to 80°F", "fry": "Released free swimming and about a third of an inch", "first_foods": "Crushed spirulina flake and baby brine shrimp", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "No care after release; adults eat fry, so move them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 55 gallon tank or larger and fill much of it with rockwork that forms caves and crevices. Keep the water at 75 to 82°F, with breeding usually around 78 to 80°F, pH 7.6 to 8.8 and GH 10 to 25. Lake Malawi water is hard and stable, so avoid swings.\n\nDemasoni are very territorial. A crowded tank with lots of rock, and a colony of 12 or more fish, spreads aggression so no single fish is targeted. Strong filtration and weekly water changes are needed for the high stocking."}, {"heading": "Choosing and conditioning a colony", "text": "Sexing demasoni is difficult. Both sexes are the same blue and black barred pattern. Males are often larger and may have more egg spots, but this is not reliable. Venting is the most accurate method.\n\nMost breeders buy a group of 12 or more juveniles and let them sort out. Aim for more females than males over time. Feed spirulina based flake and pellets and other vegetable rich foods. Too much rich, meaty food can cause bloat in mbuna, so keep protein foods as an occasional treat."}, {"heading": "Spawning: what you'll see", "text": "A male claims a cave or flat rock and displays to females with shaking and quivering. A ripe female follows him, lays a few eggs, and picks them up in her mouth, then nips at the male's anal fin egg spots, which fertilizes the eggs in her mouth. This repeats until she has her clutch, commonly about 10 to 20 eggs.\n\nAfterwards she has a swollen throat and stops eating. She will hide among the rocks."}, {"heading": "Holding the eggs and fry", "text": "The female holds the eggs and growing fry for about three weeks at 78 to 80°F. She eats little or nothing during this time.\n\nYou can leave her in the colony with plenty of rocks, but many fry are eaten after release. Most breeders move a holding female to a separate 20 gallon tank after about a week, catching her gently. Some strip the fry at about two weeks, but full term release is easier on the fry. Return her to the colony once she has recovered, but expect some aggression, so add her back after rearranging rocks.\n\nNever squeeze a female or force her mouth open hard. If you strip fry, hold her gently in a wet net underwater and let them fall out, and only after about two weeks."}, {"heading": "Raising the fry", "text": "When released, fry are about a third of an inch and free swimming. Week one: feed crushed spirulina flake and baby brine shrimp three times a day. Weeks two and three: add crushed pellets. From week four, feed small pellets and flake.\n\nKeep fry at 78°F with 20 to 30 percent water changes twice a week. Fry are peaceful at first, but even young demasoni start to squabble within a few weeks."}, {"heading": "Growing out", "text": "Fry reach about an inch in eight to ten weeks. Raise them in a tank with plenty of small rocks and caves. As they grow, aggression builds, so a large group grows up better than a small one.\n\nKeep the diet mostly vegetable based and avoid overfeeding. Clean water and a good diet give strong, well colored fish.\n\nMany breeders move young demasoni into the main colony once they are about an inch and a half, so they join a large group rather than being picked on as newcomers."}, {"heading": "Common mistakes", "text": "- Keeping only a few demasoni, which leads to one being bullied to death\n- Too little rockwork\n- Rich, meaty diets that cause bloat\n- Netting a holding female roughly\n- Mixing with similar looking mbuna that may hybridize"}]$g$::jsonb, $g$[{"q": "How long do demasoni hold their eggs?", "a": "Females hold eggs and fry for about three weeks at 78 to 80°F."}, {"q": "How many fry do demasoni have?", "a": "Clutches are small, commonly about 10 to 20 fry."}, {"q": "How do you tell male and female demasoni apart?", "a": "It is hard by looks. Males are often larger with more egg spots, but venting is the most accurate method."}, {"q": "Why are demasoni so aggressive?", "a": "They are highly territorial. Keeping a crowded colony of 12 or more with lots of rock spreads aggression around."}]$g$::jsonb, $g$Photograph your colony and the challenge code card before spawning; a holding female with a full throat is good stage 2 evidence. Because clutches are small, move the female to a fry tank so you keep enough young for every stage.$g$),
  ($g$electric-blue-hap$g$, $g$78c720e8-94eb-4c8a-88e9-d850a3ab9967$g$::uuid, $g$electric-blue-hap$g$, null, $g$How to Breed Electric Blue Haps (Sciaenochromis fryeri)$g$, $g$Electric blue haps are maternal mouthbrooders from Lake Malawi. Learn harem setup, sexing, holding time and how to raise and grow out the young fry.$g$, $g$The electric blue hap is a striking predatory cichlid from Lake Malawi. Males are bright blue with a white edge on the dorsal fin, and females are silver to gray. Breeding is fairly straightforward with a harem setup, and females hold eggs and fry for about three weeks. The main work is giving them space and keeping water stable.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Males bright blue with a white edged dorsal; females silver to gray", "group": "1 male to 3 or 4 females", "breeding_tank": "75 gallons or more, open swimming space, rocks and sand, hard alkaline water", "conditioning": "Quality pellets plus frozen mysis and krill for 3 to 4 weeks", "trigger": "A settled harem, stable water and good feeding", "spawn": "Commonly 20 to 60 eggs, more from large females", "eggs": "Female holds about 3 weeks at 78 to 80°F", "fry": "Released free swimming at about a third of an inch", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "No care after release; adults eat fry, so move them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 75 gallon tank or larger works for one male with three or four females. Keep the water at 76 to 82°F, with breeding around 78 to 80°F, pH 7.8 to 8.6 and GH 10 to 25.\n\nUse sand and rockwork along the back, with open swimming space in front. Electric blues are open water hunters, so they need room to swim. Strong filtration and weekly water changes of 30 percent or more keep conditions stable.\n\nChoose tankmates carefully. Other Malawi haps, especially similar looking species, can hybridize with electric blues, so a species tank or a tank with unrelated mbuna is safest. Smaller fish that fit in an adult's mouth will be eaten."}, {"heading": "Choosing and conditioning a harem", "text": "Adult males are a bright, even blue with a white edge on the dorsal fin. Females are silver to gray and much less colorful. Juveniles are gray and hard to sex, so breeders often raise a group and keep one male with three or four females.\n\nCondition for three to four weeks with quality pellets and frozen mysis, krill and brine shrimp. These are carnivores, but a good pellet keeps them healthy. Do not overfeed, as uneaten food fouls the water.\n\nA single female in a tank with a male is often chased to exhaustion. Three or more females spread his attention and keep the colony calmer."}, {"heading": "Spawning: what you'll see", "text": "The male darkens to a deep blue and displays to a ripe female, shaking and leading her to a spot on the sand or a flat rock. She lays a few eggs, picks them up in her mouth, and nips at his anal fin where he releases milt. This repeats until she has a clutch, commonly 20 to 60 eggs.\n\nAfterwards she has a swollen throat and stops eating, often hiding near the rocks."}, {"heading": "Holding the eggs and fry", "text": "The female holds the eggs and fry for about three weeks at 78 to 80°F, eating little or nothing. Many breeders move her to a separate 20 to 30 gallon tank after a few days, catching her gently to avoid spitting.\n\nSome breeders strip fry at about two weeks, but full term release gives stronger fry. After release, give her a week to feed and recover before returning her to the harem."}, {"heading": "Raising the fry", "text": "Released fry are about a third of an inch and free swimming. Week one: feed newly hatched baby brine shrimp and crushed flake three times a day. Weeks two and three: add crushed pellets. From week four, add chopped frozen foods.\n\nKeep fry at 78 to 80°F and change 20 to 30 percent of the water twice a week. Fry are peaceful at first and can be raised together.\n\nSiphon leftover food every day and avoid overfeeding. Fry grow best on several small meals rather than one big one."}, {"heading": "Growing out", "text": "Fry reach about an inch in six to eight weeks. Males start to show blue color at a few months old. Grow them in a tank with plenty of swimming space and some rockwork.\n\nAs they grow, males become more territorial, so give enough space and size sort if needed. Feed several small meals a day and keep the water clean.\n\nPlan homes for your young fish early. Males take several months to show full blue, so many buyers prefer juveniles that are already 2 to 3 inches long."}, {"heading": "Common mistakes", "text": "- Too small a tank for this open water hunter\n- One female with a male, which stresses her\n- Overfeeding and poor water quality\n- Netting a holding female roughly\n- Keeping with other haps that may hybridize"}]$g$::jsonb, $g$[{"q": "How long do electric blue haps hold their eggs?", "a": "Females hold eggs and fry for about three weeks at 78 to 80°F."}, {"q": "How do you tell male and female electric blue haps apart?", "a": "Males are bright blue with a white edged dorsal fin. Females are silver to gray."}, {"q": "How many fry do electric blue haps have?", "a": "Clutches are commonly 20 to 60 eggs, with larger females producing more."}, {"q": "Will electric blue haps eat their fry?", "a": "Yes, adults will eat fry after release. Move the holding female or fry to a separate tank."}]$g$::jsonb, $g$Photograph your male and females with the challenge code card before spawning; a holding female with a full throat is good stage 2 evidence. Log the release date carefully for stage 3.$g$),
  ($g$jacobfreibergi-peacock$g$, $g$80d15d59-5398-4925-8ab7-b44fc950a708$g$::uuid, null, null, $g$How to Breed Aulonocara jacobfreibergi Peacock Cichlids$g$, $g$Jacobfreibergi peacocks are maternal mouthbrooders from Lake Malawi. Learn harem setup, sexing, holding time, avoiding hybrids and raising the fry.$g$, $g$Aulonocara jacobfreibergi is a peacock cichlid from Lake Malawi, and males show stunning blue and yellow colors with long fins. Females carry eggs and fry for about three to four weeks. They breed fairly readily in a harem, but the real work is keeping the line pure, since peacocks easily hybridize with each other.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Males colorful with long fins; females brown to gray with plain fins", "group": "1 male to 3 or 4 females", "breeding_tank": "55 gallons or more, caves and rock, sand, hard alkaline water", "conditioning": "Quality pellets plus frozen mysis and brine shrimp for 3 to 4 weeks", "trigger": "A settled harem, stable water and good feeding", "spawn": "Commonly 15 to 50 eggs", "eggs": "Female holds about 3 to 4 weeks at 78 to 80°F", "fry": "Released free swimming at about a third of an inch", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "No care after release; adults eat fry, so move them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 55 gallon tank or larger works for one male with three or four females. Keep the water at about 76 to 82°F, with breeding around 78 to 80°F, pH around 7.8 to 8.6 and hard water.\n\nThis species often spawns in or near caves, so provide rockwork with caves, plus open sand for swimming. Strong filtration and weekly water changes of 30 percent or more keep conditions stable.\n\nPeacocks do best with peaceful tankmates. Avoid aggressive mbuna, which bully peacocks and stress holding females. Lighting should be moderate, with caves that give females a place to retreat. A tight lid is a good idea, as startled fish can jump."}, {"heading": "Choosing and conditioning a harem", "text": "Males are brightly colored, usually blue with yellow or orange, and have long, pointed fins. Females are brown to gray with plain fins. Juveniles look like females, so males only become clear as they mature.\n\nKeep one male with three or four females. Avoid keeping other Aulonocara females in the tank, because peacock species interbreed easily. Condition for three to four weeks with quality pellets and frozen mysis and brine shrimp.\n\nBuy breeding stock from a source that keeps the species pure and can tell you the collection point or line. Many peacocks in shops are hybrids or mixed strains, which should not be sold as jacobfreibergi."}, {"heading": "Spawning: what you'll see", "text": "The male displays to a ripe female, often near a cave, shaking and showing his fins. She lays a few eggs, picks them up, and nips at his anal fin to fertilize them. This repeats until she has a clutch, commonly 15 to 50 eggs.\n\nAfterwards she has a swollen throat and stops eating. She will hide in the rocks."}, {"heading": "Holding the eggs and fry", "text": "The female holds eggs and fry for about three to four weeks at 78 to 80°F. She eats little or nothing during this time.\n\nMany breeders move a holding female to a separate tank after a few days, catching her gently. Some strip fry at about two weeks, but full term release gives stronger fry. After release, give her a week to recover before returning her to the harem.\n\nNever squeeze a female or force her mouth open. If you strip fry, hold her gently in a wet net underwater and let them fall out."}, {"heading": "Raising the fry", "text": "Released fry are about a third of an inch and free swimming. Week one: feed newly hatched baby brine shrimp and crushed flake three times a day. Weeks two and three: add crushed pellets. From week four, add chopped frozen foods.\n\nKeep fry at 78 to 80°F and change 20 to 30 percent of the water twice a week. Fry are peaceful at first.\n\nSiphon leftover food every day and avoid overfeeding. Fry grow best on several small meals rather than one big one."}, {"heading": "Growing out", "text": "Fry reach about an inch in six to eight weeks. Males start showing color at a few months old, though full color takes much longer.\n\nAs young males mature, they become territorial, so give enough space and rockwork. Feed several small meals a day and keep the water clean.\n\nMany buyers prefer juveniles of 2 to 3 inches, when young males start to show some color. Size sort if needed to keep the smaller fish eating well."}, {"heading": "Common mistakes", "text": "- Keeping other peacock females in the tank, which leads to hybrids\n- One female with a male, which stresses her\n- Overfeeding and poor water quality\n- Netting a holding female roughly\n- Selling fry without knowing the parents are pure"}]$g$::jsonb, $g$[{"q": "How long do peacock cichlids hold their eggs?", "a": "Females typically hold eggs and fry for about three to four weeks at 78 to 80°F."}, {"q": "How do you sex Aulonocara jacobfreibergi?", "a": "Males are brightly colored with long fins. Females are brown to gray with plain fins."}, {"q": "Will peacock cichlids hybridize?", "a": "Yes. Peacock species interbreed easily, so keep only one species of Aulonocara females in a breeding tank."}, {"q": "Do peacock cichlids eat their fry?", "a": "Adults will eat fry after release. Move the holding female or fry to a separate tank."}]$g$::jsonb, $g$Photograph your male and females with the challenge code card before spawning; a holding female with a full throat is good stage 2 evidence. Keep the breeding tank free of other peacocks so your fry are pure.$g$),
  ($g$livingstoni-cichlid$g$, $g$a12b8892-bbaa-4317-8682-20ea5b971a65$g$::uuid, $g$livingstoni-cichlid$g$, null, $g$How to Breed Livingstonii Cichlids: Harem and Mouthbrooding$g$, $g$Livingstonii are large mouthbrooding predators from Lake Malawi. Learn the big harem setup, sexing, holding time and how to raise and grow out fry.$g$, $g$Nimbochromis livingstonii is a large ambush predator from Lake Malawi, famous for lying on its side to lure prey. Females carry big clutches in their mouths for about three weeks. Breeding is fairly straightforward once you have a harem in a large tank, but these fish need plenty of space and good water to thrive.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Males develop blue on the head and fins; females keep the blotched brown pattern", "group": "1 male to 3 or more females", "breeding_tank": "100 gallons or more, rocks and sand, open swimming space", "conditioning": "Quality pellets plus frozen krill and mysis for 3 to 4 weeks", "trigger": "A settled harem, stable water and good feeding", "spawn": "Commonly 30 to 100 eggs, more from large females", "eggs": "Female holds about 3 weeks at 78 to 80°F", "fry": "Released free swimming at about a third of an inch", "first_foods": "Baby brine shrimp and crushed flake", "grow_out": "About 1 inch in 6 to 8 weeks; growth is fast", "parents": "No care after release; adults eat fry, so move them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Livingstonii grow to about 9 inches, so a harem needs at least 100 gallons. Keep the water at 76 to 82°F, with breeding around 78 to 80°F, pH 7.6 to 8.6 and GH 6 to 15.\n\nUse sand with rockwork at the back and sides, leaving open swimming room. Strong filtration and weekly water changes of 30 to 40 percent are needed, because large predators produce a lot of waste.\n\nChoose tankmates carefully. Livingstonii eat any fish small enough to fit in their mouths, and they can hybridize with related haps such as Nimbochromis venustus. A tank with only livingstonii, or with large unrelated fish, is safest."}, {"heading": "Choosing and conditioning a harem", "text": "Mature males develop blue on the head and fins, and the blotched brown pattern fades in breeding males. Females keep the blotched pattern and are usually smaller. Juveniles all look alike, so breeders often grow out a group.\n\nKeep one male with three or more females. Condition for three to four weeks with quality pellets and frozen krill, mysis and some vegetable matter. Avoid feeder fish, which can bring in disease.\n\nA single female with a male is often chased hard. Three or more females spread his attention and keep the harem calmer."}, {"heading": "Spawning: what you'll see", "text": "The male colors up and displays to a ripe female, leading her to a cleaned spot on the sand or a flat rock. She lays a few eggs, picks them up, and the male fertilizes them as she nips near his anal fin. This repeats until she has a clutch, commonly 30 to 100 eggs.\n\nAfterwards she has a full throat and stops eating, often hiding near rocks."}, {"heading": "Holding the eggs and fry", "text": "The female holds eggs and fry for about three weeks at 78 to 80°F, eating little or nothing. Many breeders move a holding female to a separate 30 to 40 gallon tank after a few days, catching her gently.\n\nSome strip the fry at around two weeks, but full term release gives stronger fry. Give her a week to feed and recover before she goes back to the harem.\n\nNever squeeze a female or force her mouth open. If you strip fry, hold her gently in a wet net underwater and let them fall out."}, {"heading": "Raising the fry", "text": "Released fry are about a third of an inch and free swimming. Week one: feed newly hatched baby brine shrimp and crushed flake three times a day. Weeks two and three: add crushed pellets. From week four, add chopped frozen foods.\n\nKeep fry at 78 to 80°F and change 20 to 30 percent of the water twice a week. Fry are peaceful at first.\n\nSiphon leftover food every day and avoid overfeeding. Fry grow best on several small meals rather than one big one."}, {"heading": "Growing out", "text": "Fry grow fast with heavy feeding, reaching about an inch in six to eight weeks. As they grow, give them plenty of room and good filtration.\n\nPlan for space: large clutches of a fish that reaches 9 inches need big tanks as they grow. Size sort as needed to reduce bullying.\n\nMany buyers prefer juveniles of 2 to 3 inches. Feed three or four small meals a day and change 30 percent of the water twice a week."}, {"heading": "Common mistakes", "text": "- Too small a tank for a 9 inch predator\n- Feeding feeder fish\n- One female with a male\n- Netting a holding female roughly\n- Mixing with Nimbochromis venustus or other haps that may hybridize"}]$g$::jsonb, $g$[{"q": "How long do livingstonii hold their eggs?", "a": "Females hold eggs and fry for about three weeks at 78 to 80°F."}, {"q": "How do you sex Nimbochromis livingstonii?", "a": "Mature males show blue on the head and fins, while females keep the blotched brown pattern."}, {"q": "How big a tank do livingstonii need for breeding?", "a": "A harem needs at least 100 gallons, because adults reach about 9 inches."}, {"q": "Do livingstonii eat their fry?", "a": "Adults will eat fry after release. Move the holding female or fry to a separate tank."}]$g$::jsonb, $g$Photograph your male and females with the challenge code card before spawning; a holding female is good stage 2 evidence. With big clutches, plan your grow out space well before stage 5.$g$),
  ($g$masked-julie$g$, $g$ca4e9ff0-2496-458e-87a1-d7dc4b16dfe2$g$::uuid, null, null, $g$How to Breed Masked Julies (Julidochromis transcriptus)$g$, $g$Masked julies are Tanganyikan cave spawners that raise fry among the rocks for weeks. Learn how to form a pair, setup, egg timing and fry care.$g$, $g$The masked julie is a small cichlid from Lake Tanganyika that spawns in rocky caves and lets several generations of fry live together in the rockwork. Breeding is fairly straightforward once a pair forms, but forming that pair can be the tricky part, as julies are picky and can fight. A well settled pair will spawn every few weeks.$g$, $g${"method": "Cave spawner (both parents guard)", "sexing": "Hard; females usually larger and heavier; venting at spawning is surest", "group": "One pair, ideally formed from a group of juveniles", "breeding_tank": "20 gallons long or more, rock piles with crevices, hard alkaline water", "conditioning": "Quality flake and frozen brine shrimp, mysis and daphnia for 3 weeks", "trigger": "A settled pair, stable hard water at about 77 to 80°F", "spawn": "Small clutches, commonly 20 to 50 eggs", "eggs": "Hatch in about 3 days at 77 to 80°F", "fry": "Free swimming roughly 7 to 10 days after spawning; stay in the rocks", "first_foods": "Baby brine shrimp, microworms and crushed flake", "grow_out": "About half an inch in 6 to 8 weeks; growth is slow", "parents": "Both guard; earlier broods usually tolerated, but move them if harassed"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long tank or larger works for a pair. Keep the water at 75 to 80°F, with spawning usually around 77 to 80°F, pH 8 to 9 and hard water.\n\nBuild rock piles with lots of narrow crevices and caves. Julies spawn deep in the rocks and fry hide there for weeks. Use sand or fine gravel and a sponge filter to keep the tiny fry safe. Lake Tanganyika water is very stable, so avoid swings.\n\nKeep tankmates few. A pair defends its rock pile hard, and other fish may eat fry that wander out. Some breeders use a few small Tanganyikan dither fish, but a species tank is simplest."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing masked julies is hard. Females are usually a bit larger and heavier, but this is not reliable. Venting at spawning is the surest check.\n\nThe best way to get a pair is to raise five or six juveniles together and let two pair off. Once a pair forms, move the others out. Condition for three weeks with quality flake and frozen brine shrimp, mysis and daphnia.\n\nIf you buy an adult pair, watch them closely for the first week. Mismatched julies can fight hard, and one may need to be removed."}, {"heading": "Spawning: what you'll see", "text": "The pair claims a crevice deep in the rocks. They chase other fish away and stay close to the cave. The female lays eggs on the cave wall or ceiling, commonly 20 to 50, and the male fertilizes them.\n\nYou may see very little of the spawning itself, as it happens deep in the rocks. Increased guarding and both fish staying near one spot are good signs."}, {"heading": "Eggs and hatching", "text": "At 77 to 80°F, eggs hatch in about 3 days. The parents fan and clean them. The wrigglers stay in the cave while they use up their yolk.\n\nKeep the rocks undisturbed. Settled pairs rarely eat eggs, so artificial hatching is usually not needed.\n\nAvoid moving rocks or doing heavy cleaning near the cave during the first two weeks."}, {"heading": "Raising the fry", "text": "Fry become free swimming roughly 7 to 10 days after spawning. They stay in and around the rocks, grazing and picking at food. Week one: feed newly hatched baby brine shrimp and microworms, letting some reach the rocks. Weeks two and three: add crushed flake. From week four, add chopped frozen foods.\n\nKeep fry at 77 to 80°F and change 15 to 20 percent of the water twice a week, matching temperature and hardness.\n\nSiphon leftover food every day, as it collects in the rocks. Clean, stable, hard water is what keeps the fry growing."}, {"heading": "Growing out", "text": "Masked julie fry grow slowly, reaching about half an inch in six to eight weeks. The parents usually tolerate older broods, so you may see several sizes of fry living in the rocks.\n\nIf the parents start chasing older fry, move them to a grow out tank with plenty of small rocks. Feed several small meals a day.\n\nYoung julies take several months to reach adult size. Raise a group of five or six together if you want a future breeding pair."}, {"heading": "Common mistakes", "text": "- Forcing two adults together instead of letting a pair form\n- Too few rocks and crevices\n- Soft or acidic water\n- Large sudden water changes\n- Leaving older fry when the parents begin chasing them\n- Keeping other Julidochromis that may hybridize"}]$g$::jsonb, $g$[{"q": "How do you sex masked julies?", "a": "It is hard by looks. Females are usually larger and heavier, but venting at spawning is the most reliable method."}, {"q": "How many eggs do masked julies lay?", "a": "Clutches are small, commonly 20 to 50 eggs."}, {"q": "Do masked julies eat their fry?", "a": "Settled pairs usually guard and tolerate fry, even older broods, but may chase older fry when spawning again."}, {"q": "How long do masked julie eggs take to hatch?", "a": "About 3 days at 77 to 80°F, with fry free swimming about 7 to 10 days after spawning."}]$g$::jsonb, $g$Photograph your pair with the challenge code card near their rock pile before spawning. Fry hide deep in the rocks, so a flashlight photo of them at the cave entrance can serve for stage 3.$g$)
) as v(slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
-- Only link a points row that still exists.
left join public.club_award_species a on a.id = v.award_species_id
on conflict (slug) do update set
  award_species_id = excluded.award_species_id,
  species_slug = excluded.species_slug,
  glossary_slug = excluded.glossary_slug,
  seo_title = excluded.seo_title,
  summary = excluded.summary,
  intro = excluded.intro,
  facts = excluded.facts,
  sections = excluded.sections,
  faq = excluded.faq,
  society_tip = excluded.society_tip,
  updated_at = now();

